              <input type="text" value={desc} onChange={e => setDesc(e.target.value)} placeholder="비고/연락처" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" />
