              {products.map(p => (
                <div key={p.id} className="flex justify-between items-center p-3 bg-slate-50 border border-slate-200 rounded-xl group">
                  <div><div className="font-bold text-sm text-slate-800">{p.name}</div><div className="text-[10px] font-bold text-blue-600">단축어: {p.shortcut} | 박스당 {p.unitsPerBox}개</div></div>
                  <button onClick={() => remove(p.id)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash className="w-4 h-4" /></button>
