            <div className="space-y-3">
              <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="품목 명 (예: 사과 박스)" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              <input type="text" value={shortcut} onChange={e => setShortcut(e.target.value)} placeholder="단축어 (예: A)" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              <div><label className="text-[10px] font-bold text-slate-400 ml-1">박스 내품 수량 (박스당 몇 개인가요?)</label><input type="number" value={units} onChange={e => setUnits(parseInt(e.target.value))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" /></div>
              <button onClick={add} className="w-full bg-slate-900 text-white py-3 rounded-xl font-bold hover:bg-slate-800 transition-colors shadow-lg">추가하기</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

