              <button onClick={save} className={`w-full text-white py-3 rounded-xl font-bold transition-colors shadow-lg ${editingId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-900 hover:bg-slate-800'}`}>{editingId ? '수정 저장' : '추가하기'}</button>
