const OrderModal: React.FC<{ 
  onClose: () => void, 
  onSubmit: (c: string, i: string) => void, 
  selectedDate: string, 
  products: ProductDefinition[], 
  clients: ClientDefinition[],
  onOpenProductManager: () => void,
  onOpenClientManager: () => void
}> = ({ onClose, onSubmit, selectedDate, products, clients, onOpenProductManager, onOpenClientManager }) => {
  const [client, setClient] = useState('');
  const [items, setItems] = useState('');
  const [registrationPrompt, setRegistrationPrompt] = useState<{ type: 'client' | 'product', missing: string } | null>(null);

  const clientInputRef = useRef<HTMLInputElement>(null);
  const itemsInputRef = useRef<HTMLTextAreaElement>(null);

  const filteredClients = useMemo(() => {
    const term = client.trim().toLowerCase();
    if (!term) return [];
    return clients.filter(c => 
      c.name.toLowerCase().includes(term) || 
      (c.shortcut && c.shortcut.toLowerCase().includes(term))
    );
  }, [client, clients]);

  const handleInitialSubmit = () => {
    if (!client || !items) return;

    let targetClientName = client;
    const trimmedClient = client.trim();

    // 1. 정확한 거래처명 일치 확인
    const exactNameMatch = clients.find(c => c.name === trimmedClient);

    if (exactNameMatch) {
      targetClientName = exactNameMatch.name;
    } else {
      // 2. 정확한 단축어 일치 확인
      const exactShortcutMatch = clients.find(c => c.shortcut === trimmedClient);
      if (exactShortcutMatch) {
        targetClientName = exactShortcutMatch.name;
      } else {
        // 3. 부분 일치가 1개뿐인 경우 자동 설정
        const partialMatches = clients.filter(c => c.name.includes(trimmedClient));
        if (partialMatches.length === 1) {
          targetClientName = partialMatches[0].name;
        } else {
          setRegistrationPrompt({ type: 'client', missing: client });
          return;
        }
      }
    }

    const parts = items.split(/[\s,]+/).map(p => p.trim()).filter(p => p !== "");
    for (const part of parts) {
      // 정규식 수정: [단축어][수량]
      const match = part.match(/^([a-zA-Z가-힣]+)(\d+)$/);
      if (match) {
        const sc = match[1].toUpperCase();
        if (!products.some(p => p.shortcut.toUpperCase() === sc)) {
          setRegistrationPrompt({ type: 'product', missing: sc });
          return;
        }
      } else {
        alert(`입력 형식이 잘못되었습니다: ${part}\n(예: A20 B30)`);
        return;
      }
    }

    onSubmit(targetClientName, items);
  };

  const handleClientKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();

      const term = client.trim();
      if (!term) return;

      let resolvedName = term;
      const exactNameMatch = clients.find(c => c.name === term);
      if (exactNameMatch) {
        resolvedName = exactNameMatch.name;
      } else {
        const exactShortcutMatch = clients.find(c => c.shortcut === term);
        if (exactShortcutMatch) {
          resolvedName = exactShortcutMatch.name;
        } else {
           const partialMatches = clients.filter(c => c.name.includes(term));
           if (partialMatches.length === 1) {
             resolvedName = partialMatches[0].name;
           }
        }
      }

      setClient(resolvedName);
      itemsInputRef.current?.focus();
    }
  };

  const handleItemsKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      if (registrationPrompt) return; 
      e.preventDefault();
      handleInitialSubmit();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all">
        {registrationPrompt ? (
          <div className="p-8 text-center">
            <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
              <Plus className="w-8 h-8" />
            </div>
            <h3 className="text-xl font-black text-slate-800 mb-2">
              {registrationPrompt.type === 'client' ? '거래처가 없습니다' : '품목이 없습니다'}
            </h3>
            <p className="text-sm font-medium text-slate-500 mb-6 leading-relaxed">
              "<span className="font-bold text-blue-600">{registrationPrompt.missing}</span>" 은(는) 등록되지 않은 {registrationPrompt.type === 'client' ? '거래처' : '품목'}입니다.<br/>
              새롭게 등록하시겠습니까?
            </p>
            <div className="flex gap-3">
              <button onClick={() => setRegistrationPrompt(null)} className="flex-1 py-4 text-sm font-bold text-slate-400 bg-slate-50 rounded-2xl hover:bg-slate-100 transition-colors">아니오</button>
              <button onClick={registrationPrompt.type === 'client' ? onOpenClientManager : onOpenProductManager} className="flex-1 py-4 text-sm font-bold text-white bg-blue-600 rounded-2xl hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all active:scale-95">예 (등록하기)</button>
            </div>
          </div>
        ) : (
          <>
            <div className="p-6">
              <h3 className="text-2xl font-black text-slate-800 mb-1">상차 주문 등록</h3><p className="text-sm font-bold text-slate-400 mb-6">{selectedDate}</p>
              <div className="space-y-5">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 ml-1">거래처 선택 또는 직접 입력</label>
                  <div className="relative">
                    <input 
                      ref={clientInputRef}
                      type="text" 
                      value={client} 
                      onChange={(e) => setClient(e.target.value)} 
                      onKeyDown={handleClientKeyDown} 
                      placeholder="거래처 명 또는 단축어 입력" 
                      className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none transition-all" 
                      autoFocus 
                    />
                    {filteredClients.length > 0 && client !== filteredClients[0].name && (
                      <div className="absolute top-full left-0 right-0 z-10 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl max-h-40 overflow-y-auto p-2">
                        {filteredClients.map(c => (
                          <div 
                            key={c.id} 
                            onClick={() => {
                              setClient(c.name);
                              itemsInputRef.current?.focus();
                            }} 
                            className="p-2 text-sm font-bold hover:bg-slate-50 rounded-lg cursor-pointer flex justify-between items-center"
                          >
                            <span>{c.name}</span>
                            {c.shortcut && <span className="text-[10px] bg-blue-50 text-blue-600 px-1.5 py-0.5 rounded ml-2">{c.shortcut}</span>}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 ml-1">품목 수량 입력 (띄어쓰기로 구분)</label>
                  <textarea 
                    ref={itemsInputRef}
                    rows={3} 
                    value={items} 
                    onChange={(e) => setItems(e.target.value)} 
                    onKeyDown={handleItemsKeyDown} 
                    placeholder="A20 B30 C10 (단축어+수량 띄어쓰기)" 
                    className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none" 
                  />
                  <div className="mt-3 bg-blue-50 p-4 rounded-xl border border-blue-100 space-y-2">
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] font-black bg-blue-600 text-white px-1.5 py-0.5 rounded">TIP</span>
                      <p className="text-[10px] font-bold text-blue-700">입력 형식 안내 (박스 없음, 낱개만 입력):</p>
                    </div>
                    <ul className="text-[9px] text-blue-600 font-medium list-disc pl-4 space-y-1">
                      <li><span className="font-bold">A20</span> : 사과 20개 (단축어A + 수량20)</li>
                      <li><span className="font-bold">B10</span> : 배 10개</li>
                      <li><span className="font-bold">A20 B10</span> : 띄어쓰기로 여러 품목 입력</li>
                    </ul>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-slate-50 p-5 flex gap-3 border-t border-slate-100">
              <button onClick={onClose} className="flex-1 px-4 py-4 text-sm font-bold text-slate-400 hover:text-slate-600 transition-colors">취소</button>
              <button onClick={handleInitialSubmit} className="flex-[2] bg-blue-600 hover:bg-blue-700 px-4 py-4 text-sm font-black text-white rounded-2xl transition-all shadow-xl disabled:opacity-30" disabled={!client || !items}>주문 생성하기</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Order, OrderItem, ProductDefinition, ClientDefinition } from './types';
import { ChevronLeft, ChevronRight, Plus, Truck, CheckCircle, Trash, GripVertical, Settings, Pencil, Download, Upload } from './components/Icons';
import { getSmartLoadingAdvice } from './services/geminiService';

const HOLIDAYS: Record<string, string> = {
  '01-01': '신정',
  '03-01': '삼일절',
  '05-05': '어린이날',
  '06-06': '현충일',
  '08-15': '광복절',
  '10-03': '개천절',
  '10-09': '한글날',
  '12-25': '성탄절',
  '2025-01-28': '설날',
  '2025-01-29': '설날',
  '2025-01-30': '설날',
  '2025-05-05': '부처님오신날',
  '2025-10-05': '추석',
  '2025-10-06': '추석',
  '2025-10-07': '추석',
  '2025-10-08': '대체공휴일'
};

const App: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('smart_orders_v6'); // Version up
    return saved ? JSON.parse(saved) : [];
  });

  const [products, setProducts] = useState<ProductDefinition[]>(() => {
    const saved = localStorage.getItem('smart_products_v2');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: '사과', shortcut: 'A', category: '과일' },
      { id: '2', name: '배', shortcut: 'B', category: '과일' }
    ];
  });

  const [clients, setClients] = useState<ClientDefinition[]>(() => {
    const saved = localStorage.getItem('smart_clients_v3');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: '대한상사', shortcut: '대한', phone: '010-1234-5678' },
      { id: 'c2', name: '한울물산', shortcut: '한울', phone: '010-9876-5432' }
    ];
  });

  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(formatDate(new Date()));
  const [showOrderForm, setShowOrderForm] = useState(false);
  const [showProductManager, setShowProductManager] = useState(false);
  const [showClientManager, setShowClientManager] = useState(false);
  const [showDataManager, setShowDataManager] = useState(false);
  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [draggedOrderId, setDraggedOrderId] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('smart_orders_v6', JSON.stringify(orders));
  }, [orders]);

  useEffect(() => {
    localStorage.setItem('smart_products_v2', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('smart_clients_v3', JSON.stringify(clients));
  }, [clients]);

  function formatDate(date: Date) {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  const getHolidayName = (date: Date) => {
    const fullDate = formatDate(date);
    const monthDay = fullDate.substring(5);
    return HOLIDAYS[fullDate] || HOLIDAYS[monthDay] || null;
  };

  const monthYear = useMemo(() => {
    return currentDate.toLocaleString('ko-KR', { month: 'long', year: 'numeric' });
  }, [currentDate]);

  const daysInMonth = useMemo(() => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) days.push(new Date(year, month, i));
    return days;
  }, [currentDate]);

  const handlePrevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const handleNextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const parseShortcuts = (input: string): OrderItem[] => {
    // 콤마 또는 공백으로 분리
    const parts = input.split(/[\s,]+/).map(p => p.trim()).filter(p => p !== "");
    const parsedItems: OrderItem[] = [];

    parts.forEach(part => {
      // 정규식 수정: [문자열(단축어)][숫자(수량)] 형태 매칭
      // 예: A20 -> A(단축어), 20(수량)
      const match = part.match(/^([a-zA-Z가-힣]+)(\d+)$/);

      if (match) {
        const shortcut = match[1].toUpperCase();
        const unitQty = parseInt(match[2], 10) || 0;

        const product = products.find(p => p.shortcut.toUpperCase() === shortcut);

        if (product) {
          parsedItems.push({
            id: Math.random().toString(36).substr(2, 9),
            productId: product.id,
            name: product.name,
            category: product.category,
            unitQuantity: unitQty,
            isLoaded: false
          });
        }
      }
    });
    return parsedItems;
  };

  const addOrder = (clientName: string, itemsStr: string) => {
    if (!selectedDate || !clientName || !itemsStr) return;
    const items = parseShortcuts(itemsStr);

    if (items.length === 0) return;

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      clientName,
      date: selectedDate,
      createdAt: Date.now(),
      items
    };

    setOrders(prev => [...prev, newOrder]);
    setShowOrderForm(false);
  };

  const deleteOrder = (orderId: string) => {
    if (confirm('이 주문을 삭제하시겠습니까?')) {
      setOrders(prev => prev.filter(o => o.id !== orderId));
    }
  };

  const toggleItemLoaded = (orderId: string, itemId: string) => {
    setOrders(prev => prev.map(order => {
      if (order.id !== orderId) return order;
      return {
        ...order,
        items: order.items.map(item => item.id === itemId ? { ...item, isLoaded: !item.isLoaded } : item)
      };
    }));
  };

  const selectedDateOrders = useMemo(() => {
    if (!selectedDate) return [];
    return orders.filter(o => o.date === selectedDate);
  }, [orders, selectedDate]);

  // 카테고리별 품목 합계 계산 (박스 제거, 낱개만 계산)
  const categoryTotals = useMemo(() => {
    const totals: Record<string, Record<string, number>> = {};

    selectedDateOrders.forEach(o => {
      o.items.forEach(i => {
        const cat = i.category || '기타';
        if (!totals[cat]) totals[cat] = {};
        if (!totals[cat][i.name]) totals[cat][i.name] = 0;

        totals[cat][i.name] += i.unitQuantity;
      });
    });

    return totals;
  }, [selectedDateOrders]);

  const fetchAiAdvice = async () => {
    if (selectedDateOrders.length === 0) return;
    setIsAiLoading(true);
    const advice = await getSmartLoadingAdvice(selectedDateOrders);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedOrderId(id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, id: string) => {
    e.preventDefault();
    if (!draggedOrderId || draggedOrderId === id) return;

    const newOrders = [...orders];
    const draggedIdx = newOrders.findIndex(o => o.id === draggedOrderId);
    const targetIdx = newOrders.findIndex(o => o.id === id);

    if (draggedIdx > -1 && targetIdx > -1) {
      const [draggedItem] = newOrders.splice(draggedIdx, 1);
      newOrders.splice(targetIdx, 0, draggedItem);
      setOrders(newOrders);
    }
  };

  const handleDragEnd = () => {
    setDraggedOrderId(null);
  };

  const handleImportData = (data: any) => {
    if (data.orders) setOrders(data.orders);
    if (data.products) setProducts(data.products);
    if (data.clients) setClients(data.clients);
    setShowDataManager(false);
    alert('데이터가 성공적으로 복원되었습니다.');
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-4 py-4 md:px-8 shadow-sm">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg text-white shadow-lg shadow-blue-200">
              <Truck className="w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 hidden sm:block">스마트 상차 플래너</h1>
          </div>

          <div className="flex flex-col items-center gap-2">
            <div className="flex items-center gap-2 md:gap-4">
              <button onClick={handlePrevMonth} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><ChevronLeft /></button>
              <h2 className="text-lg font-bold text-slate-700 min-w-[140px] text-center">{monthYear}</h2>
              <button onClick={handleNextMonth} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><ChevronRight /></button>
            </div>
            <div className="flex gap-2">
              <button onClick={() => setShowClientManager(true)} className="text-[10px] font-bold text-slate-500 hover:text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded-full transition-all border border-slate-200 hover:border-blue-200">거래처 관리</button>
              <button onClick={() => setShowProductManager(true)} className="text-[10px] font-bold text-slate-500 hover:text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded-full transition-all border border-slate-200 hover:border-blue-200">품목 관리</button>
            </div>
          </div>

          <div className="flex gap-2">
            <button onClick={() => { setCurrentDate(new Date()); setSelectedDate(formatDate(new Date())); }} className="text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 px-4 py-2 rounded-lg shadow-md transition-all active:scale-95">오늘</button>
            <button onClick={() => setShowDataManager(true)} className="p-2 text-slate-400 hover:text-slate-600 rounded-lg hover:bg-slate-100 transition-colors">
              <Settings className="w-6 h-6" />
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-4 md:p-6 flex flex-col lg:flex-row gap-6">
        <div className="flex-1 bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="calendar-grid bg-slate-50 border-b border-slate-200">
            {['일', '월', '화', '수', '목', '금', '토'].map((day, idx) => (
              <div key={day} className={`py-3 text-center text-xs font-bold uppercase tracking-wider ${idx === 0 ? 'text-red-500' : idx === 6 ? 'text-blue-500' : 'text-slate-400'}`}>{day}</div>
            ))}
          </div>
          <div className="calendar-grid divide-x divide-y divide-slate-100">
            {daysInMonth.map((date, idx) => {
              if (!date) return <div key={`empty-${idx}`} className="h-24 md:h-32 bg-slate-50/30" />;
              const dateStr = formatDate(date);
              const dayOrders = orders.filter(o => o.date === dateStr);
              const isSelected = selectedDate === dateStr;
              const isToday = formatDate(new Date()) === dateStr;
              const holidayName = getHolidayName(date);
              const dayOfWeek = date.getDay();
              const isSunday = dayOfWeek === 0;
              const isSaturday = dayOfWeek === 6;
              return (
                <div key={dateStr} onClick={() => setSelectedDate(dateStr)} className={`h-24 md:h-32 p-2 cursor-pointer transition-all hover:bg-blue-50/40 relative ${isSelected ? 'bg-blue-50 ring-2 ring-blue-500 ring-inset z-10' : ''}`}>
                  <div className="flex justify-between items-start">
                    <div className="flex flex-col items-center">
                      <span className={`text-sm font-bold ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center' : holidayName || isSunday ? 'text-red-500' : isSaturday ? 'text-blue-500' : 'text-slate-500'}`}>{date.getDate()}</span>
                      {holidayName && <span className="text-[9px] text-red-400 font-bold mt-0.5 truncate max-w-[40px]">{holidayName}</span>}
                    </div>
                    {dayOrders.length > 0 && <span className="bg-blue-100 text-blue-700 text-[10px] px-1.5 py-0.5 rounded-full font-bold">{dayOrders.length}</span>}
                  </div>
                  <div className="mt-2 space-y-1 overflow-hidden">
                    {dayOrders.slice(0, 2).map(o => (
                      <div key={o.id} className="text-[10px] text-slate-600 truncate bg-slate-100/80 px-1.5 py-0.5 rounded border border-slate-200">{o.clientName}</div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="w-full lg:w-96 flex flex-col gap-6">
          <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden flex flex-col h-full min-h-[600px]">
            <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50/80">
              <div>
                <h3 className="text-xl font-black text-slate-800">{selectedDate}</h3>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">DAILY LOADING LIST</p>
              </div>
              <button onClick={() => setShowOrderForm(true)} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-transform active:scale-90">
                <Plus className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-5 hide-scrollbar">
              {selectedDateOrders.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center py-20 grayscale opacity-30">
                  <Truck className="w-16 h-16 mb-4" />
                  <p className="font-bold">등록된 주문이 없습니다.</p>
                </div>
              ) : (
                <>
                  <div className="bg-blue-900 rounded-2xl p-4 text-white shadow-xl space-y-4">
                    <h4 className="text-[10px] font-black uppercase tracking-widest opacity-60">카테고리별 품목 합계</h4>
                    <div className="space-y-4">
                      {Object.entries(categoryTotals).map(([category, items]) => (
                        <div key={category} className="space-y-1">
                          <div className="text-[10px] font-black text-blue-400 border-b border-blue-800/50 pb-1 mb-2 uppercase">{category}</div>
                          {Object.entries(items).map(([name, count]) => (
                            <div key={name} className="flex justify-between items-center text-sm">
                              <span className="font-medium opacity-90">{name}</span>
                              <span className="font-bold text-white">
                                {count}개
                              </span>
                            </div>
                          ))}
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="space-y-3">
                    {selectedDateOrders.map(order => (
                      <div 
                        key={order.id} 
                        draggable
                        onDragStart={(e) => handleDragStart(e, order.id)}
                        onDragOver={(e) => handleDragOver(e, order.id)}
                        onDragEnd={handleDragEnd}
                        className={`bg-white border-2 border-slate-100 rounded-2xl overflow-hidden shadow-sm hover:border-blue-200 transition-colors ${draggedOrderId === order.id ? 'opacity-40 grayscale' : ''}`}
                      >
                        <div className="px-4 py-2 bg-slate-50 flex justify-between items-center border-b border-slate-100">
                          <div className="flex items-center gap-2">
                            <div className="cursor-grab active:cursor-grabbing text-slate-300 hover:text-blue-400">
                              <GripVertical className="w-4 h-4" />
                            </div>
                            <span className="font-black text-sm text-slate-800">{order.clientName}</span>
                          </div>
                          <button onClick={() => deleteOrder(order.id)} className="text-slate-300 hover:text-red-500 transition-colors"><Trash className="w-4 h-4" /></button>
                        </div>
                        <div className="p-1.5 space-y-0.5">
                          {order.items.map(item => (
                            <div 
                              key={item.id} 
                              onClick={() => toggleItemLoaded(order.id, item.id)} 
                              className={`flex items-center gap-2 px-2 py-1.5 rounded-lg cursor-pointer transition-all border ${item.isLoaded ? 'bg-green-50 border-green-100' : 'bg-white hover:bg-slate-50 border-transparent'}`}
                            >
                              <div className={`w-5 h-5 flex-shrink-0 rounded-md border-2 flex items-center justify-center transition-all ${item.isLoaded ? 'bg-green-500 border-green-500 text-white' : 'border-slate-200'}`}>
                                {item.isLoaded && <CheckCircle className="w-3.5 h-3.5" />}
                              </div>
                              <div className="flex-1 flex justify-between items-center gap-2 overflow-hidden">
                                <div className={`flex flex-col ${item.isLoaded ? 'opacity-40' : ''}`}>
                                  <span className="text-[8px] font-black text-blue-500 uppercase">{item.category}</span>
                                  <span className={`text-xs font-bold truncate ${item.isLoaded ? 'line-through text-green-800' : 'text-slate-700'}`}>
                                    {item.name}
                                  </span>
                                </div>
                                <div className={`flex-shrink-0 text-[10px] font-black px-1.5 py-0.5 rounded-md whitespace-nowrap ${item.isLoaded ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-600'}`}>
                                  {item.unitQuantity}개
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </>
              )}
            </div>

            {selectedDateOrders.length > 0 && (
              <div className="p-4 bg-slate-900 text-white">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-pulse" />
                    <span className="text-[10px] font-black tracking-widest text-blue-300">GEMINI LOADING ADVISOR</span>
                  </div>
                  {!aiAdvice && !isAiLoading && <button onClick={fetchAiAdvice} className="text-[10px] bg-blue-600 px-2 py-1 rounded font-bold hover:bg-blue-500 transition-colors">분석</button>}
                </div>
                {isAiLoading ? <div className="space-y-1 opacity-50"><div className="h-1.5 bg-slate-700 rounded w-full animate-pulse" /><div className="h-1.5 bg-slate-700 rounded w-2/3 animate-pulse" /></div> : aiAdvice && <p className="text-xs leading-relaxed font-medium text-slate-300">"{aiAdvice}"</p>}
              </div>
            )}
          </div>
        </div>
      </main>

      {showProductManager && <ProductManagerModal products={products} setProducts={setProducts} onClose={() => setShowProductManager(false)} orders={orders} selectedDate={selectedDate || ""} />}
      {showClientManager && <ClientManagerModal clients={clients} setClients={setClients} onClose={() => setShowClientManager(false)} />}
      {showDataManager && <DataManagerModal orders={orders} products={products} clients={clients} onImport={handleImportData} onClose={() => setShowDataManager(false)} />}
      {showOrderForm && (
        <OrderModal 
          onClose={() => setShowOrderForm(false)} 
          onSubmit={addOrder} 
          selectedDate={selectedDate || ""} 
          products={products} 
          clients={clients} 
          onOpenProductManager={() => { setShowOrderForm(false); setShowProductManager(true); }}
          onOpenClientManager={() => { setShowOrderForm(false); setShowClientManager(true); }}
        />
      )}
    </div>
  );
};

const DataManagerModal: React.FC<{ orders: Order[], products: ProductDefinition[], clients: ClientDefinition[], onImport: (data: any) => void, onClose: () => void }> = ({ orders, products, clients, onImport, onClose }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleExport = () => {
    const data = {
      version: '4.0',
      exportedAt: new Date().toISOString(),
      orders,
      products,
      clients
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `smart_loading_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (window.confirm('기존 데이터를 덮어쓰고 복원하시겠습니까?')) {
          onImport(data);
        }
      } catch (err) {
        alert('올바른 백업 파일이 아닙니다.');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center">
          <h3 className="text-xl font-black text-slate-800">데이터 백업 및 복구</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button>
        </div>
        <div className="p-8 space-y-6">
          <div className="bg-blue-50 p-4 rounded-xl text-sm text-blue-700 leading-relaxed font-medium">
            주문 내역, 품목 마스터, 거래처 정보를 파일로 저장하거나 불러옵니다.<br/>
            정기적인 백업으로 데이터를 안전하게 관리하세요.
          </div>
          <div className="grid grid-cols-2 gap-4">
            <button onClick={handleExport} className="flex flex-col items-center justify-center gap-3 p-6 bg-white border-2 border-slate-100 hover:border-blue-500 rounded-2xl transition-all group shadow-sm hover:shadow-lg">
              <div className="bg-slate-100 p-3 rounded-full text-slate-500 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                <Download className="w-8 h-8" />
              </div>
              <span className="font-bold text-slate-600 group-hover:text-slate-900">백업 파일 생성</span>
            </button>
            <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center gap-3 p-6 bg-white border-2 border-slate-100 hover:border-green-500 rounded-2xl transition-all group shadow-sm hover:shadow-lg">
              <div className="bg-slate-100 p-3 rounded-full text-slate-500 group-hover:bg-green-600 group-hover:text-white transition-colors">
                <Upload className="w-8 h-8" />
              </div>
              <span className="font-bold text-slate-600 group-hover:text-slate-900">백업 불러오기</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden" />
        </div>
      </div>
    </div>
  );
};

const ProductManagerModal: React.FC<{ 
  products: ProductDefinition[], 
  setProducts: any, 
  onClose: () => void,
  orders: Order[],
  selectedDate: string
}> = ({ products, setProducts, onClose, orders, selectedDate }) => {
  const [name, setName] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  const categories = useMemo(() => Array.from(new Set(products.map(p => p.category))).filter(Boolean), [products]);

  // 금일(selectedDate) 해당 품목의 총 상차 수량 계산
  const productCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    const dailyOrders = orders.filter(o => o.date === selectedDate);
    dailyOrders.forEach(order => {
      order.items.forEach(item => {
        counts[item.productId] = (counts[item.productId] || 0) + item.unitQuantity;
      });
    });
    return counts;
  }, [orders, selectedDate]);

  const startEdit = (p: ProductDefinition) => {
    setEditingId(p.id);
    setName(p.name);
    setShortcut(p.shortcut);
    setCategory(p.category || '');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setName('');
    setShortcut('');
    setCategory('');
  };

  const save = () => {
    if(!name || !shortcut || !category) return;
    if (editingId) {
      setProducts(products.map(p => p.id === editingId ? { ...p, name, shortcut: shortcut.toUpperCase(), category } : p));
      cancelEdit();
    } else {
      setProducts([...products, { id: Math.random().toString(36).substr(2, 9), name, shortcut: shortcut.toUpperCase(), category }]);
      cancelEdit();
    }
  };

  const remove = (id: string) => {
    if (confirm('삭제하시겠습니까?')) {
      setProducts(products.filter(p => p.id !== id));
      if (editingId === id) cancelEdit();
