              {editingId && <button onClick={cancelEdit} className="text-[10px] font-bold text-red-500 hover:bg-red-50 px-2 py-1 rounded">취소</button>}
            </div>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
              <div>
                <label className="text-[10px] font-bold text-slate-400 ml-1 uppercase block mb-1">카테고리</label>
                <input list="category-list" value={category} onChange={e => setCategory(e.target.value)} placeholder="분류 입력" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" />
