              <div className="bg-slate-100 p-3 rounded-full text-slate-500 group-hover:bg-green-600 group-hover:text-white transition-colors">
                <Upload className="w-8 h-8" />
              </div>
              <span className="font-bold text-slate-600 group-hover:text-slate-900">백업 불러오기</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden" />
        </div>
      </div>
    </div>
  );
};

const ProductManagerModal: React.FC<{ 
  products: ProductDefinition[], 
  setProducts: any, 
  onClose: () => void,
  orders: Order[],
  selectedDate: string
}> = ({ products, setProducts, onClose, orders, selectedDate }) => {
  const [name, setName] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  const categories = useMemo(() => Array.from(new Set(products.map(p => p.category))).filter(Boolean), [products]);

  // 금일(selectedDate) 해당 품목의 상차/총 수량 계산
  const productStats = useMemo(() => {
    const stats: Record<string, { total: number; loaded: number }> = {};
    const dailyOrders = orders.filter(o => o.date === selectedDate);

    // Initialize 0 for all existing products
    products.forEach(p => {
      stats[p.id] = { total: 0, loaded: 0 };
    });

    dailyOrders.forEach(order => {
      order.items.forEach(item => {
        if (!stats[item.productId]) stats[item.productId] = { total: 0, loaded: 0 };

        stats[item.productId].total += item.unitQuantity;
        if (item.isLoaded) {
          stats[item.productId].loaded += item.unitQuantity;
        }
      });
    });
    return stats;
  }, [orders, selectedDate, products]);

  const startEdit = (p: ProductDefinition) => {
    setEditingId(p.id);
    setName(p.name);
    setShortcut(p.shortcut);
    setCategory(p.category || '');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setName('');
    setShortcut('');
    setCategory('');
  };

  const save = () => {
    if(!name || !shortcut || !category) return;
    if (editingId) {
      setProducts(products.map(p => p.id === editingId ? { ...p, name, shortcut: shortcut.toUpperCase(), category } : p));
      cancelEdit();
    } else {
      setProducts([...products, { id: Math.random().toString(36).substr(2, 9), name, shortcut: shortcut.toUpperCase(), category }]);
      cancelEdit();
    }
  };

  const remove = (id: string) => {
    if (confirm('삭제하시겠습니까?')) {
      setProducts(products.filter(p => p.id !== id));
      if (editingId === id) cancelEdit();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-3xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center flex-shrink-0 bg-slate-50/50">
          <h3 className="text-lg font-black text-slate-800">품목 마스터 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button>
        </div>

        <div className="p-4 flex flex-col gap-4 overflow-hidden h-full">
          {/* 입력 폼 (Compact) */}
          <div className="bg-slate-50 p-3 rounded-xl border border-slate-200 flex-shrink-0 shadow-sm">
            <div className="flex flex-col md:flex-row gap-3 items-center">
              <div className="flex items-center gap-2 w-full md:flex-1">
                <span className="text-xs font-bold text-slate-500 whitespace-nowrap w-12 text-right">카테고리</span>
                <input list="category-list" value={category} onChange={e => setCategory(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="선택/입력" />
                <datalist id="category-list">
                  {categories.map(c => <option key={c} value={c} />)}
                </datalist>
              </div>

              <div className="flex items-center gap-2 w-full md:flex-[1.5]">
                <span className="text-xs font-bold text-slate-500 whitespace-nowrap w-10 text-right">품목명</span>
                <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="품목 이름" />
              </div>

              <div className="flex items-center gap-2 w-full md:w-48">
                <span className="text-xs font-bold text-slate-500 whitespace-nowrap w-10 text-right">단축어</span>
                <input type="text" value={shortcut} onChange={e => setShortcut(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="키(Key)" />
              </div>

              <div className="flex items-center gap-2 w-full md:w-auto pl-1">
                {editingId && <button onClick={cancelEdit} className="px-3 py-2 text-xs font-bold text-slate-500 hover:bg-slate-200 rounded-lg whitespace-nowrap">취소</button>}
                <button onClick={save} className={`px-5 py-2 text-sm font-bold text-white rounded-lg transition-colors whitespace-nowrap shadow-md active:scale-95 ${editingId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-800 hover:bg-slate-900'}`}>
                  {editingId ? '수정' : '추가'}
                </button>
              </div>
            </div>
          </div>

          {/* 목록 (하단으로 이동) */}
          <div className="flex flex-col gap-2 flex-1 overflow-hidden">
            <div className="flex justify-between items-end px-1 pb-1 border-b border-slate-100">
                <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">등록된 품목 리스트</h4>
                <span className="text-[10px] text-slate-400 font-medium">총 {products.length}개</span>
            </div>
            <div className="flex-1 space-y-2 overflow-y-auto pr-1 hide-scrollbar">
              {products.map(p => {
                const stat = productStats[p.id] || { total: 0, loaded: 0 };
                return (
                  <div key={p.id} className={`flex justify-between items-center p-3 border rounded-xl group transition-all hover:shadow-sm ${editingId === p.id ? 'bg-blue-50 border-blue-300 ring-1 ring-blue-300' : 'bg-white border-slate-100 hover:border-blue-200'}`}>
                    <div className="flex items-center gap-4 flex-1">
                      <div className="w-16 flex-shrink-0">
                          <div className="text-[10px] font-black text-blue-500 uppercase truncate">{p.category}</div>
                      </div>
                      <div className="flex-1 min-w-[100px]">
                          <div className="font-bold text-sm text-slate-800">{p.name}</div>
                      </div>
                      <div className="w-20">
                          <div className="text-[10px] font-bold text-slate-400">단축어 <span className="text-blue-600 bg-blue-50 px-1 rounded">{p.shortcut}</span></div>
                      </div>
                    </div>

                    <div className="flex items-center gap-4">
                      <div className="w-28 text-right">
                          <div className="text-[10px] font-bold text-slate-400 mb-0.5">금일 상차/주문</div>
                          <div className="text-sm font-bold text-slate-800">
                            <span className={`${stat.loaded > 0 && stat.loaded === stat.total ? 'text-green-600' : 'text-blue-600'}`}>{stat.loaded}</span>
                            <span className="text-slate-300 mx-1">/</span>
                            <span>{stat.total}</span>
                          </div>
                      </div>
                      <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => startEdit(p)} className="p-1.5 text-slate-400 hover:text-blue-600 rounded-lg hover:bg-blue-50 transition-colors"><Pencil className="w-4 h-4" /></button>
                        <button onClick={() => remove(p.id)} className="p-1.5 text-slate-400 hover:text-red-500 rounded-lg hover:bg-red-50 transition-colors"><Trash className="w-4 h-4" /></button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const ClientManagerModal: React.FC<{ clients: ClientDefinition[], setClients: any, onClose: () => void }> = ({ clients, setClients, onClose }) => {
