              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 ml-1">거래처 단축명</label>
                <input name="shortcut" value={formData.shortcut || ''} onChange={handleChange} placeholder="예: 한울, 대한" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 ml-1">전화번호</label>
                <input name="phone" value={formData.phone || ''} onChange={handleChange} placeholder="010-0000-0000" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" />
