  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center"><h3 className="text-xl font-black text-slate-800">거래처 마스터 관리</h3><button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button></div>
        <div className="p-6 grid grid-cols-1 lg:grid-cols-2 gap-6 overflow-hidden">
