};

const ClientManagerModal: React.FC<{ clients: ClientDefinition[], setClients: any, onClose: () => void }> = ({ clients, setClients, onClose }) => {
  const [formData, setFormData] = useState<Partial<ClientDefinition>>({});
  const [editingId, setEditingId] = useState<string | null>(null);

  const startEdit = (c: ClientDefinition) => {
    setEditingId(c.id);
    setFormData(c);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setFormData({});
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const save = () => {
    if(!formData.name) return;
    if (editingId) {
      setClients(clients.map(c => c.id === editingId ? { ...c, ...formData } : c));
      cancelEdit();
    } else {
      setClients([...clients, { id: Math.random().toString(36).substr(2, 9), ...formData } as ClientDefinition]);
      cancelEdit();
    }
  };

  const remove = (id: string) => {
    if (confirm('삭제하시겠습니까?')) {
      setClients(clients.filter(c => c.id !== id));
      if (editingId === id) cancelEdit();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center"><h3 className="text-xl font-black text-slate-800">거래처 마스터 관리</h3><button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button></div>
        <div className="p-6 grid grid-cols-1 lg:grid-cols-2 gap-6 overflow-hidden">
          <div className="flex flex-col gap-3">
            <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">등록된 거래처</h4>
            <div className="flex-1 space-y-2 overflow-y-auto pr-2 hide-scrollbar">
              {clients.map(c => (
                <div key={c.id} className={`flex justify-between items-center p-3 border rounded-xl group transition-all ${editingId === c.id ? 'bg-blue-50 border-blue-300 ring-1 ring-blue-300' : 'bg-slate-50 border-slate-200'}`}>
                  <div className="overflow-hidden">
                    <div className="font-bold text-sm text-slate-800 truncate">{c.name}</div>
                    <div className="text-[10px] text-slate-400 truncate">
                      {c.shortcut ? <span className="text-blue-600 font-bold">[{c.shortcut}] </span> : ''}
                      {c.phone || '번호없음'}
                    </div>
                  </div>
                  <div className="flex gap-1 flex-shrink-0">
                    <button onClick={() => startEdit(c)} className="p-1.5 text-slate-400 hover:text-blue-600 rounded-lg hover:bg-blue-100 transition-colors"><Pencil className="w-4 h-4" /></button>
                    <button onClick={() => remove(c.id)} className="p-1.5 text-slate-400 hover:text-red-500 rounded-lg hover:bg-red-100 transition-colors"><Trash className="w-4 h-4" /></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200 overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">{editingId ? '거래처 정보 수정' : '새 거래처 등록'}</h4>
              {editingId && <button onClick={cancelEdit} className="text-[10px] font-bold text-red-500 hover:bg-red-50 px-2 py-1 rounded">입력 취소</button>}
            </div>
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-bold text-slate-400 ml-1">거래처명 (필수)</label>
                <input name="name" value={formData.name || ''} onChange={handleChange} placeholder="거래처명 입력" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 ml-1">거래처 단축명</label>
                <input name="shortcut" value={formData.shortcut || ''} onChange={handleChange} placeholder="예: 한울, 대한" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 ml-1">전화번호</label>
                <input name="phone" value={formData.phone || ''} onChange={handleChange} placeholder="010-0000-0000" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div className="pt-2">
                <button onClick={save} className={`w-full text-white py-3.5 rounded-xl font-bold transition-all shadow-lg active:scale-95 ${editingId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-900 hover:bg-slate-800'}`}>{editingId ? '수정 내용 저장' : '새 거래처 추가하기'}</button>
