        </div>
      </main>

      {showProductManager && <ProductManagerModal products={products} setProducts={setProducts} onClose={() => setShowProductManager(false)} />}
      {showClientManager && (
        <ClientManagerModal 
          clients={clients} 
          setClients={setClients} 
          onClose={() => setShowClientManager(false)} 
          onSelectForOrder={handleSelectClientForOrder}
        />
      )}
      {showDataManager && <DataManagerModal orders={orders} products={products} clients={clients} onImport={handleImportData} onClose={() => setShowDataManager(false)} />}
      {showOrderForm && (
        <OrderModal 
          onClose={() => {
            setShowOrderForm(false);
            setEditingOrder(null);
            setPreselectedClient(''); 
          }} 
          onSubmit={handleSaveOrder} 
          selectedDate={selectedDate || ""} 
          products={products} 
          clients={clients} 
          initialClientName={editingOrder ? editingOrder.clientName : preselectedClient}
          initialItemsStr={editingOrder ? reconstructItemsStr(editingOrder.items) : ''}
          isEditing={!!editingOrder}
          onOpenProductManager={() => { setShowOrderForm(false); setShowProductManager(true); }}
          onOpenClientManager={() => { setShowOrderForm(false); setShowClientManager(true); }}
        />
      )}
    </div>
  );
};

const DataManagerModal: React.FC<{ orders: Order[], products: ProductDefinition[], clients: ClientDefinition[], onImport: (data: any) => void, onClose: () => void }> = ({ orders, products, clients, onImport, onClose }) => {
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const csvInputRef = useRef<HTMLInputElement>(null);

  const handleExportJSON = () => {
    const data = {
      version: '4.0',
      exportedAt: new Date().toISOString(),
      orders,
      products,
      clients
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `smart_loading_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportCSV = () => {
    // CSV 헤더
    let csvContent = "날짜,거래처,주문내역\n";

    // 데이터 변환
    orders.forEach(order => {
        // 주문 내역 문자열로 변환 (예: 특크20 감천10)
        const itemsStr = order.items.map(i => {
            const p = products.find(prod => prod.id === i.productId);
            const code = p ? p.shortcut : i.name;
            return `${code}${i.unitQuantity}`;
        }).join(' ');

        // CSV 행 추가 (특수문자 처리 위해 따옴표 감싸기)
        csvContent += `"${order.date}","${order.clientName}","${itemsStr}"\n`;
    });

    // BOM 추가 (엑셀 한글 깨짐 방지)
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `smart_loading_list_${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleJSONFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (window.confirm('기존 데이터를 덮어쓰고 복원하시겠습니까? (JSON)')) {
          onImport(data);
        }
      } catch (err) {
        alert('올바른 백업 파일이 아닙니다.');
      }
    };
    reader.readAsText(file);
    // 입력값 초기화
    e.target.value = '';
  };

  const handleCSVFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
          const text = event.target?.result as string;
          if (!text) return;

          try {
              const lines = text.split('\n');
              const newOrders: Order[] = [];
              let successCount = 0;

              // 첫 줄(헤더) 건너뛰고 파싱
              for (let i = 1; i < lines.length; i++) {
                  const line = lines[i].trim();
                  if (!line) continue;

                  // CSV 파싱 (따옴표 제거 및 콤마 분리 - 간단한 파서)
                  // 주의: 데이터 내에 콤마가 있으면 오동작할 수 있음. 
                  // 여기서는 "날짜","거래처","주문내역" 형태를 가정하고 정규식으로 처리하거나 간단히 split.
                  // 정규식: 콤마로 구분하되 따옴표 내의 콤마는 무시
                  const cols = line.match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);

                  if (cols && cols.length >= 3) {
                      const date = cols[0].replace(/^"|"$/g, '').trim();
                      const clientName = cols[1].replace(/^"|"$/g, '').trim();
                      const itemsStr = cols[2].replace(/^"|"$/g, '').trim();

                      // 주문 내역 파싱 (App.tsx의 parseShortcuts 로직 복제)
                      const parts = itemsStr.split(/[\s,]+/).map(p => p.trim()).filter(p => p !== "");
                      const parsedItems: OrderItem[] = [];

                      parts.forEach(part => {
                          const match = part.match(/^([a-zA-Z가-힣]+)(\d+)$/);
                          if (match) {
                              const shortcut = match[1].toUpperCase();
                              const unitQty = parseInt(match[2], 10) || 0;
                              const product = products.find(p => p.shortcut.toUpperCase() === shortcut);
                              if (product) {
                                  parsedItems.push({
                                      id: Math.random().toString(36).substr(2, 9),
                                      productId: product.id,
                                      name: product.name,
                                      category: product.category,
                                      unitQuantity: unitQty,
                                      isLoaded: false
                                  });
                              }
                          }
                      });

                      if (parsedItems.length > 0) {
                          newOrders.push({
                              id: Math.random().toString(36).substr(2, 9),
                              date: date,
                              clientName: clientName,
                              createdAt: Date.now(),
                              items: parsedItems
                          });
                          successCount++;
                      }
                  }
              }

              if (newOrders.length > 0) {
                  if (window.confirm(`${successCount}건의 주문을 CSV에서 불러왔습니다.\n기존 주문 데이터를 덮어쓰시겠습니까?`)) {
                      onImport({ orders: newOrders });
                  }
              } else {
                  alert('불러올 수 있는 유효한 주문 데이터가 없습니다.');
              }
          } catch (err) {
              console.error(err);
              alert('CSV 파일을 읽는 중 오류가 발생했습니다.');
          }
      };
      reader.readAsText(file);
      e.target.value = '';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center">
          <h3 className="text-2xl font-black text-slate-800">데이터 백업 및 복구</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button>
        </div>
        <div className="p-8 space-y-6">
          <div className="bg-blue-50 p-4 rounded-xl text-base text-blue-700 leading-relaxed font-medium">
            주문 내역, 품목 마스터, 거래처 정보를 파일로 저장하거나 불러옵니다.<br/>
            정기적인 백업으로 데이터를 안전하게 관리하세요.
          </div>
          <div className="grid grid-cols-2 gap-4">
            <button onClick={handleExport} className="flex flex-col items-center justify-center gap-3 p-6 bg-white border-2 border-slate-100 hover:border-blue-500 rounded-2xl transition-all group shadow-sm hover:shadow-lg">
              <div className="bg-slate-100 p-3 rounded-full text-slate-500 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                <Download className="w-8 h-8" />
              </div>
              <span className="font-bold text-slate-600 group-hover:text-slate-900 text-lg">백업 파일 생성</span>
            </button>
            <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center gap-3 p-6 bg-white border-2 border-slate-100 hover:border-green-500 rounded-2xl transition-all group shadow-sm hover:shadow-lg">
              <div className="bg-slate-100 p-3 rounded-full text-slate-500 group-hover:bg-green-600 group-hover:text-white transition-colors">
                <Upload className="w-8 h-8" />
              </div>
              <span className="font-bold text-slate-600 group-hover:text-slate-900 text-lg">백업 불러오기</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden" />
        </div>
      </div>
    </div>
  );
};

const ProductManagerModal: React.FC<{ 
  products: ProductDefinition[], 
  setProducts: any, 
  onClose: () => void
}> = ({ products, setProducts, onClose }) => {
  const [name, setName] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [expandedCategories, setExpandedCategories] = useState<string[]>([]);

  const categories = useMemo(() => Array.from(new Set(products.map(p => p.category))).filter(Boolean), [products]);

  // Group products by category
  const productsByCategory = useMemo(() => {
    const grouped: Record<string, ProductDefinition[]> = {};
    products.forEach(p => {
      const cat = p.category || '기타';
      if (!grouped[cat]) grouped[cat] = [];
      grouped[cat].push(p);
    });
    return grouped;
  }, [products]);

  const toggleCategory = (cat: string) => {
    setExpandedCategories(prev => 
      prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]
    );
  };

  const startEdit = (p: ProductDefinition) => {
    setEditingId(p.id);
    setName(p.name);
    setShortcut(p.shortcut);
    setCategory(p.category || '');

    // Auto expand category when editing
    const cat = p.category || '기타';
    if (!expandedCategories.includes(cat)) {
      setExpandedCategories(prev => [...prev, cat]);
    }
  };

  const cancelEdit = () => {
    setEditingId(null);
    setName('');
    setShortcut('');
    setCategory('');
  };

  const save = () => {
    if(!name || !shortcut || !category) return;

    // Auto expand target category
    const targetCat = category || '기타';
    if (!expandedCategories.includes(targetCat)) {
      setExpandedCategories(prev => [...prev, targetCat]);
    }

    if (editingId) {
      setProducts(products.map(p => p.id === editingId ? { ...p, name, shortcut: shortcut.toUpperCase(), category } : p));
      cancelEdit();
    } else {
      setProducts([...products, { id: Math.random().toString(36).substr(2, 9), name, shortcut: shortcut.toUpperCase(), category }]);
      cancelEdit();
    }
  };

  const remove = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('삭제하시겠습니까?')) {
      setProducts((prev: ProductDefinition[]) => prev.filter(p => p.id !== id));
      if (editingId === id) cancelEdit();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-3xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center flex-shrink-0 bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-800">품목 마스터 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button>
        </div>

        <div className="p-4 flex flex-col gap-4 overflow-hidden h-full">
          {/* 입력 폼 (Compact) */}
          <div className="bg-slate-50 p-3 rounded-xl border border-slate-200 flex-shrink-0 shadow-sm">
            <div className="flex flex-col md:flex-row gap-3 items-center">
              <div className="flex items-center gap-2 w-full md:flex-1">
                <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-12 text-right">카테고리</span>
                <input list="category-list" value={category} onChange={e => setCategory(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="선택/입력" />
                <datalist id="category-list">
                  {categories.map(c => <option key={c} value={c} />)}
                </datalist>
              </div>

              <div className="flex items-center gap-2 w-full md:flex-[1.5]">
                <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-10 text-right">품목명</span>
                <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="품목 이름" />
              </div>

              <div className="flex items-center gap-2 w-full md:w-48">
                <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-10 text-right">단축어</span>
                <input type="text" value={shortcut} onChange={e => setShortcut(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="키(Key)" />
              </div>

              <div className="flex items-center gap-2 w-full md:w-auto pl-1">
                {editingId && <button onClick={cancelEdit} className="px-3 py-2 text-sm font-bold text-slate-500 hover:bg-slate-200 rounded-lg whitespace-nowrap">취소</button>}
                <button onClick={save} className={`px-5 py-2 text-base font-bold text-white rounded-lg transition-colors whitespace-nowrap shadow-md active:scale-95 ${editingId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-800 hover:bg-slate-900'}`}>
                  {editingId ? '수정' : '추가'}
                </button>
              </div>
            </div>
          </div>

          {/* 목록 (카테고리별 그룹핑) */}
          <div className="flex flex-col gap-2 flex-1 overflow-hidden">
            <div className="flex justify-between items-end px-1 pb-1 border-b border-slate-100">
                <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">등록된 품목 리스트</h4>
                <span className="text-xs text-slate-400 font-medium">총 {products.length}개</span>
            </div>
            <div className="flex-1 space-y-2 overflow-y-auto pr-1 hide-scrollbar">
              {Object.entries(productsByCategory).sort((a, b) => {
                const indexA = CATEGORY_ORDER.indexOf(a[0]);
                const indexB = CATEGORY_ORDER.indexOf(b[0]);
                if (indexA !== -1 && indexB !== -1) return indexA - indexB;
                if (indexA !== -1) return -1;
                if (indexB !== -1) return 1;
                return a[0].localeCompare(b[0]);
              }).map(([cat, itemsRaw]) => {
                const items = itemsRaw as ProductDefinition[];
                return (
                <div key={cat} className="space-y-1">
                   {/* Category Header */}
                   <button 
                     onClick={() => toggleCategory(cat)}
                     className={`w-full flex justify-between items-center p-3 rounded-xl transition-all ${expandedCategories.includes(cat) ? 'bg-slate-100 text-slate-800' : 'bg-white border border-slate-100 text-slate-600 hover:bg-slate-50'}`}
                   >
                     <div className="flex items-center gap-2">
                       <div className={`transform transition-transform duration-200 ${expandedCategories.includes(cat) ? 'rotate-90' : ''}`}>
                          <ChevronRight className="w-4 h-4" />
                       </div>
                       <span className="font-black text-base">{cat}</span>
                     </div>
                     <span className="text-xs font-bold bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full">{items.length}개</span>
                   </button>

                   {/* Products List */}
                   {expandedCategories.includes(cat) && (
                     <div className="space-y-2 pl-2 border-l-2 border-slate-100 ml-3 py-1">
                       {items.map(p => {
                         return (
                           <div key={p.id} className={`flex justify-between items-center p-3 border rounded-xl group transition-all hover:shadow-sm ${editingId === p.id ? 'bg-blue-50 border-blue-300 ring-1 ring-blue-300' : 'bg-white border-slate-100 hover:border-blue-200'}`}>
                             <div className="flex items-center gap-4 flex-1">
                               <div className="flex-1 min-w-[100px]">
                                   <div className="font-bold text-base text-slate-800">{p.name}</div>
                               </div>
                               <div className="w-20">
                                   <div className="text-xs font-bold text-slate-400">단축어 <span className="text-blue-600 bg-blue-50 px-1 rounded">{p.shortcut}</span></div>
                               </div>
                             </div>

                             <div className="flex items-center gap-4">
                               <div className="flex gap-1">
                                 <button onClick={() => startEdit(p)} className="p-1.5 text-slate-400 hover:text-blue-600 rounded-lg hover:bg-blue-50 transition-colors"><Pencil className="w-4 h-4" /></button>
                                 <button onClick={(e) => remove(e, p.id)} className="p-1.5 text-slate-400 hover:text-red-500 rounded-lg hover:bg-red-50 transition-colors"><Trash className="w-4 h-4" /></button>
                               </div>
                             </div>
                           </div>
                         );
                       })}
                     </div>
                   )}
                </div>
              )})}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const ClientManagerModal: React.FC<{ 
  clients: ClientDefinition[], 
  setClients: any, 
  onClose: () => void,
  onSelectForOrder?: (clientName: string) => void
}> = ({ clients, setClients, onClose, onSelectForOrder }) => {
  const [formData, setFormData] = useState<Partial<ClientDefinition>>({});
  const [editingId, setEditingId] = useState<string | null>(null);

  const startEdit = (c: ClientDefinition) => {
    setEditingId(c.id);
    setFormData(c);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setFormData({});
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const save = () => {
    if(!formData.name) return;
    if (editingId) {
      setClients(clients.map(c => c.id === editingId ? { ...c, ...formData } : c));
      cancelEdit();
    } else {
      setClients([...clients, { id: Math.random().toString(36).substr(2, 9), ...formData } as ClientDefinition]);
      cancelEdit();
    }
  };

  const remove = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('삭제하시겠습니까?')) {
      setClients((prev: ClientDefinition[]) => prev.filter(c => c.id !== id));
      if (editingId === id) cancelEdit();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center flex-shrink-0">
          <h3 className="text-2xl font-black text-slate-800">거래처 마스터 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button>
        </div>

        <div className="flex flex-col h-full overflow-hidden">
          {/* 상단: 입력 폼 (위치 변경됨) */}
          <div className="bg-slate-50 p-6 border-b border-slate-200 flex-shrink-0">
            <div className="flex justify-between items-center mb-4">
              <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">{editingId ? '거래처 정보 수정' : '새 거래처 등록'}</h4>
              {editingId && <button onClick={cancelEdit} className="text-xs font-bold text-red-500 hover:bg-red-50 px-2 py-1 rounded">입력 취소</button>}
            </div>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
              <div className="md:col-span-1">
                <label className="text-xs font-bold text-slate-400 ml-1 mb-1 block">거래처명 (필수)</label>
                <input name="name" value={formData.name || ''} onChange={handleChange} placeholder="거래처명 입력" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div className="md:col-span-1">
                <label className="text-xs font-bold text-slate-400 ml-1 mb-1 block">거래처 단축명</label>
                <input name="shortcut" value={formData.shortcut || ''} onChange={handleChange} placeholder="예: 한울, 대한" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div className="md:col-span-1">
                <label className="text-xs font-bold text-slate-400 ml-1 mb-1 block">전화번호</label>
                <input name="phone" value={formData.phone || ''} onChange={handleChange} placeholder="010-0000-0000" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div className="md:col-span-1">
                <button onClick={save} className={`w-full text-white py-2.5 rounded-xl font-bold transition-all shadow-lg active:scale-95 ${editingId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-900 hover:bg-slate-800'}`}>{editingId ? '수정 내용 저장' : '새 거래처 추가하기'}</button>
              </div>
            </div>
          </div>

          {/* 하단: 리스트 */}
          <div className="flex-1 overflow-y-auto p-6 bg-white">
            <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-3">등록된 거래처 ({clients.length})</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {clients.map(c => (
                <div key={c.id} className={`flex justify-between items-center p-3 border rounded-xl group transition-all ${editingId === c.id ? 'bg-blue-50 border-blue-300 ring-1 ring-blue-300' : 'bg-slate-50 border-slate-200'}`}>
                  <div className="overflow-hidden">
                    {c.phone ? (
                      <a href={`tel:${c.phone}`} className="font-bold text-base text-slate-800 truncate hover:text-blue-600 hover:underline block cursor-pointer">
                        {c.name}
