                    <Settings className="w-5 h-5" />
                    <span>거래처 관리</span>
                </button>
            </header>

            <main className="max-w-5xl mx-auto">
                {showClientManager && (
                    <ClientManagerModal 
                        clients={clients} 
                        setClients={setClients} 
                        onClose={() => setShowClientManager(false)} 
                    />
                )}

                <div className="bg-white p-12 rounded-3xl shadow-sm border border-slate-200 text-center">
                    <p className="text-slate-400 font-bold text-lg">메인 화면</p>
                    <p className="text-slate-300 mt-2">이곳에 주문 내역 및 캘린더가 표시됩니다.</p>
                </div>
            </main>
        </div>
    );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Order, OrderItem, ProductDefinition, ClientDefinition } from './types';
import { ChevronLeft, ChevronRight, Plus, Truck, CheckCircle, Trash, GripVertical, Settings, Pencil, Download, Upload } from './components/Icons';
import { getSmartLoadingAdvice } from './services/geminiService';

const HOLIDAYS: Record<string, string> = {
  '01-01': '신정',
  '03-01': '삼일절',
  '05-05': '어린이날',
  '06-06': '현충일',
  '08-15': '광복절',
  '10-03': '개천절',
  '10-09': '한글날',
  '12-25': '성탄절',
  '2025-01-28': '설날',
  '2025-01-29': '설날',
  '2025-01-30': '설날',
  '2025-05-05': '부처님오신날',
  '2025-10-05': '추석',
  '2025-10-06': '추석',
  '2025-10-07': '추석',
  '2025-10-08': '대체공휴일'
};

const CATEGORY_ORDER = ['크릴', '파우다', '생물', '기타'];

const App: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('smart_orders_v10'); 
    return saved ? JSON.parse(saved) : [];
  });

  const [products, setProducts] = useState<ProductDefinition[]>(() => {
    const saved = localStorage.getItem('smart_products_v10'); // 초기 데이터 없애기 위해 키 변경
    return saved ? JSON.parse(saved) : []; 
  });

  const [clients, setClients] = useState<ClientDefinition[]>(() => {
    const saved = localStorage.getItem('smart_clients_v10'); // 초기 데이터 없애기 위해 키 변경
    return saved ? JSON.parse(saved) : []; 
  });

  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(formatDate(new Date()));
  const [showOrderForm, setShowOrderForm] = useState(false);
  const [showProductManager, setShowProductManager] = useState(false);
  const [showClientManager, setShowClientManager] = useState(false);
  const [showDataManager, setShowDataManager] = useState(false);
  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [draggedOrderId, setDraggedOrderId] = useState<string | null>(null);

  // 주문 수정 및 바로 등록을 위한 상태
  const [preselectedClient, setPreselectedClient] = useState<string>('');
  const [editingOrder, setEditingOrder] = useState<Order | null>(null);

  useEffect(() => {
    localStorage.setItem('smart_orders_v10', JSON.stringify(orders));
  }, [orders]);

  useEffect(() => {
    localStorage.setItem('smart_products_v10', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('smart_clients_v10', JSON.stringify(clients));
  }, [clients]);

  function formatDate(date: Date) {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  const getHolidayName = (date: Date) => {
    const fullDate = formatDate(date);
    const monthDay = fullDate.substring(5);
    return HOLIDAYS[fullDate] || HOLIDAYS[monthDay] || null;
  };

  const monthYear = useMemo(() => {
    return currentDate.toLocaleString('ko-KR', { month: 'long', year: 'numeric' });
  }, [currentDate]);

  const daysInMonth = useMemo(() => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) days.push(new Date(year, month, i));
    return days;
  }, [currentDate]);

  const handlePrevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const handleNextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const parseShortcuts = (input: string): OrderItem[] => {
    const parts = input.split(/[\s,]+/).map(p => p.trim()).filter(p => p !== "");
    const parsedItems: OrderItem[] = [];

    parts.forEach(part => {
      const match = part.match(/^([a-zA-Z가-힣]+)(\d+)$/);

      if (match) {
        const shortcut = match[1].toUpperCase();
        const unitQty = parseInt(match[2], 10) || 0;

        const product = products.find(p => p.shortcut.toUpperCase() === shortcut);

        if (product) {
          parsedItems.push({
            id: Math.random().toString(36).substr(2, 9),
            productId: product.id,
            name: product.name,
            category: product.category,
            unitQuantity: unitQty,
            isLoaded: false
          });
        }
      }
    });
    return parsedItems;
  };

  const reconstructItemsStr = (items: OrderItem[]) => {
    return items.map(i => {
        const p = products.find(prod => prod.id === i.productId);
        const code = p ? p.shortcut : i.name; // fallback to name if shortcut not found
        return `${code}${i.unitQuantity}`;
    }).join(' ');
  };

  const handleSaveOrder = (clientName: string, itemsStr: string) => {
    if (!selectedDate || !clientName || !itemsStr) return;
    const items = parseShortcuts(itemsStr);

    if (items.length === 0) return;

    if (editingOrder) {
      setOrders(prev => prev.map(o => {
        if (o.id === editingOrder.id) {
          return {
            ...o,
            clientName,
            items // Note: This regenerates items, so isLoaded status is reset. This is expected behavior for "Edit".
          };
        }
        return o;
      }));
      setEditingOrder(null);
    } else {
      const newOrder: Order = {
        id: Math.random().toString(36).substr(2, 9),
        clientName,
        date: selectedDate,
        createdAt: Date.now(),
        items
      };
      setOrders(prev => [...prev, newOrder]);
    }

    setShowOrderForm(false);
    setPreselectedClient('');
  };

  const deleteOrder = (e: React.MouseEvent, orderId: string) => {
    e.stopPropagation();
    if (confirm('이 주문을 삭제하시겠습니까?')) {
      setOrders(prev => prev.filter(o => o.id !== orderId));
    }
  };

  const startEditOrder = (order: Order) => {
    setEditingOrder(order);
    setShowOrderForm(true);
  };

  const toggleItemLoaded = (orderId: string, itemId: string) => {
    setOrders(prev => prev.map(order => {
      if (order.id !== orderId) return order;
      return {
        ...order,
        items: order.items.map(item => item.id === itemId ? { ...item, isLoaded: !item.isLoaded } : item)
      };
    }));
  };

  const selectedDateOrders = useMemo(() => {
    if (!selectedDate) return [];
    return orders.filter(o => o.date === selectedDate);
  }, [orders, selectedDate]);

  const categoryTotals = useMemo(() => {
    const totals: Record<string, Record<string, number>> = {};

    selectedDateOrders.forEach(o => {
      o.items.forEach(i => {
        const cat = i.category || '기타';
        if (!totals[cat]) totals[cat] = {};
        if (!totals[cat][i.name]) totals[cat][i.name] = 0;

        totals[cat][i.name] += i.unitQuantity;
      });
    });

    return totals;
  }, [selectedDateOrders]);

  const fetchAiAdvice = async () => {
    if (selectedDateOrders.length === 0) return;
    setIsAiLoading(true);
    const advice = await getSmartLoadingAdvice(selectedDateOrders);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedOrderId(id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, id: string) => {
    e.preventDefault();
    if (!draggedOrderId || draggedOrderId === id) return;

    const newOrders = [...orders];
    const draggedIdx = newOrders.findIndex(o => o.id === draggedOrderId);
    const targetIdx = newOrders.findIndex(o => o.id === id);

    if (draggedIdx > -1 && targetIdx > -1) {
      const [draggedItem] = newOrders.splice(draggedIdx, 1);
      newOrders.splice(targetIdx, 0, draggedItem);
      setOrders(newOrders);
    }
  };

  const handleDragEnd = () => {
    setDraggedOrderId(null);
  };

  const handleImportData = (data: any) => {
    if (data.orders) setOrders(data.orders);
    if (data.products) setProducts(data.products);
    if (data.clients) setClients(data.clients);
    setShowDataManager(false);
    alert('데이터가 성공적으로 복원되었습니다.');
  };

  // 거래처 관리에서 주문 버튼 클릭 시 핸들러
  const handleSelectClientForOrder = (clientName: string) => {
    setPreselectedClient(clientName);
    setShowClientManager(false);
    setShowOrderForm(true);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-4 py-4 md:px-8 shadow-sm">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg text-white shadow-lg shadow-blue-200">
              <Truck className="w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-slate-800 hidden sm:block">스마트 상차 플래너</h1>
          </div>

          <div className="flex flex-col items-center gap-2">
            <div className="flex items-center gap-2 md:gap-4">
              <button onClick={handlePrevMonth} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><ChevronLeft /></button>
              <h2 className="text-xl font-bold text-slate-700 min-w-[140px] text-center">{monthYear}</h2>
              <button onClick={handleNextMonth} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><ChevronRight /></button>
            </div>
            <div className="flex gap-2">
              <button onClick={() => setShowClientManager(true)} className="text-xs font-bold text-slate-500 hover:text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded-full transition-all border border-slate-200 hover:border-blue-200">거래처 관리</button>
              <button onClick={() => setShowProductManager(true)} className="text-xs font-bold text-slate-500 hover:text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded-full transition-all border border-slate-200 hover:border-blue-200">품목 관리</button>
            </div>
          </div>

          <div className="flex gap-2">
            <button onClick={() => { setCurrentDate(new Date()); setSelectedDate(formatDate(new Date())); }} className="text-base font-bold text-white bg-blue-600 hover:bg-blue-700 px-4 py-2 rounded-lg shadow-md transition-all active:scale-95">오늘</button>
            <button onClick={() => setShowDataManager(true)} className="p-2 text-slate-400 hover:text-slate-600 rounded-lg hover:bg-slate-100 transition-colors">
              <Settings className="w-6 h-6" />
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-4 md:p-6 flex flex-col lg:flex-row gap-6">
        <div className="flex-1 bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="calendar-grid bg-slate-50 border-b border-slate-200">
            {['일', '월', '화', '수', '목', '금', '토'].map((day, idx) => (
              <div key={day} className={`py-3 text-center text-sm font-bold uppercase tracking-wider ${idx === 0 ? 'text-red-500' : idx === 6 ? 'text-blue-500' : 'text-slate-400'}`}>{day}</div>
            ))}
          </div>
          <div className="calendar-grid divide-x divide-y divide-slate-100">
            {daysInMonth.map((date, idx) => {
              if (!date) return <div key={`empty-${idx}`} className="h-24 md:h-32 bg-slate-50/30" />;
              const dateStr = formatDate(date);
              const dayOrders = orders.filter(o => o.date === dateStr);
              const isSelected = selectedDate === dateStr;
              const isToday = formatDate(new Date()) === dateStr;
              const holidayName = getHolidayName(date);
              const dayOfWeek = date.getDay();
              const isSunday = dayOfWeek === 0;
              const isSaturday = dayOfWeek === 6;
              return (
                <div key={dateStr} onClick={() => setSelectedDate(dateStr)} className={`h-24 md:h-32 p-2 cursor-pointer transition-all hover:bg-blue-50/40 relative ${isSelected ? 'bg-blue-50 ring-2 ring-blue-500 ring-inset z-10' : ''}`}>
                  <div className="flex justify-between items-start">
                    <div className="flex flex-col items-center">
                      <span className={`text-base font-bold ${isToday ? 'bg-blue-600 text-white w-7 h-7 rounded-full flex items-center justify-center' : holidayName || isSunday ? 'text-red-500' : isSaturday ? 'text-blue-500' : 'text-slate-500'}`}>{date.getDate()}</span>
                      {holidayName && <span className="text-[11px] text-red-400 font-bold mt-0.5 truncate max-w-[45px]">{holidayName}</span>}
                    </div>
                    {dayOrders.length > 0 && <span className="bg-blue-100 text-blue-700 text-xs px-2 py-0.5 rounded-full font-bold">{dayOrders.length}</span>}
                  </div>
                  <div className="mt-2 space-y-1 overflow-hidden">
                    {dayOrders.slice(0, 2).map(o => (
                      <div key={o.id} className="text-xs text-slate-600 truncate bg-slate-100/80 px-1.5 py-0.5 rounded border border-slate-200">{o.clientName}</div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="w-full lg:w-96 flex flex-col gap-6">
          <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden flex flex-col h-full min-h-[600px]">
            <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50/80">
              <div>
                <h3 className="text-2xl font-black text-slate-800">{selectedDate}</h3>
                <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">DAILY LOADING LIST</p>
              </div>
              <button onClick={() => setShowOrderForm(true)} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-transform active:scale-90">
                <Plus className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-5 hide-scrollbar">
              {selectedDateOrders.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center py-20 grayscale opacity-30">
                  <Truck className="w-16 h-16 mb-4" />
                  <p className="font-bold text-lg">등록된 주문이 없습니다.</p>
                </div>
              ) : (
                <>
                  <div className="bg-blue-900 rounded-2xl p-4 text-white shadow-xl space-y-4">
                    <h4 className="text-xs font-black uppercase tracking-widest opacity-60">카테고리별 품목 합계</h4>
                    <div className="space-y-4">
                      {Object.entries(categoryTotals).map(([category, items]) => (
                        <div key={category} className="space-y-1">
                          <div className="text-xs font-black text-blue-400 border-b border-blue-800/50 pb-1 mb-2 uppercase">{category}</div>
                          {Object.entries(items).map(([name, count]) => (
                            <div key={name} className="flex justify-between items-center text-base">
                              <span className="font-medium opacity-90">{name}</span>
                              <span className="font-bold text-white">
                                {count}개
                              </span>
                            </div>
                          ))}
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="space-y-3">
                    {selectedDateOrders.map(order => (
                      <div 
                        key={order.id} 
                        draggable
                        onDragStart={(e) => handleDragStart(e, order.id)}
                        onDragOver={(e) => handleDragOver(e, order.id)}
                        onDragEnd={handleDragEnd}
                        className={`bg-white border-2 border-slate-100 rounded-2xl overflow-hidden shadow-sm hover:border-blue-200 transition-colors ${draggedOrderId === order.id ? 'opacity-40 grayscale' : ''}`}
                      >
                        <div className="px-4 py-2 bg-slate-50 flex justify-between items-center border-b border-slate-100">
                          <div className="flex items-center gap-2">
                            <div className="cursor-grab active:cursor-grabbing text-slate-300 hover:text-blue-400">
                              <GripVertical className="w-4 h-4" />
                            </div>
                            <span className="font-black text-base text-slate-800">{order.clientName}</span>
                          </div>
                          <div className="flex gap-1">
                            <button onClick={() => startEditOrder(order)} className="text-slate-300 hover:text-blue-500 transition-colors p-1" title="수정">
                                <Pencil className="w-4 h-4" />
                            </button>
                            <button onClick={(e) => deleteOrder(e, order.id)} className="text-slate-300 hover:text-red-500 transition-colors p-1" title="삭제">
                                <Trash className="w-4 h-4" />
                            </button>
                          </div>
                        </div>
                        <div className="p-1.5 space-y-0.5">
                          {order.items.map(item => (
                            <div 
                              key={item.id} 
                              onClick={() => toggleItemLoaded(order.id, item.id)} 
                              className={`flex items-center gap-2 px-2 py-1.5 rounded-lg cursor-pointer transition-all border ${item.isLoaded ? 'bg-green-50 border-green-100' : 'bg-white hover:bg-slate-50 border-transparent'}`}
                            >
                              <div className={`w-5 h-5 flex-shrink-0 rounded-md border-2 flex items-center justify-center transition-all ${item.isLoaded ? 'bg-green-500 border-green-500 text-white' : 'border-slate-200'}`}>
                                {item.isLoaded && <CheckCircle className="w-3.5 h-3.5" />}
                              </div>
                              <div className="flex-1 flex justify-between items-center gap-2 overflow-hidden">
                                <div className={`flex flex-col ${item.isLoaded ? 'opacity-40' : ''}`}>
                                  <span className="text-[10px] font-black text-blue-500 uppercase">{item.category}</span>
                                  <span className={`text-sm font-bold truncate ${item.isLoaded ? 'line-through text-green-800' : 'text-slate-700'}`}>
                                    {item.name}
                                  </span>
                                </div>
                                <div className={`flex-shrink-0 text-xs font-black px-1.5 py-0.5 rounded-md whitespace-nowrap ${item.isLoaded ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-600'}`}>
                                  {item.unitQuantity}개
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </>
              )}
            </div>

            {selectedDateOrders.length > 0 && (
              <div className="p-4 bg-slate-900 text-white">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-pulse" />
                    <span className="text-xs font-black tracking-widest text-blue-300">GEMINI LOADING ADVISOR</span>
                  </div>
                  {!aiAdvice && !isAiLoading && <button onClick={fetchAiAdvice} className="text-xs bg-blue-600 px-2 py-1 rounded font-bold hover:bg-blue-500 transition-colors">분석</button>}
                </div>
                {isAiLoading ? <div className="space-y-1 opacity-50"><div className="h-1.5 bg-slate-700 rounded w-full animate-pulse" /><div className="h-1.5 bg-slate-700 rounded w-2/3 animate-pulse" /></div> : aiAdvice && <p className="text-sm leading-relaxed font-medium text-slate-300">"{aiAdvice}"</p>}
              </div>
            )}
          </div>
        </div>
      </main>

      {showProductManager && <ProductManagerModal products={products} setProducts={setProducts} onClose={() => setShowProductManager(false)} />}
      {showClientManager && (
        <ClientManagerModal 
          clients={clients} 
          setClients={setClients} 
          onClose={() => setShowClientManager(false)} 
          onSelectForOrder={handleSelectClientForOrder}
        />
      )}
      {showDataManager && <DataManagerModal orders={orders} products={products} clients={clients} onImport={handleImportData} onClose={() => setShowDataManager(false)} />}
      {showOrderForm && (
        <OrderModal 
          onClose={() => {
            setShowOrderForm(false);
            setEditingOrder(null);
            setPreselectedClient(''); 
          }} 
          onSubmit={handleSaveOrder} 
          selectedDate={selectedDate || ""} 
          products={products} 
          clients={clients} 
          initialClientName={editingOrder ? editingOrder.clientName : preselectedClient}
          initialItemsStr={editingOrder ? reconstructItemsStr(editingOrder.items) : ''}
          isEditing={!!editingOrder}
          onOpenProductManager={() => { setShowOrderForm(false); setShowProductManager(true); }}
          onOpenClientManager={() => { setShowOrderForm(false); setShowClientManager(true); }}
        />
      )}
    </div>
  );
};

const DataManagerModal: React.FC<{ orders: Order[], products: ProductDefinition[], clients: ClientDefinition[], onImport: (data: any) => void, onClose: () => void }> = ({ orders, products, clients, onImport, onClose }) => {
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const csvInputRef = useRef<HTMLInputElement>(null);

  const handleExportJSON = () => {
    const data = {
      version: '4.0',
      exportedAt: new Date().toISOString(),
      orders,
      products,
      clients
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `smart_loading_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportCSV = () => {
    // CSV 헤더
    let csvContent = "날짜,거래처,주문내역\n";

    // 데이터 변환
    orders.forEach(order => {
        // 주문 내역 문자열로 변환 (예: 특크20 감천10)
        const itemsStr = order.items.map(i => {
            const p = products.find(prod => prod.id === i.productId);
            const code = p ? p.shortcut : i.name;
            return `${code}${i.unitQuantity}`;
        }).join(' ');

        // CSV 행 추가 (특수문자 처리 위해 따옴표 감싸기)
        csvContent += `"${order.date}","${order.clientName}","${itemsStr}"\n`;
    });

    // BOM 추가 (엑셀 한글 깨짐 방지)
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `smart_loading_list_${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleJSONFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (window.confirm('기존 데이터를 덮어쓰고 복원하시겠습니까? (JSON)')) {
          onImport(data);
        }
      } catch (err) {
        alert('올바른 백업 파일이 아닙니다.');
      }
    };
    reader.readAsText(file);
    // 입력값 초기화
    e.target.value = '';
  };

  const handleCSVFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
          const text = event.target?.result as string;
          if (!text) return;

          try {
              const lines = text.split('\n');
              const newOrders: Order[] = [];
              let successCount = 0;

              // 첫 줄(헤더) 건너뛰고 파싱
              for (let i = 1; i < lines.length; i++) {
                  const line = lines[i].trim();
                  if (!line) continue;

                  // CSV 파싱 (따옴표 제거 및 콤마 분리 - 간단한 파서)
                  // 주의: 데이터 내에 콤마가 있으면 오동작할 수 있음. 
                  // 여기서는 "날짜","거래처","주문내역" 형태를 가정하고 정규식으로 처리하거나 간단히 split.
                  // 정규식: 콤마로 구분하되 따옴표 내의 콤마는 무시
                  const cols = line.match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);

                  if (cols && cols.length >= 3) {
                      const date = cols[0].replace(/^"|"$/g, '').trim();
                      const clientName = cols[1].replace(/^"|"$/g, '').trim();
                      const itemsStr = cols[2].replace(/^"|"$/g, '').trim();

                      // 주문 내역 파싱 (App.tsx의 parseShortcuts 로직 복제)
                      const parts = itemsStr.split(/[\s,]+/).map(p => p.trim()).filter(p => p !== "");
                      const parsedItems: OrderItem[] = [];

                      parts.forEach(part => {
                          const match = part.match(/^([a-zA-Z가-힣]+)(\d+)$/);
                          if (match) {
                              const shortcut = match[1].toUpperCase();
                              const unitQty = parseInt(match[2], 10) || 0;
                              const product = products.find(p => p.shortcut.toUpperCase() === shortcut);
                              if (product) {
                                  parsedItems.push({
                                      id: Math.random().toString(36).substr(2, 9),
                                      productId: product.id,
                                      name: product.name,
                                      category: product.category,
                                      unitQuantity: unitQty,
                                      isLoaded: false
                                  });
                              }
                          }
                      });

                      if (parsedItems.length > 0) {
                          newOrders.push({
                              id: Math.random().toString(36).substr(2, 9),
                              date: date,
                              clientName: clientName,
                              createdAt: Date.now(),
                              items: parsedItems
                          });
                          successCount++;
                      }
                  }
              }

              if (newOrders.length > 0) {
                  if (window.confirm(`${successCount}건의 주문을 CSV에서 불러왔습니다.\n기존 주문 데이터를 덮어쓰시겠습니까?`)) {
                      onImport({ orders: newOrders });
                  }
              } else {
                  alert('불러올 수 있는 유효한 주문 데이터가 없습니다.');
              }
          } catch (err) {
              console.error(err);
              alert('CSV 파일을 읽는 중 오류가 발생했습니다.');
          }
      };
      reader.readAsText(file);
      e.target.value = '';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center flex-shrink-0">
          <h3 className="text-2xl font-black text-slate-800">데이터 백업 및 복구</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button>
        </div>
        <div className="p-8 space-y-6 overflow-y-auto">
          <div className="bg-blue-50 p-4 rounded-xl text-base text-blue-700 leading-relaxed font-medium">
            데이터를 안전하게 보관하거나, 엑셀 호환(CSV) 파일로 주문 내역을 관리하세요.
          </div>

          <div className="space-y-3">
            <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">전체 백업 (JSON)</h4>
            <div className="grid grid-cols-2 gap-4">
              <button onClick={handleExportJSON} className="flex flex-col items-center justify-center gap-3 p-4 bg-white border-2 border-slate-100 hover:border-blue-500 rounded-2xl transition-all group shadow-sm hover:shadow-lg">
                <div className="bg-slate-100 p-3 rounded-full text-slate-500 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                  <Download className="w-6 h-6" />
                </div>
                <span className="font-bold text-slate-600 group-hover:text-slate-900">백업 파일 생성</span>
              </button>
              <button onClick={() => jsonInputRef.current?.click()} className="flex flex-col items-center justify-center gap-3 p-4 bg-white border-2 border-slate-100 hover:border-green-500 rounded-2xl transition-all group shadow-sm hover:shadow-lg">
                <div className="bg-slate-100 p-3 rounded-full text-slate-500 group-hover:bg-green-600 group-hover:text-white transition-colors">
                  <Upload className="w-6 h-6" />
                </div>
                <span className="font-bold text-slate-600 group-hover:text-slate-900">백업 불러오기</span>
              </button>
            </div>
          </div>

          <div className="space-y-3">
            <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">주문 목록 (CSV)</h4>
            <div className="grid grid-cols-2 gap-4">
              <button onClick={handleExportCSV} className="flex flex-col items-center justify-center gap-3 p-4 bg-white border-2 border-slate-100 hover:border-blue-500 rounded-2xl transition-all group shadow-sm hover:shadow-lg">
                <div className="bg-slate-100 p-3 rounded-full text-slate-500 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                  <Download className="w-6 h-6" />
                </div>
                <span className="font-bold text-slate-600 group-hover:text-slate-900">CSV 내보내기</span>
              </button>
              <button onClick={() => csvInputRef.current?.click()} className="flex flex-col items-center justify-center gap-3 p-4 bg-white border-2 border-slate-100 hover:border-green-500 rounded-2xl transition-all group shadow-sm hover:shadow-lg">
                <div className="bg-slate-100 p-3 rounded-full text-slate-500 group-hover:bg-green-600 group-hover:text-white transition-colors">
                  <Upload className="w-6 h-6" />
                </div>
                <span className="font-bold text-slate-600 group-hover:text-slate-900">CSV 불러오기</span>
              </button>
            </div>
          </div>

          <input type="file" ref={jsonInputRef} onChange={handleJSONFileChange} accept=".json" className="hidden" />
          <input type="file" ref={csvInputRef} onChange={handleCSVFileChange} accept=".csv" className="hidden" />
        </div>
      </div>
    </div>
  );
};

const ProductManagerModal: React.FC<{ 
  products: ProductDefinition[], 
  setProducts: any, 
  onClose: () => void
}> = ({ products, setProducts, onClose }) => {
  const [name, setName] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [expandedCategories, setExpandedCategories] = useState<string[]>([]);

  const categories = useMemo(() => Array.from(new Set(products.map(p => p.category))).filter(Boolean), [products]);

  // Group products by category
  const productsByCategory = useMemo(() => {
    const grouped: Record<string, ProductDefinition[]> = {};
    products.forEach(p => {
      const cat = p.category || '기타';
      if (!grouped[cat]) grouped[cat] = [];
      grouped[cat].push(p);
    });
    return grouped;
  }, [products]);

  const toggleCategory = (cat: string) => {
    setExpandedCategories(prev => 
      prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]
    );
  };

  const startEdit = (p: ProductDefinition) => {
    setEditingId(p.id);
    setName(p.name);
    setShortcut(p.shortcut);
    setCategory(p.category || '');

    // Auto expand category when editing
    const cat = p.category || '기타';
    if (!expandedCategories.includes(cat)) {
      setExpandedCategories(prev => [...prev, cat]);
    }
  };

  const cancelEdit = () => {
    setEditingId(null);
    setName('');
    setShortcut('');
    setCategory('');
  };

  const save = () => {
    if(!name || !shortcut || !category) return;

    // Auto expand target category
    const targetCat = category || '기타';
    if (!expandedCategories.includes(targetCat)) {
      setExpandedCategories(prev => [...prev, targetCat]);
    }

    if (editingId) {
      setProducts(products.map(p => p.id === editingId ? { ...p, name, shortcut: shortcut.toUpperCase(), category } : p));
      cancelEdit();
    } else {
      setProducts([...products, { id: Math.random().toString(36).substr(2, 9), name, shortcut: shortcut.toUpperCase(), category }]);
      cancelEdit();
    }
  };

  const remove = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('삭제하시겠습니까?')) {
      setProducts((prev: ProductDefinition[]) => prev.filter(p => p.id !== id));
      if (editingId === id) cancelEdit();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-3xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center flex-shrink-0 bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-800">품목 마스터 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button>
        </div>

        <div className="p-4 flex flex-col gap-4 overflow-hidden h-full">
          {/* 입력 폼 (Compact) */}
          <div className="bg-slate-50 p-3 rounded-xl border border-slate-200 flex-shrink-0 shadow-sm">
            <div className="flex flex-col md:flex-row gap-3 items-center">
              <div className="flex items-center gap-2 w-full md:flex-1">
                <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-12 text-right">카테고리</span>
                <input list="category-list" value={category} onChange={e => setCategory(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="선택/입력" />
                <datalist id="category-list">
                  {categories.map(c => <option key={c} value={c} />)}
                </datalist>
              </div>

              <div className="flex items-center gap-2 w-full md:flex-[1.5]">
                <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-10 text-right">품목명</span>
                <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="품목 이름" />
              </div>

              <div className="flex items-center gap-2 w-full md:w-48">
                <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-10 text-right">단축어</span>
                <input type="text" value={shortcut} onChange={e => setShortcut(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="키(Key)" />
              </div>

              <div className="flex items-center gap-2 w-full md:w-auto pl-1">
                {editingId && <button onClick={cancelEdit} className="px-3 py-2 text-sm font-bold text-slate-500 hover:bg-slate-200 rounded-lg whitespace-nowrap">취소</button>}
                <button onClick={save} className={`px-5 py-2 text-base font-bold text-white rounded-lg transition-colors whitespace-nowrap shadow-md active:scale-95 ${editingId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-800 hover:bg-slate-900'}`}>
                  {editingId ? '수정' : '추가'}
                </button>
              </div>
            </div>
          </div>

          {/* 목록 (카테고리별 그룹핑) */}
          <div className="flex flex-col gap-2 flex-1 overflow-hidden">
            <div className="flex justify-between items-end px-1 pb-1 border-b border-slate-100">
                <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">등록된 품목 리스트</h4>
                <span className="text-xs text-slate-400 font-medium">총 {products.length}개</span>
            </div>
            <div className="flex-1 space-y-2 overflow-y-auto pr-1 hide-scrollbar">
              {Object.entries(productsByCategory).sort((a, b) => {
                const indexA = CATEGORY_ORDER.indexOf(a[0]);
                const indexB = CATEGORY_ORDER.indexOf(b[0]);
                if (indexA !== -1 && indexB !== -1) return indexA - indexB;
                if (indexA !== -1) return -1;
                if (indexB !== -1) return 1;
                return a[0].localeCompare(b[0]);
              }).map(([cat, itemsRaw]) => {
                const items = itemsRaw as ProductDefinition[];
                return (
                <div key={cat} className="space-y-1">
                   {/* Category Header */}
                   <button 
                     onClick={() => toggleCategory(cat)}
                     className={`w-full flex justify-between items-center p-3 rounded-xl transition-all ${expandedCategories.includes(cat) ? 'bg-slate-100 text-slate-800' : 'bg-white border border-slate-100 text-slate-600 hover:bg-slate-50'}`}
                   >
                     <div className="flex items-center gap-2">
                       <div className={`transform transition-transform duration-200 ${expandedCategories.includes(cat) ? 'rotate-90' : ''}`}>
                          <ChevronRight className="w-4 h-4" />
                       </div>
                       <span className="font-black text-base">{cat}</span>
                     </div>
                     <span className="text-xs font-bold bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full">{items.length}개</span>
                   </button>

                   {/* Products List */}
                   {expandedCategories.includes(cat) && (
                     <div className="space-y-2 pl-2 border-l-2 border-slate-100 ml-3 py-1">
                       {items.map(p => {
                         return (
                           <div key={p.id} className={`flex justify-between items-center p-3 border rounded-xl group transition-all hover:shadow-sm ${editingId === p.id ? 'bg-blue-50 border-blue-300 ring-1 ring-blue-300' : 'bg-white border-slate-100 hover:border-blue-200'}`}>
                             <div className="flex items-center gap-4 flex-1">
                               <div className="flex-1 min-w-[100px]">
                                   <div className="font-bold text-base text-slate-800">{p.name}</div>
                               </div>
                               <div className="w-20">
                                   <div className="text-xs font-bold text-slate-400">단축어 <span className="text-blue-600 bg-blue-50 px-1 rounded">{p.shortcut}</span></div>
                               </div>
                             </div>

                             <div className="flex items-center gap-4">
                               <div className="flex gap-1">
                                 <button onClick={() => startEdit(p)} className="p-1.5 text-slate-400 hover:text-blue-600 rounded-lg hover:bg-blue-50 transition-colors"><Pencil className="w-4 h-4" /></button>
                                 <button onClick={(e) => remove(e, p.id)} className="p-1.5 text-slate-400 hover:text-red-500 rounded-lg hover:bg-red-50 transition-colors"><Trash className="w-4 h-4" /></button>
                               </div>
                             </div>
                           </div>
                         );
                       })}
                     </div>
                   )}
                </div>
              )})}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const ClientManagerModal: React.FC<{ 
  clients: ClientDefinition[], 
  setClients: any, 
  onClose: () => void,
  onSelectForOrder?: (clientName: string) => void
}> = ({ clients, setClients, onClose, onSelectForOrder }) => {
  const [formData, setFormData] = useState<Partial<ClientDefinition>>({});
  const [editingId, setEditingId] = useState<string | null>(null);
  const [draggedClientId, setDraggedClientId] = useState<string | null>(null);

  const startEdit = (c: ClientDefinition) => {
    setEditingId(c.id);
    setFormData(c);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setFormData({});
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const save = () => {
    if(!formData.name) return;
    if (editingId) {
      setClients(clients.map(c => c.id === editingId ? { ...c, ...formData } : c));
      cancelEdit();
    } else {
      setClients([...clients, { id: Math.random().toString(36).substr(2, 9), ...formData } as ClientDefinition]);
      cancelEdit();
    }
  };

  const remove = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('삭제하시겠습니까?')) {
      setClients((prev: ClientDefinition[]) => prev.filter(c => c.id !== id));
      if (editingId === id) cancelEdit();
    }
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedClientId(id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, id: string) => {
    e.preventDefault();
    if (!draggedClientId || draggedClientId === id) return;

    const sourceIndex = clients.findIndex(c => c.id === draggedClientId);
    const targetIndex = clients.findIndex(c => c.id === id);

    if (sourceIndex > -1 && targetIndex > -1) {
      const newClients = [...clients];
      const [movedItem] = newClients.splice(sourceIndex, 1);
      newClients.splice(targetIndex, 0, movedItem);
      setClients(newClients);
    }
  };

  const handleDragEnd = () => {
    setDraggedClientId(null);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center flex-shrink-0">
          <h3 className="text-2xl font-black text-slate-800">거래처 마스터 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button>
        </div>

        <div className="flex flex-col h-full overflow-hidden">
          {/* 상단: 입력 폼 (위치 변경됨) */}
          <div className="bg-slate-50 p-6 border-b border-slate-200 flex-shrink-0">
            <div className="flex justify-between items-center mb-4">
              <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">{editingId ? '거래처 정보 수정' : '새 거래처 등록'}</h4>
              {editingId && <button onClick={cancelEdit} className="text-xs font-bold text-red-500 hover:bg-red-50 px-2 py-1 rounded">입력 취소</button>}
            </div>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
              <div className="md:col-span-1">
                <label className="text-xs font-bold text-slate-400 ml-1 mb-1 block">거래처명 (필수)</label>
                <input name="name" value={formData.name || ''} onChange={handleChange} placeholder="거래처명 입력" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div className="md:col-span-1">
                <label className="text-xs font-bold text-slate-400 ml-1 mb-1 block">거래처 단축명</label>
                <input name="shortcut" value={formData.shortcut || ''} onChange={handleChange} placeholder="예: 한울, 대한" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div className="md:col-span-1">
                <label className="text-xs font-bold text-slate-400 ml-1 mb-1 block">전화번호</label>
                <input name="phone" value={formData.phone || ''} onChange={handleChange} placeholder="010-0000-0000" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" />
              </div>
              <div className="md:col-span-1">
                <button onClick={save} className={`w-full text-white py-2.5 rounded-xl font-bold transition-all shadow-lg active:scale-95 ${editingId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-900 hover:bg-slate-800'}`}>{editingId ? '수정 내용 저장' : '새 거래처 추가하기'}</button>
              </div>
            </div>
          </div>

          {/* 하단: 리스트 */}
          <div className="flex-1 overflow-y-auto p-6 bg-white">
            <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-3">등록된 거래처 ({clients.length})</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {clients.map(c => (
                <div 
                  key={c.id} 
                  draggable
                  onDragStart={(e) => handleDragStart(e, c.id)}
                  onDragOver={(e) => handleDragOver(e, c.id)}
                  onDragEnd={handleDragEnd}
                  className={`flex justify-between items-center p-3 border rounded-xl group transition-all cursor-move ${editingId === c.id ? 'bg-blue-50 border-blue-300 ring-1 ring-blue-300' : 'bg-slate-50 border-slate-200'} ${draggedClientId === c.id ? 'opacity-40 border-dashed border-blue-400' : ''}`}
                >
                  <div className="flex items-center gap-3 overflow-hidden flex-1">
                    <div className="cursor-grab active:cursor-grabbing text-slate-300 hover:text-blue-500 flex-shrink-0">
                      <GripVertical className="w-5 h-5" />
                    </div>
                    <div className="overflow-hidden flex-1">
                      {c.phone ? (
                        <a href={`tel:${c.phone}`} onClick={(e) => e.stopPropagation()} className="font-bold text-base text-slate-800 truncate hover:text-blue-600 hover:underline block cursor-pointer">
                          {c.name}
                        </a>
                      ) : (
                        <div className="font-bold text-base text-slate-800 truncate">{c.name}</div>
                      )}
                      <div className="text-xs text-slate-400 truncate">
                        {c.shortcut ? <span className="text-blue-600 font-bold">[{c.shortcut}] </span> : ''}
                        {c.phone || '번호없음'}
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-1 flex-shrink-0">
                    {onSelectForOrder && (
                      <button onClick={() => onSelectForOrder(c.name)} className="p-1.5 text-white bg-blue-500 hover:bg-blue-600 rounded-lg transition-colors shadow-sm" title="이 거래처로 주문 등록">
                        <Plus className="w-4 h-4" />
                      </button>
                    )}
                    <button onClick={() => startEdit(c)} className="p-1.5 text-slate-400 hover:text-blue-600 rounded-lg hover:bg-blue-100 transition-colors"><Pencil className="w-4 h-4" /></button>
                    <button onClick={(e) => remove(e, c.id)} className="p-1.5 text-slate-400 hover:text-red-500 rounded-lg hover:bg-red-100 transition-colors"><Trash className="w-4 h-4" /></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const OrderModal: React.FC<{ 
  onClose: () => void, 
  onSubmit: (c: string, i: string) => void, 
  selectedDate: string, 
  products: ProductDefinition[], 
  clients: ClientDefinition[],
  initialClientName?: string,
  initialItemsStr?: string,
  isEditing?: boolean,
  onOpenProductManager: () => void,
  onOpenClientManager: () => void
}> = ({ onClose, onSubmit, selectedDate, products, clients, initialClientName, initialItemsStr, isEditing, onOpenProductManager, onOpenClientManager }) => {
  const [client, setClient] = useState(initialClientName || '');
  const [items, setItems] = useState(initialItemsStr || '');
  const [registrationPrompt, setRegistrationPrompt] = useState<{ type: 'client' | 'product', missing: string } | null>(null);

  const clientInputRef = useRef<HTMLInputElement>(null);
  const itemsInputRef = useRef<HTMLTextAreaElement>(null);

  // 초기값이 있으면 설정 및 포커스 관리
  useEffect(() => {
    if (initialClientName) setClient(initialClientName);
    if (initialItemsStr) setItems(initialItemsStr);

    if (isEditing) {
        setTimeout(() => clientInputRef.current?.focus(), 100);
    } else if (initialClientName) {
        // 거래처가 미리 선택된 경우 품목 입력창에 포커스
        setTimeout(() => itemsInputRef.current?.focus(), 100);
    } else {
        // 거래처가 없는 경우 거래처 입력창에 포커스
        setTimeout(() => clientInputRef.current?.focus(), 100);
    }
  }, [initialClientName, initialItemsStr, isEditing]);

  const filteredClients = useMemo<ClientDefinition[]>(() => {
    const term = client.trim().toLowerCase();
    if (!term) return [];
    return clients.filter(c => 
      c.name.toLowerCase().includes(term) || 
      (c.shortcut && c.shortcut.toLowerCase().includes(term))
    );
  }, [client, clients]);

  const handleInitialSubmit = () => {
    if (!client || !items) return;

    let targetClientName = client;
    const trimmedClient = client.trim();

    // 1. 정확한 거래처명 일치 확인
    const exactNameMatch = clients.find(c => c.name === trimmedClient);

    if (exactNameMatch) {
      targetClientName = exactNameMatch.name;
    } else {
      // 2. 정확한 단축어 일치 확인
      const exactShortcutMatch = clients.find(c => c.shortcut === trimmedClient);
      if (exactShortcutMatch) {
        targetClientName = exactShortcutMatch.name;
      } else {
        // 3. 부분 일치가 1개뿐인 경우 자동 설정
        const partialMatches = clients.filter(c => c.name.includes(trimmedClient));
        if (partialMatches.length === 1) {
          targetClientName = partialMatches[0].name;
        } else {
          setRegistrationPrompt({ type: 'client', missing: client });
          return;
        }
      }
    }

    const parts = items.split(/[\s,]+/).map(p => p.trim()).filter(p => p !== "");
    for (const part of parts) {
      // 정규식 수정: [단축어][수량]
      const match = part.match(/^([a-zA-Z가-힣]+)(\d+)$/);
      if (match) {
        const sc = match[1].toUpperCase();
        if (!products.some(p => p.shortcut.toUpperCase() === sc)) {
          setRegistrationPrompt({ type: 'product', missing: sc });
          return;
        }
      } else {
        alert(`입력 형식이 잘못되었습니다: ${part}\n(예: A20 B30)`);
        return;
      }
    }

    onSubmit(targetClientName, items);
  };

  const handleClientKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();

      const term = client.trim();
      if (!term) return;

      let resolvedName = term;
      const exactNameMatch = clients.find(c => c.name === term);
      if (exactNameMatch) {
        resolvedName = exactNameMatch.name;
      } else {
        const exactShortcutMatch = clients.find(c => c.shortcut === term);
        if (exactShortcutMatch) {
          resolvedName = exactShortcutMatch.name;
        } else {
           const partialMatches = clients.filter(c => c.name.includes(term));
           if (partialMatches.length === 1) {
             resolvedName = partialMatches[0].name;
           }
        }
      }

      setClient(resolvedName);
      itemsInputRef.current?.focus();
    }
  };

  const handleItemsKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      if (registrationPrompt) return; 
      e.preventDefault();
      handleInitialSubmit();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all">
        {registrationPrompt ? (
          <div className="p-8 text-center">
            <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
              <Plus className="w-8 h-8" />
            </div>
            <h3 className="text-xl font-black text-slate-800 mb-2">
              {registrationPrompt.type === 'client' ? '거래처가 없습니다' : '품목이 없습니다'}
            </h3>
            <p className="text-base font-medium text-slate-500 mb-6 leading-relaxed">
              "<span className="font-bold text-blue-600">{registrationPrompt.missing}</span>" 은(는) 등록되지 않은 {registrationPrompt.type === 'client' ? '거래처' : '품목'}입니다.<br/>
              새롭게 등록하시겠습니까?
            </p>
            <div className="flex gap-3">
              <button onClick={() => setRegistrationPrompt(null)} className="flex-1 py-4 text-base font-bold text-slate-400 bg-slate-50 rounded-2xl hover:bg-slate-100 transition-colors">아니오</button>
              <button onClick={registrationPrompt.type === 'client' ? onOpenClientManager : onOpenProductManager} className="flex-1 py-4 text-base font-bold text-white bg-blue-600 rounded-2xl hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all active:scale-95">예 (등록하기)</button>
            </div>
          </div>
        ) : (
          <>
            <div className="p-6">
              <h3 className="text-3xl font-black text-slate-800 mb-1">{isEditing ? '주문 내역 수정' : '상차 주문 등록'}</h3><p className="text-base font-bold text-slate-400 mb-6">{selectedDate}</p>
              <div className="space-y-5">
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase mb-1.5 ml-1">거래처 선택 또는 직접 입력</label>
                  <div className="relative">
                    <input 
                      ref={clientInputRef}
                      type="text" 
                      value={client} 
                      onChange={(e) => setClient(e.target.value)} 
                      onKeyDown={handleClientKeyDown} 
                      placeholder="거래처 명 또는 단축어 입력" 
                      className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-base font-bold text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none transition-all" 
                    />
                    {filteredClients.length > 0 && client !== filteredClients[0].name && (
                      <div className="absolute top-full left-0 right-0 z-10 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl max-h-40 overflow-y-auto p-2">
                        {filteredClients.map(c => (
                          <div 
                            key={c.id} 
                            onClick={() => {
                              setClient(c.name);
                              itemsInputRef.current?.focus();
                            }} 
                            className="p-2 text-base font-bold hover:bg-slate-50 rounded-lg cursor-pointer flex justify-between items-center"
                          >
                            <span>{c.name}</span>
                            {c.shortcut && <span className="text-xs bg-blue-50 text-blue-600 px-1.5 py-0.5 rounded ml-2">{c.shortcut}</span>}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase mb-1.5 ml-1">품목 수량 입력 (띄어쓰기로 구분)</label>
                  <textarea 
                    ref={itemsInputRef}
                    rows={3} 
                    value={items} 
                    onChange={(e) => setItems(e.target.value)} 
                    onKeyDown={handleItemsKeyDown} 
                    placeholder="특크20 감천10 판빙5 (단축어+수량 띄어쓰기)" 
                    className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-base font-bold text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none" 
                  />
                  <div className="mt-3 bg-blue-50 p-4 rounded-xl border border-blue-100 space-y-2">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-black bg-blue-600 text-white px-1.5 py-0.5 rounded">TIP</span>
                      <p className="text-xs font-bold text-blue-700">입력 형식 안내 (박스 없음, 낱개만 입력):</p>
                    </div>
                    <ul className="text-[11px] text-blue-600 font-medium list-disc pl-4 space-y-1">
                      <li><span className="font-bold">특크20</span> : 특크릴 20개 (단축어특크 + 수량20)</li>
                      <li><span className="font-bold">감천10</span> : 감성천하 10개</li>
                      <li><span className="font-bold">특크20 감천10</span> : 띄어쓰기로 여러 품목 입력</li>
                    </ul>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-slate-50 p-5 flex gap-3 border-t border-slate-100">
              <button onClick={onClose} className="flex-1 px-4 py-4 text-base font-bold text-slate-400 hover:text-slate-600 transition-colors">취소</button>
              <button onClick={handleInitialSubmit} className="flex-[2] bg-blue-600 hover:bg-blue-700 px-4 py-4 text-base font-black text-white rounded-2xl transition-all shadow-xl disabled:opacity-30" disabled={!client || !items}>{isEditing ? '주문 수정하기' : '주문 생성하기'}</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Order, OrderItem, ProductDefinition, ClientDefinition } from './types';
import { ChevronLeft, ChevronRight, Plus, Truck, CheckCircle, Trash, GripVertical, Settings, Pencil, Download, Upload } from './components/Icons';
import { getSmartLoadingAdvice } from './services/geminiService';

const HOLIDAYS: Record<string, string> = {
  '01-01': '신정',
  '03-01': '삼일절',
  '05-05': '어린이날',
  '06-06': '현충일',
  '08-15': '광복절',
  '10-03': '개천절',
  '10-09': '한글날',
  '12-25': '성탄절',
  '2025-01-28': '설날',
  '2025-01-29': '설날',
  '2025-01-30': '설날',
  '2025-05-05': '부처님오신날',
  '2025-10-05': '추석',
  '2025-10-06': '추석',
  '2025-10-07': '추석',
  '2025-10-08': '대체공휴일'
};

const CATEGORY_ORDER = ['크릴', '파우다', '생물', '기타'];

const App: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('smart_orders_v10'); 
    return saved ? JSON.parse(saved) : [];
  });

  const [products, setProducts] = useState<ProductDefinition[]>(() => {
    const saved = localStorage.getItem('smart_products_v10');
    return saved ? JSON.parse(saved) : []; 
  });

  const [clients, setClients] = useState<ClientDefinition[]>(() => {
    const saved = localStorage.getItem('smart_clients_v10');
    return saved ? JSON.parse(saved) : []; 
  });

  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(() => {
    const d = new Date();
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  });
  const [showOrderForm, setShowOrderForm] = useState(false);
  const [showProductManager, setShowProductManager] = useState(false);
  const [showClientManager, setShowClientManager] = useState(false);
  const [showDataManager, setShowDataManager] = useState(false);
  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [draggedOrderId, setDraggedOrderId] = useState<string | null>(null);

  const [preselectedClient, setPreselectedClient] = useState<string>('');
  const [editingOrder, setEditingOrder] = useState<Order | null>(null);

  useEffect(() => {
    localStorage.setItem('smart_orders_v10', JSON.stringify(orders));
  }, [orders]);

  useEffect(() => {
    localStorage.setItem('smart_products_v10', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('smart_clients_v10', JSON.stringify(clients));
  }, [clients]);

  function formatDate(date: Date) {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  const getHolidayName = (date: Date) => {
    const fullDate = formatDate(date);
    const monthDay = fullDate.substring(5);
    return HOLIDAYS[fullDate] || HOLIDAYS[monthDay] || null;
  };

  const monthYear = useMemo(() => {
    return currentDate.toLocaleString('ko-KR', { month: 'long', year: 'numeric' });
  }, [currentDate]);

  const daysInMonth = useMemo(() => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) days.push(new Date(year, month, i));
    return days;
  }, [currentDate]);

  const handlePrevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const handleNextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const parseShortcuts = (input: string): OrderItem[] => {
    const parts = input.split(/[\s,]+/).map(p => p.trim()).filter(p => p !== "");
    const parsedItems: OrderItem[] = [];

    parts.forEach(part => {
      const match = part.match(/^([a-zA-Z가-힣]+)(\d+)$/);
      if (match) {
        const shortcut = match[1].toUpperCase();
        const unitQty = parseInt(match[2], 10) || 0;
        const product = products.find(p => p.shortcut.toUpperCase() === shortcut);
        if (product) {
          parsedItems.push({
            id: Math.random().toString(36).substr(2, 9),
            productId: product.id,
            name: product.name,
            category: product.category,
            unitQuantity: unitQty,
            isLoaded: false
          });
        }
      }
    });
    return parsedItems;
  };

  const reconstructItemsStr = (items: OrderItem[]) => {
    return items.map(i => {
        const p = products.find(prod => prod.id === i.productId);
        const code = p ? p.shortcut : i.name;
        return `${code}${i.unitQuantity}`;
    }).join(' ');
  };

  const handleSaveOrder = (clientName: string, itemsStr: string) => {
    if (!selectedDate || !clientName || !itemsStr) return;
    const items = parseShortcuts(itemsStr);
    if (items.length === 0) return;

    if (editingOrder) {
      setOrders(prev => prev.map(o => o.id === editingOrder.id ? { ...o, clientName, items } : o));
      setEditingOrder(null);
    } else {
      const newOrder: Order = {
        id: Math.random().toString(36).substr(2, 9),
        clientName,
        date: selectedDate,
        createdAt: Date.now(),
        items
      };
      setOrders(prev => [...prev, newOrder]);
    }
    setShowOrderForm(false);
    setPreselectedClient('');
  };

  const deleteOrder = (e: React.MouseEvent, orderId: string) => {
    e.stopPropagation();
    if (confirm('이 주문을 삭제하시겠습니까?')) {
      setOrders(prev => prev.filter(o => o.id !== orderId));
    }
  };

  const startEditOrder = (order: Order) => {
    setEditingOrder(order);
    setShowOrderForm(true);
  };

  const toggleItemLoaded = (orderId: string, itemId: string) => {
    setOrders(prev => prev.map(order => {
      if (order.id !== orderId) return order;
      return {
        ...order,
        items: order.items.map(item => item.id === itemId ? { ...item, isLoaded: !item.isLoaded } : item)
      };
    }));
  };

  const selectedDateOrders = useMemo(() => {
    if (!selectedDate) return [];
    return orders.filter(o => o.date === selectedDate);
  }, [orders, selectedDate]);

  const categoryTotals = useMemo(() => {
    const totals: Record<string, Record<string, number>> = {};
    selectedDateOrders.forEach(o => {
      o.items.forEach(i => {
        const cat = i.category || '기타';
        if (!totals[cat]) totals[cat] = {};
        if (!totals[cat][i.name]) totals[cat][i.name] = 0;
        totals[cat][i.name] += i.unitQuantity;
      });
    });
    return totals;
  }, [selectedDateOrders]);

  const fetchAiAdvice = async () => {
    if (selectedDateOrders.length === 0) return;
    setIsAiLoading(true);
    const advice = await getSmartLoadingAdvice(selectedDateOrders);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedOrderId(id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, id: string) => {
    e.preventDefault();
    if (!draggedOrderId || draggedOrderId === id) return;
    const newOrders = [...orders];
    const draggedIdx = newOrders.findIndex(o => o.id === draggedOrderId);
    const targetIdx = newOrders.findIndex(o => o.id === id);
    if (draggedIdx > -1 && targetIdx > -1) {
      const [draggedItem] = newOrders.splice(draggedIdx, 1);
      newOrders.splice(targetIdx, 0, draggedItem);
      setOrders(newOrders);
    }
  };

  const handleDragEnd = () => setDraggedOrderId(null);

  const handleImportData = (data: any) => {
    if (data.orders) setOrders(data.orders);
    if (data.products) setProducts(data.products);
    if (data.clients) setClients(data.clients);
    setShowDataManager(false);
    alert('데이터가 성공적으로 복원되었습니다.');
  };

  const handleSelectClientForOrder = (clientName: string) => {
    setPreselectedClient(clientName);
    setShowClientManager(false);
    setShowOrderForm(true);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-4 py-4 md:px-8 shadow-sm">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg text-white shadow-lg shadow-blue-200">
              <Truck className="w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-slate-800 hidden sm:block">스마트 상차 플래너</h1>
          </div>

          <div className="flex flex-col items-center gap-2">
            <div className="flex items-center gap-2 md:gap-4">
              <button onClick={handlePrevMonth} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><ChevronLeft /></button>
              <h2 className="text-xl font-bold text-slate-700 min-w-[140px] text-center">{monthYear}</h2>
              <button onClick={handleNextMonth} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><ChevronRight /></button>
            </div>
            <div className="flex gap-2">
              <button onClick={() => setShowClientManager(true)} className="text-xs font-bold text-slate-500 hover:text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded-full transition-all border border-slate-200 hover:border-blue-200">거래처 관리</button>
              <button onClick={() => setShowProductManager(true)} className="text-xs font-bold text-slate-500 hover:text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded-full transition-all border border-slate-200 hover:border-blue-200">품목 관리</button>
            </div>
          </div>

          <div className="flex gap-2">
