const DataManagerModal: React.FC<{ orders: Order[], products: ProductDefinition[], clients: ClientDefinition[], onImport: (data: any) => void, onClose: () => void }> = ({ orders, products, clients, onImport, onClose }) => {
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const csvInputRef = useRef<HTMLInputElement>(null);

  const handleExportJSON = () => {
    const data = { version: '1.0', orders, products, clients };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportCSV = () => {
    let csv = "날짜,거래처,주문내역\n";
    orders.forEach(o => {
      const itemsStr = o.items.map(i => {
        const p = products.find(prod => prod.id === i.productId);
        return `${p ? p.shortcut : i.name}${i.unitQuantity}`;
      }).join(' ');
      csv += `"${o.date}","${o.clientName}","${itemsStr}"\n`;
    });
    const blob = new Blob(["\uFEFF" + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `orders_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>, type: 'JSON' | 'CSV') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      if (type === 'JSON') {
        try { onImport(JSON.parse(content)); } catch { alert('오류'); }
      } else {
        // Simple CSV Parser logic
        const lines = content.split('\n').slice(1);
        const newOrders: Order[] = lines.map(l => {
          const m = l.match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);
          if (!m || m.length < 3) return null;
          const [d, c, i] = m.map(v => v.replace(/^"|"$/g, ''));
          // Shortcut Parser 복구 생략, JSON 권장
          return { id: Math.random().toString(36).substr(2, 9), date: d, clientName: c, items: [], createdAt: Date.now() };
        }).filter(v => v) as Order[];
        if (newOrders.length > 0) onImport({ orders: newOrders });
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg flex flex-col p-8 space-y-6">
        <div className="flex justify-between items-center"><h3 className="text-2xl font-black">데이터 관리</h3><button onClick={onClose} className="text-2xl">&times;</button></div>
        <div className="grid grid-cols-2 gap-4">
          <button onClick={handleExportJSON} className="p-4 border-2 rounded-2xl hover:border-blue-500 font-bold">JSON 내보내기</button>
          <button onClick={() => jsonInputRef.current?.click()} className="p-4 border-2 rounded-2xl hover:border-green-500 font-bold">JSON 가져오기</button>
          <button onClick={handleExportCSV} className="p-4 border-2 rounded-2xl hover:border-blue-500 font-bold">CSV 내보내기</button>
          <button onClick={() => csvInputRef.current?.click()} className="p-4 border-2 rounded-2xl hover:border-green-500 font-bold">CSV 가져오기</button>
        </div>
        <input type="file" ref={jsonInputRef} onChange={e => handleFile(e, 'JSON')} hidden />
        <input type="file" ref={csvInputRef} onChange={e => handleFile(e, 'CSV')} hidden />
      </div>
    </div>
  );
};

