const ClientManagerModal: React.FC<{ clients: ClientDefinition[], setClients: any, onClose: () => void, onSelectForOrder?: (clientName: string) => void }> = ({ clients, setClients, onClose, onSelectForOrder }) => {
  const [name, setName] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [phone, setPhone] = useState('');
  const [draggedId, setDraggedId] = useState<string | null>(null);

  const save = () => {
    if (!name) return;
    setClients([...clients, { id: Math.random().toString(36).substr(2, 9), name, shortcut, phone }]);
    setName(''); setShortcut(''); setPhone('');
  };

  const handleDragStart = (e: React.DragEvent, id: string) => { e.dataTransfer.effectAllowed = 'move'; setDraggedId(id); };
  const handleDragOver = (e: React.DragEvent, id: string) => {
    e.preventDefault();
    if (!draggedId || draggedId === id) return;
    const newClients = [...clients];
    const di = newClients.findIndex(c => c.id === draggedId);
    const ti = newClients.findIndex(c => c.id === id);
    if (di > -1 && ti > -1) {
      const [moved] = newClients.splice(di, 1);
      newClients.splice(ti, 0, moved);
      setClients(newClients);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-3xl flex flex-col p-6 max-h-[90vh]">
        <div className="flex justify-between items-center mb-4"><h3 className="text-xl font-black">거래처 관리</h3><button onClick={onClose} className="text-2xl">&times;</button></div>
        <div className="flex gap-2 mb-4">
          <input value={name} onChange={e => setName(e.target.value)} placeholder="거래처명" className="border p-2 rounded flex-1" />
          <input value={shortcut} onChange={e => setShortcut(e.target.value)} placeholder="단축어" className="border p-2 rounded w-24" />
          <input value={phone} onChange={e => setPhone(e.target.value)} placeholder="전화번호" className="border p-2 rounded w-32" />
          <button onClick={save} className="bg-blue-600 text-white px-4 py-2 rounded font-bold">추가</button>
        </div>
        <div className="overflow-y-auto grid grid-cols-2 gap-2">
          {clients.map(c => (
            <div key={c.id} draggable onDragStart={e => handleDragStart(e, c.id)} onDragOver={e => handleDragOver(e, c.id)} onDragEnd={() => setDraggedId(null)}
              className={`flex items-center gap-3 p-3 border rounded-xl bg-slate-50 cursor-move ${draggedId === c.id ? 'opacity-30 border-blue-500 border-dashed' : ''}`}>
              <GripVertical className="w-4 h-4 text-slate-300" />
              <div className="flex-1"><div className="font-bold text-sm">{c.name}</div><div className="text-[10px] text-slate-400">{c.shortcut} | {c.phone}</div></div>
              <div className="flex gap-2">
                <button onClick={() => onSelectForOrder?.(c.name)} className="text-blue-500"><Plus className="w-4 h-4" /></button>
                <button onClick={() => setClients(clients.filter(item => item.id !== c.id))} className="text-red-500"><Trash className="w-4 h-4" /></button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const OrderModal: React.FC<{ onClose: () => void, onSubmit: (c: string, i: string) => void, selectedDate: string, products: ProductDefinition[], clients: ClientDefinition[], initialClientName?: string, initialItemsStr?: string, isEditing?: boolean, onOpenProductManager: () => void, onOpenClientManager: () => void }> = ({ onClose, onSubmit, selectedDate, products, clients, initialClientName, initialItemsStr, isEditing, onOpenProductManager, onOpenClientManager }) => {
  const [client, setClient] = useState(initialClientName || '');
  const [items, setItems] = useState(initialItemsStr || '');
  const [prompt, setPrompt] = useState<{ type: 'client' | 'product', val: string } | null>(null);

  const submit = () => {
    if (!client || !items) return;
    const exactClient = clients.find(c => c.name === client || c.shortcut === client);
    if (!exactClient) { setPrompt({ type: 'client', val: client }); return; }
    const parts = items.split(/\s+/);
    for (const p of parts) {
      const match = p.match(/^([a-zA-Z가-힣]+)(\d+)$/);
      if (match && !products.some(prod => prod.shortcut.toUpperCase() === match[1].toUpperCase())) {
        setPrompt({ type: 'product', val: match[1] }); return;
      }
    }
    onSubmit(exactClient.name, items);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-8">
        {prompt ? (
          <div className="text-center">
            <h4 className="text-lg font-bold mb-4">{prompt.val} 은(는) 등록되지 않았습니다.</h4>
            <div className="flex gap-2">
              <button onClick={() => setPrompt(null)} className="flex-1 p-3 bg-slate-100 rounded-xl">취소</button>
              <button onClick={prompt.type === 'client' ? onOpenClientManager : onOpenProductManager} className="flex-1 p-3 bg-blue-600 text-white rounded-xl">등록하러 가기</button>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            <h3 className="text-2xl font-black">주문 {isEditing ? '수정' : '등록'}</h3>
            <input list="clients-list" value={client} onChange={e => setClient(e.target.value)} placeholder="거래처명 또는 단축어" className="w-full border p-4 rounded-2xl font-bold" />
            <datalist id="clients-list">{clients.map(c => <option key={c.id} value={c.name}>{c.shortcut}</option>)}</datalist>
            <textarea value={items} onChange={e => setItems(e.target.value)} placeholder="품목수량 (예: 특크20 감천10)" className="w-full border p-4 rounded-2xl h-32 font-bold" />
            <div className="flex gap-2">
              <button onClick={onClose} className="flex-1 p-4 font-bold">취소</button>
              <button onClick={submit} className="flex-1 p-4 bg-blue-600 text-white rounded-2xl font-black shadow-lg">확인</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

