  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center flex-shrink-0 bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-800">거래처 마스터 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 font-bold text-2xl">&times;</button>
        </div>

        <div className="p-4 flex flex-col gap-4 overflow-hidden h-full">
          {/* 상단: 입력 폼 (가로 배치) */}
          <div className="bg-slate-50 p-3 rounded-xl border border-slate-200 flex-shrink-0 shadow-sm">
            <div className="flex flex-col md:flex-row gap-3 items-center">
              {/* Category */}
              <div className="flex items-center gap-2 w-full md:w-48">
                   <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-12 text-right">카테고리</span>
                   <input list="client-category-list" name="category" value={formData.category || ''} onChange={handleChange} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="선택/입력" />
                   <datalist id="client-category-list">
                        {categories.map(c => <option key={c} value={c} />)}
                   </datalist>
              </div>

              {/* Name */}
              <div className="flex items-center gap-2 w-full md:flex-1">
                   <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-12 text-right">거래처명</span>
                   <input name="name" value={formData.name || ''} onChange={handleChange} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="거래처명" />
              </div>

              {/* Shortcut */}
              <div className="flex items-center gap-2 w-full md:w-32">
                   <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-10 text-right">단축어</span>
                   <input name="shortcut" value={formData.shortcut || ''} onChange={handleChange} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="단축" />
              </div>

              {/* Phone */}
              <div className="flex items-center gap-2 w-full md:w-40">
                   <span className="text-sm font-bold text-slate-500 whitespace-nowrap w-12 text-right">전화번호</span>
                   <input name="phone" value={formData.phone || ''} onChange={handleChange} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="번호" />
