              <div className="md:col-span-2">
                   <label className="text-xs font-bold text-slate-400 ml-1 mb-1 block">전화번호</label>
                   <input name="phone" value={formData.phone || ''} onChange={handleChange} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-base font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="전화번호" />
              </div>
              <div className="md:col-span-2 flex gap-1">
                   <button onClick={save} className={`w-full text-white py-2 rounded-lg font-bold transition-all shadow-md active:scale-95 ${editingId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-slate-900 hover:bg-slate-800'}`}>
                     {editingId ? '수정' : '추가'}
                   </button>
