                                     <span className="font-bold text-base text-slate-800 truncate">{c.name}</span>
                                     {c.shortcut && <span className="text-xs font-bold text-blue-600 bg-blue-50 px-1.5 rounded">{c.shortcut}</span>}
                                  </div>
                                  <div className="text-xs text-slate-400 truncate mt-0.5">{c.phone || '번호없음'}</div>
                                </div>
                              </div>
                              <div className="flex gap-1 flex-shrink-0">
                                {onSelectForOrder && (<button onClick={() => onSelectForOrder(c.name)} className="p-1.5 text-white bg-blue-500 hover:bg-blue-600 rounded-lg transition-colors shadow-sm" title="이 거래처로 주문 등록"><Plus className="w-4 h-4" /></button>)}
