const DataManagerModal: React.FC<{ orders: Order[], products: ProductDefinition[], clients: ClientDefinition[], financials: FinancialRecord[], onImport: (data: any) => void, onClose: () => void }> = ({ orders, products, clients, financials, onImport, onClose }) => {
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const csvInputRef = useRef<HTMLInputElement>(null);

  const handleExportJSON = () => {
    const data = { version: '1.0', orders, products, clients, financials };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportCSV = () => {
    let csv = "날짜,거래처,주문내역\n";
    orders.forEach(o => {
      const itemsStr = o.items.map(i => {
        const p = products.find(prod => prod.id === i.productId);
        return `${p ? p.shortcut : i.name}${i.unitQuantity}`;
      }).join(' ');
      csv += `"${o.date}","${o.clientName}","${itemsStr}"\n`;
    });
    const blob = new Blob(["\uFEFF" + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `orders_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>, type: 'JSON' | 'CSV') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      if (type === 'JSON') {
        try { onImport(JSON.parse(content)); } catch { alert('올바른 백업 파일이 아닙니다.'); }
      } else {
        const lines = content.split('\n').slice(1);
        const newOrders: Order[] = lines.map(l => {
          const m = l.match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);
          if (!m || m.length < 3) return null;
          const [d, c, itemsText] = m.map(v => v.replace(/^"|"$/g, '').trim());

          const parts = itemsText.split(/\s+/).filter(p => p);
          const parsedItems: OrderItem[] = parts.map(part => {
            const match = part.match(/^([a-zA-Z가-힣]+)([\d]+(\.\d)?)$/);
            if (match) {
              const sc = match[1].toUpperCase();
              const qty = parseFloat(match[2]);
              const prod = products.find(p => p.shortcut.toUpperCase() === sc);
              if (prod) {
                return {
                  id: Math.random().toString(36).substr(2, 9),
                  productId: prod.id,
                  name: prod.name,
                  category: prod.category,
                  unitQuantity: qty,
                  isLoaded: false
                };
              }
            }
            return null;
          }).filter(v => v) as OrderItem[];

          return { id: Math.random().toString(36).substr(2, 9), date: d, clientName: c, items: parsedItems, createdAt: Date.now() };
        }).filter(v => v) as Order[];

        if (newOrders.length > 0) {
          if (confirm(`${newOrders.length}건의 주문 데이터를 가져오시겠습니까?`)) {
            onImport({ orders: newOrders });
          }
        } else {
          alert('가져올 주문 데이터가 없습니다.');
        }
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg flex flex-col p-8 space-y-6">
        <div className="flex justify-between items-center">
          <h3 className="text-2xl font-black text-slate-800">데이터 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl transition-colors">&times;</button>
        </div>
        <div className="grid grid-cols-2 gap-4">
