const OrderModal: React.FC<{ onClose: () => void, onSubmit: (c: string, i: string) => void, selectedDate: string, products: ProductDefinition[], clients: ClientDefinition[], initialClientName?: string, initialItemsStr?: string, isEditing?: boolean, onOpenProductManager: () => void, onOpenClientManager: () => void }> = ({ onClose, onSubmit, selectedDate, products, clients, initialClientName, initialItemsStr, isEditing, onOpenProductManager, onOpenClientManager }) => {
  const [client, setClient] = useState(initialClientName || '');
  const [items, setItems] = useState(initialItemsStr || '');
  const [prompt, setPrompt] = useState<{ type: 'client' | 'product', val: string } | null>(null);

  const submit = () => {
    if (!client || !items) return;
    const exactClient = clients.find(c => c.name === client || c.shortcut === client);
    if (!exactClient) { setPrompt({ type: 'client', val: client }); return; }
    const parts = items.split(/\s+/);
    for (const p of parts) {
      const match = p.match(/^([a-zA-Z가-힣]+)([\d]+(\.\d)?)$/);
      if (match && !products.some(prod => prod.shortcut.toUpperCase() === match[1].toUpperCase())) {
        setPrompt({ type: 'product', val: match[1] }); return;
      }
    }
    onSubmit(exactClient.name, items);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-8">
        {prompt ? (
          <div className="text-center">
            <h4 className="text-lg font-bold mb-4">{prompt.val} 은(는) 등록되지 않았습니다.</h4>
            <div className="flex gap-2">
              <button onClick={() => setPrompt(null)} className="flex-1 p-3 bg-slate-100 rounded-xl">취소</button>
              <button onClick={prompt.type === 'client' ? onOpenClientManager : onOpenProductManager} className="flex-1 p-3 bg-blue-600 text-white rounded-xl">등록하러 가기</button>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            <h3 className="text-2xl font-black">주문 {isEditing ? '수정' : '등록'}</h3>
            <input list="clients-list" value={client} onChange={e => setClient(e.target.value)} placeholder="거래처명 또는 단축어" className="w-full bg-slate-100 border border-slate-300 p-4 rounded-2xl font-bold text-slate-900 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-colors" />
            <datalist id="clients-list">{clients.map(c => <option key={c.id} value={c.name}>{c.shortcut}</option>)}</datalist>
            <textarea value={items} onChange={e => setItems(e.target.value)} placeholder="품목수량 (예: 특크20 감천10)" className="w-full bg-slate-100 border border-slate-300 p-4 rounded-2xl h-32 font-bold text-slate-900 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-colors" />
            <div className="flex gap-2">
              <button onClick={onClose} className="flex-1 p-4 font-bold">취소</button>
              <button onClick={submit} className="flex-1 p-4 bg-blue-600 text-white rounded-2xl font-black shadow-lg">확인</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

