            <div className="grid grid-cols-1 md:grid-cols-12 gap-3 items-end">
              <div className="md:col-span-3">
                   <label className="text-xs font-bold text-slate-400 ml-1 mb-1 block">카테고리</label>
                   <input list="client-category-list" name="category" value={formData.category || ''} onChange={handleChange} className="w-full bg-slate-100 border border-slate-300 rounded-lg px-3 py-2 text-base font-bold text-slate-900 outline-none focus:bg-white focus:ring-2 focus:ring-blue-500 transition-colors" placeholder="선택/입력" />
                   <datalist id="client-category-list">
