                      <div key={c.id} onMouseDown={() => { setClientName(c.name); setShowClientSuggestions(false); }} className="p-3 hover:bg-blue-50 cursor-pointer border-b border-slate-50 last:border-0">
                         <span className="font-bold text-slate-800">{c.name}</span>
                      </div>
                    ))}
                    {filteredClients.length === 0 && (
