                  <label className="text-xs font-bold text-slate-500">주문 내역 (단축어 입력)</label>
                  <button type="button" onClick={onOpenProductManager} className="text-xs text-blue-500 font-bold hover:underline">품목 단축어 확인</button>
               </div>
               <textarea 
                 value={itemsStr}
                 onChange={e => setItemsStr(e.target.value)}
