const ClientManagerModal: React.FC<{ clients: ClientDefinition[], setClients: React.Dispatch<React.SetStateAction<ClientDefinition[]>>, onClose: () => void, onSelectForOrder?: (name: string) => void }> = ({ clients, setClients, onClose, onSelectForOrder }) => {
  const [name, setName] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState(CLIENT_CATEGORIES[0]);
  const [search, setSearch] = useState('');

  const filtered = useMemo(() => {
    if (!search) return clients;
    return clients.filter(c => c.name.includes(search) || (c.shortcut && c.shortcut.includes(search)) || getChosung(c.name).includes(search));
  }, [clients, search]);

  const handleAdd = () => {
    if (!name) return;
    const newClient: ClientDefinition = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      shortcut,
      category
    };
    setClients(prev => [...prev, newClient]);
    setName('');
    setShortcut('');
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('삭제하시겠습니까?')) {
      setClients(prev => prev.filter(c => c.id !== id));
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg flex flex-col p-6 space-y-4 max-h-[80vh]">
        <div className="flex justify-between items-center">
          <h3 className="text-xl font-black text-slate-800">거래처 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
        </div>

        <div className="grid grid-cols-4 gap-2">
            <input placeholder="거래처명" value={name} onChange={e => setName(e.target.value)} className="col-span-1 bg-slate-100 p-2 rounded-lg" />
            <input placeholder="단축어" value={shortcut} onChange={e => setShortcut(e.target.value)} className="col-span-1 bg-slate-100 p-2 rounded-lg" />
            <select value={category} onChange={e => setCategory(e.target.value)} className="col-span-1 bg-slate-100 p-2 rounded-lg">
                {CLIENT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
            <button onClick={handleAdd} className="col-span-1 bg-blue-600 text-white rounded-lg font-bold">추가</button>
        </div>

        <input placeholder="검색..." value={search} onChange={e => setSearch(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg p-2" />

        <div className="overflow-y-auto space-y-2 flex-1">
            {filtered.map(c => (
                <div key={c.id} onClick={() => onSelectForOrder && onSelectForOrder(c.name)} className={`flex justify-between items-center bg-slate-50 p-2 rounded-lg border border-slate-100 ${onSelectForOrder ? 'cursor-pointer hover:bg-blue-50 hover:border-blue-200' : ''}`}>
                    <div>
                        <span className="text-xs font-bold text-blue-500 mr-2">[{c.category}]</span>
                        <span className="font-bold text-slate-700">{c.name}</span>
                        {c.shortcut && <span className="text-xs text-slate-400 ml-2">({c.shortcut})</span>}
                    </div>
                    <button onClick={(e) => handleDelete(c.id, e)} className="text-slate-300 hover:text-red-500"><Trash className="w-4 h-4" /></button>
                </div>
            ))}
        </div>
      </div>
    </div>
  );
};

const OrderModal: React.FC<{ onClose: () => void, onSubmit: (name: string, items: string) => void, selectedDate: string, products: ProductDefinition[], clients: ClientDefinition[], initialClientName?: string, initialItemsStr?: string, isEditing: boolean, onOpenProductManager: () => void, onOpenClientManager: () => void }> = ({ onClose, onSubmit, selectedDate, products, clients, initialClientName = '', initialItemsStr = '', isEditing, onOpenProductManager, onOpenClientManager }) => {
  const [clientName, setClientName] = useState(initialClientName);
  const [itemsStr, setItemsStr] = useState(initialItemsStr);
  const [showSuggestions, setShowSuggestions] = useState(false);

  const filteredClients = useMemo(() => {
    if (!clientName) return [];
    return clients.filter(c => c.name.includes(clientName) || getChosung(c.name).includes(clientName)).slice(0, 5);
  }, [clientName, clients]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit(clientName, itemsStr);
  };

  const selectClient = (name: string) => {
      setClientName(name);
      setShowSuggestions(false);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg p-6 space-y-6">
        <div className="flex justify-between items-center">
           <div>
             <h3 className="text-xl font-black text-slate-800">{isEditing ? '주문 수정' : '새 주문 등록'}</h3>
             <p className="text-sm text-slate-400 font-bold">{selectedDate}</p>
           </div>
           <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl">&times;</button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
            <div className="relative">
                <label className="text-xs font-bold text-slate-500 mb-1 block">거래처</label>
                <div className="flex gap-2">
                    <input 
                        type="text" 
                        value={clientName} 
                        onChange={e => { setClientName(e.target.value); setShowSuggestions(true); }}
                        onFocus={() => setShowSuggestions(true)}
                        className="flex-1 bg-slate-100 border border-slate-300 rounded-lg p-3 font-bold text-slate-900 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-colors"
                        placeholder="거래처명 입력"
                        autoFocus
                    />
                    <button type="button" onClick={onOpenClientManager} className="bg-slate-100 hover:bg-slate-200 p-3 rounded-lg text-slate-600"><Settings className="w-6 h-6" /></button>
                </div>
                {showSuggestions && filteredClients.length > 0 && (
                    <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 rounded-lg shadow-xl mt-1 z-10 overflow-hidden">
                        {filteredClients.map(c => (
                            <div key={c.id} onClick={() => selectClient(c.name)} className="p-3 hover:bg-blue-50 cursor-pointer border-b border-slate-50 last:border-0">
                                <span className="font-bold text-slate-700">{c.name}</span>
                                {c.shortcut && <span className="text-xs text-slate-400 ml-2">({c.shortcut})</span>}
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div>
                <label className="text-xs font-bold text-slate-500 mb-1 block">주문 내역 (단축어 입력)</label>
                <div className="flex gap-2">
                    <input 
                        type="text" 
                        value={itemsStr} 
                        onChange={e => setItemsStr(e.target.value)}
                        className="flex-1 bg-slate-100 border border-slate-300 rounded-lg p-3 font-bold text-slate-900 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-colors"
                        placeholder="예: 크릴10 파우다5" 
                    />
                    <button type="button" onClick={onOpenProductManager} className="bg-slate-100 hover:bg-slate-200 p-3 rounded-lg text-slate-600"><Settings className="w-6 h-6" /></button>
                </div>
                <p className="text-xs text-slate-400 mt-2">
                   * 등록된 단축어와 수량을 붙여서 입력하세요 (띄어쓰기로 구분) <br/>
                   * 예: <span className="text-blue-500 font-bold">크릴10</span> <span className="text-blue-500 font-bold">파우다5</span>
                </p>
            </div>

            <div className="pt-4 flex gap-3">
                <button type="button" onClick={onClose} className="flex-1 py-3 rounded-xl font-bold text-slate-500 bg-slate-100 hover:bg-slate-200 transition-colors">취소</button>
                <button type="submit" className="flex-1 py-3 rounded-xl font-bold text-white bg-blue-600 hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all active:scale-95">
                    {isEditing ? '수정 완료' : '등록하기'}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

export default App;

