개발자님, 아주 좋은 아이디어입니다! 구글 스프레드시트를 백엔드(DB)로 사용하면 무료이면서도 엑셀처럼 데이터를 직접 눈으로 보고 관리할 수 있어 소규모 앱에 최적입니다.

요청하신 대로 **1. 구글 앱스 스크립트(GAS) 코드**, **2. React 앱 수정 코드**, **3. 초보자용 배포 가이드** 순서로 정리해 드릴게요.

### 1. Google Apps Script (GAS) 코드

이 코드는 구글 시트의 '확장 프로그램 > Apps Script'에 붙여넣어야 하는 코드입니다.
이 스크립트는 React 앱에서 보낸 데이터를 받아서 시트에 저장(`doPost`)하고, 시트의 데이터를 읽어서 앱으로 보내주는(`doGet`) 역할을 합니다.

```javascript
// 이 코드를 구글 스프레드시트 Apps Script 에디터에 붙여넣으세요.

function doGet(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // 데이터 읽어오기
  const clients = readSheet(ss, 'Clients');
  const products = readSheet(ss, 'Products');
  const orders = readSheet(ss, 'Orders');
  const financials = readSheet(ss, 'Financials');

  const result = {
    clients: clients,
    products: products,
    orders: orders,
    financials: financials
  };

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const data = JSON.parse(e.postData.contents);

  // 탭이 없으면 생성, 있으면 데이터 덮어쓰기
  if (data.clients) saveToSheet(ss, 'Clients', data.clients, ['id', 'name', 'shortcut', 'phone', 'category']);
  if (data.products) saveToSheet(ss, 'Products', data.products, ['id', 'name', 'shortcut', 'category']);
  if (data.orders) saveToSheet(ss, 'Orders', data.orders, ['id', 'date', 'clientName', 'items', 'createdAt']);
  if (data.financials) saveToSheet(ss, 'Financials', data.financials, ['date', 'cash', 'transfer', 'card', 'note']);

  return ContentService.createTextOutput(JSON.stringify({ status: 'success' }))
    .setMimeType(ContentService.MimeType.JSON);
}

// 시트 저장 헬퍼 함수
function saveToSheet(ss, sheetName, dataArray, headers) {
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
  }

  sheet.clear(); // 기존 데이터 삭제 (덮어쓰기)

  // 헤더 추가
  sheet.appendRow(headers);

  if (dataArray.length === 0) return;

  // 데이터 변환 (Object -> Array)
  const rows = dataArray.map(item => {
    return headers.map(header => {
      // items 같은 배열 데이터는 문자열로 변환하여 저장
      if (typeof item[header] === 'object') return JSON.stringify(item[header]);
      return item[header] || '';
    });
  });

  // 한 번에 쓰기 (속도 최적화)
  sheet.getRange(2, 1, rows.length, headers.length).setValues(rows);
}

// 시트 읽기 헬퍼 함수
function readSheet(ss, sheetName) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];

  const rows = sheet.getDataRange().getValues();
  if (rows.length < 2) return [];

  const headers = rows[0];
  const data = rows.slice(1);

  return data.map(row => {
    const obj = {};
    headers.forEach((header, index) => {
      let value = row[index];
      // JSON 형태의 문자열이면 다시 객체로 변환 (items 등)
      try {
        if (typeof value === 'string' && (value.startsWith('[') || value.startsWith('{'))) {
          value = JSON.parse(value);
        }
      } catch (e) {
        // 파싱 실패시 그냥 값 사용
      }
      obj[header] = value;
    });
    return obj;
  });
}
```

---

### 2. React 앱 코드 수정

`App.tsx`의 `DataManagerModal` 컴포넌트를 수정하여 구글 시트 URL을 입력받고, 연동 버튼을 추가합니다.

