                    <span className="font-medium opacity-90">{name}</span>
                    <span className="font-bold text-white">{Number((count as number).toFixed(1))}</span>
                  </div>
                ))}
              </div>
            ))}
          </div>
      )}
    </div>
  );

  const renderOrderList = () => (
    <div className="space-y-4">
      {selectedDateOrders.length === 0 ? (
        <div className="flex flex-col items-center justify-center text-center py-12 bg-white rounded-2xl border border-dashed border-slate-200">
          <Truck className="w-12 h-12 text-slate-200 mb-3" />
          <p className="font-bold text-slate-400">등록된 주문이 없습니다.</p>
          <button onClick={() => setShowOrderForm(true)} className="mt-4 text-sm text-blue-600 font-bold hover:underline">주문 추가하기</button>
        </div>
      ) : (
        selectedDateOrders.map(order => {
          const totalQty = order.items.reduce((sum, i) => sum + i.unitQuantity, 0);
          return (
            <div key={order.id} draggable onDragStart={(e) => handleDragStart(e, order.id)} onDragOver={(e) => handleDragOver(e, order.id)} onDragEnd={handleDragEnd}
              className={`bg-white border-2 border-slate-100 rounded-2xl overflow-hidden shadow-sm hover:border-blue-200 transition-colors ${draggedOrderId === order.id ? 'opacity-40 grayscale' : ''}`}>
              <div className="px-4 py-2 bg-slate-50 flex justify-between items-center border-b border-slate-100">
                <div className="flex items-center gap-2">
                  <div className="cursor-grab active:cursor-grabbing text-slate-300 hover:text-blue-400"><GripVertical className="w-4 h-4" /></div>
                  <span className="font-black text-base text-slate-800">{order.clientName}</span>
                </div>
                <div className="flex gap-1">
                  <button onClick={() => startEditOrder(order)} className="text-slate-300 hover:text-blue-500 p-1"><Pencil className="w-4 h-4" /></button>
                  <button onClick={(e) => deleteOrder(e, order.id)} className="text-slate-300 hover:text-red-500 p-1"><Trash className="w-4 h-4" /></button>
