  const [clientName, setClientName] = useState(initialClientName);
  const [itemsStr, setItemsStr] = useState(initialItemsStr);
  const [showClientSuggestions, setShowClientSuggestions] = useState(false);

  // New state for product search
  const [productSearch, setProductSearch] = useState('');
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const itemsTextareaRef = useRef<HTMLTextAreaElement>(null);

  // Update local state if initial props change (e.g. coming back from a modal)
  useEffect(() => {
    setClientName(initialClientName);
  }, [initialClientName]);

  useEffect(() => {
    setItemsStr(initialItemsStr);
  }, [initialItemsStr]);

  const filteredClients = useMemo(() => {
    if (!clientName) return [];
    return clients.filter(c => 
      c.name.includes(clientName) || 
      (c.shortcut && c.shortcut.includes(clientName)) || 
      getChosung(c.name).includes(clientName)
    ).slice(0, 5); // Limit to 5
