  const filteredProducts = useMemo(() => {
    if (!productSearch) return [];
    return products.filter(p => 
      p.name.includes(productSearch) || 
      p.shortcut.includes(productSearch) || 
      getChosung(p.name).includes(productSearch)
    ).slice(0, 5); // Limit to 5
