const ProductManagerModal: React.FC<{ products: ProductDefinition[], setProducts: React.Dispatch<React.SetStateAction<ProductDefinition[]>>, onClose: () => void, onSelectForOrder?: (product: ProductDefinition) => void }> = ({ products, setProducts, onClose, onSelectForOrder }) => {
  const [name, setName] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState(PRODUCT_CATEGORIES[0]);
  const [searchTerm, setSearchTerm] = useState('');

  const handleAdd = () => {
    if (!name || !shortcut) return;
    setProducts(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), name, shortcut, category }]);
    setName('');
    setShortcut('');
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if(confirm('정말 삭제하시겠습니까?')) {
      setProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  const filtered = products.filter(p => p.name.includes(searchTerm) || p.shortcut.includes(searchTerm) || getChosung(p.name).includes(searchTerm));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col p-8 space-y-6 max-h-[85vh]">
        <div className="flex justify-between items-center">
          <h3 className="text-2xl font-black text-slate-800">품목 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl transition-colors">&times;</button>
        </div>
        <div className="flex gap-2 p-4 bg-slate-50 rounded-xl border border-slate-100">
          <select value={category} onChange={e => setCategory(e.target.value)} className="bg-white border border-slate-200 rounded-lg px-2 py-2 text-sm">
            {PRODUCT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <input value={name} onChange={e => setName(e.target.value)} placeholder="품목명 (예: 각크릴)" className="flex-1 bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500" />
          <input value={shortcut} onChange={e => setShortcut(e.target.value)} placeholder="단축어 (예: K)" className="w-24 bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500" />
          <button onClick={handleAdd} className="bg-blue-600 text-white rounded-lg px-4 py-2 font-bold hover:bg-blue-700 transition-colors">추가</button>
        </div>

        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="품목 검색..." className="w-full bg-slate-100 border-none rounded-xl px-4 py-3 text-sm font-bold" />

        <div className="overflow-y-auto flex-1 pr-2 space-y-2">
          {filtered.map(p => (
            <div key={p.id} onClick={() => onSelectForOrder && onSelectForOrder(p)} className={`flex items-center justify-between p-3 bg-white border border-slate-100 rounded-xl transition-colors ${onSelectForOrder ? 'cursor-pointer hover:bg-blue-50 hover:border-blue-200' : ''}`}>
              <div className="flex items-center gap-3">
                <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">{p.category}</span>
                <span className="font-bold text-slate-700">{p.name}</span>
                <span className="text-xs font-bold text-blue-500 bg-blue-50 px-1.5 py-0.5 rounded">Cmd: {p.shortcut}</span>
              </div>
              <button onClick={(e) => handleDelete(p.id, e)} className="text-slate-300 hover:text-red-500"><Trash className="w-4 h-4" /></button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const ClientManagerModal: React.FC<{ clients: ClientDefinition[], setClients: React.Dispatch<React.SetStateAction<ClientDefinition[]>>, onClose: () => void, onSelectForOrder?: (name: string) => void }> = ({ clients, setClients, onClose, onSelectForOrder }) => {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState(CLIENT_CATEGORIES[0]);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  const handleSave = () => {
    if (!name) return;

    if (editingId) {
        setClients(prev => prev.map(c => c.id === editingId ? { ...c, name, phone, shortcut, category } : c));
        setEditingId(null);
    } else {
        setClients(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), name, phone, shortcut, category }]);
    }
    resetForm();
  };

  const handleEdit = (client: ClientDefinition) => {
      setEditingId(client.id);
      setName(client.name);
      setPhone(client.phone || '');
      setShortcut(client.shortcut || '');
      setCategory(client.category || CLIENT_CATEGORIES[0]);
  };

  const handleCancelEdit = () => {
      setEditingId(null);
      resetForm();
  };

  const resetForm = () => {
      setName('');
      setPhone('');
      setShortcut('');
      setCategory(CLIENT_CATEGORIES[0]);
  }

  const handleDelete = (id: string) => {
    if(confirm('삭제하시겠습니까?')) {
      setClients(prev => prev.filter(c => c.id !== id));
      if (editingId === id) handleCancelEdit();
    }
  };

  const filtered = clients.filter(c => c.name.includes(searchTerm) || (c.shortcut && c.shortcut.includes(searchTerm)));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col p-8 space-y-6 max-h-[85vh]">
        <div className="flex justify-between items-center">
          <h3 className="text-2xl font-black text-slate-800">거래처 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl transition-colors">&times;</button>
        </div>

        <div className="bg-slate-50 rounded-xl border border-slate-100 p-4 space-y-3">
            <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">{editingId ? '거래처 정보 수정' : '새 거래처 등록'}</span>
                {editingId && <button onClick={handleCancelEdit} className="text-xs text-red-500 font-bold hover:underline">수정 취소</button>}
            </div>
            <div className="grid grid-cols-4 gap-2">
                <select value={category} onChange={e => setCategory(e.target.value)} className="col-span-1 bg-white border border-slate-200 rounded-lg px-2 py-2 text-sm">
                    {CLIENT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input value={name} onChange={e => setName(e.target.value)} placeholder="거래처명" className="col-span-1 bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                <input value={phone} onChange={e => setPhone(e.target.value)} placeholder="전화번호 (010-0000-0000)" className="col-span-1 bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                <input value={shortcut} onChange={e => setShortcut(e.target.value)} placeholder="단축어" className="col-span-1 bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm" />
            </div>
            <button onClick={handleSave} className={`w-full text-white rounded-lg py-3 font-bold transition-colors ${editingId ? 'bg-green-600 hover:bg-green-700' : 'bg-blue-600 hover:bg-blue-700'}`}>
                {editingId ? '수정 내용 저장' : '새 거래처 추가'}
            </button>
        </div>

        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="거래처 검색..." className="w-full bg-slate-100 border-none rounded-xl px-4 py-3 text-sm font-bold" />

        <div className="overflow-y-auto flex-1 pr-2 space-y-2">
          {filtered.map(c => (
            <div key={c.id} className="flex items-center justify-between p-3 bg-white border border-slate-100 rounded-xl hover:border-blue-200 transition-colors group">
              <div 
                onClick={() => {
                    // If we are in "Select Mode" (from Order Form), click selects.
                    // If we are in "Manager Mode" (Main Menu), click calls (convenience).
                    if (onSelectForOrder) {
                        onSelectForOrder(c.name);
                    } else if (c.phone) {
                        window.location.href = `tel:${c.phone}`;
                    }
                }} 
                className="flex-1 cursor-pointer flex flex-col justify-center"
              >
                <div className="flex items-center gap-2 mb-0.5">
                    <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">{c.category}</span>
                    <span className="font-bold text-slate-700 group-hover:text-blue-600">{c.name}</span>
                    {c.shortcut && <span className="text-xs text-slate-400">({c.shortcut})</span>}
                </div>
                {c.phone && <div className="text-xs text-slate-400 font-medium pl-1">{c.phone}</div>}
              </div>

              <div className="flex items-center gap-1">
                  {c.phone && (
                      <a href={`tel:${c.phone}`} className="p-2 bg-green-50 text-green-600 rounded-lg hover:bg-green-100 transition-colors" title="전화 걸기">
                          <Phone className="w-4 h-4" />
                      </a>
                  )}
                  <button onClick={() => handleEdit(c)} className="p-2 text-slate-300 hover:text-blue-500 hover:bg-blue-50 rounded-lg transition-colors" title="수정">
                      <Pencil className="w-4 h-4" />
                  </button>
                  <button onClick={() => handleDelete(c.id)} className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="삭제">
                      <Trash className="w-4 h-4" />
                  </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const OrderModal: React.FC<{
  onClose: () => void;
  onSubmit: (clientName: string, itemsStr: string) => void;
  selectedDate: string;
  products: ProductDefinition[];
  clients: ClientDefinition[];
  initialClientName: string;
  initialItemsStr: string;
  isEditing: boolean;
  onOpenProductManager: (currentClientName: string, currentItemsStr: string) => void;
  onOpenClientManager: (currentClientName: string, currentItemsStr: string) => void;
}> = ({ onClose, onSubmit, selectedDate, products, clients, initialClientName, initialItemsStr, isEditing, onOpenProductManager, onOpenClientManager }) => {
  const [clientName, setClientName] = useState(initialClientName);
  const [itemsStr, setItemsStr] = useState(initialItemsStr);
  const [showClientSuggestions, setShowClientSuggestions] = useState(false);

  // New state for product search
  const [productSearch, setProductSearch] = useState('');
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const itemsTextareaRef = useRef<HTMLTextAreaElement>(null);

  // Update local state if initial props change (e.g. coming back from a modal)
  useEffect(() => {
    setClientName(initialClientName);
  }, [initialClientName]);

  useEffect(() => {
    setItemsStr(initialItemsStr);
  }, [initialItemsStr]);

  const filteredClients = useMemo(() => {
    if (!clientName) return [];
    return clients.filter(c => 
      c.name.includes(clientName) || 
      (c.shortcut && c.shortcut.includes(clientName)) || 
      getChosung(c.name).includes(clientName)
    ).slice(0, 5); // Limit to 5
  }, [clients, clientName]);

  const filteredProducts = useMemo(() => {
    if (!productSearch) return [];
    return products.filter(p => 
      p.name.includes(productSearch) || 
      p.shortcut.includes(productSearch) || 
      getChosung(p.name).includes(productSearch)
    ).slice(0, 5); // Limit to 5
  }, [products, productSearch]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg flex flex-col p-6 space-y-4">
        <div className="flex justify-between items-center border-b border-slate-100 pb-4">
          <div>
            <h3 className="text-xl font-black text-slate-800">{isEditing ? '주문 수정' : '새 주문 등록'}</h3>
            <p className="text-xs text-slate-400 font-bold mt-1">{selectedDate}</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
        </div>

        <div className="space-y-4">
            <div className="relative">
                <div className="flex justify-between items-center mb-1">
                    <label className="text-xs font-bold text-slate-500">거래처</label>
                    <button onClick={() => onOpenClientManager(clientName, itemsStr)} className="text-xs text-blue-500 font-bold hover:underline">거래처 관리</button>
                </div>
                <input 
                    type="text" 
                    value={clientName} 
                    onChange={e => { setClientName(e.target.value); setShowClientSuggestions(true); }}
                    onFocus={() => setShowClientSuggestions(true)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-800 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    placeholder="거래처명 입력" 
                />
                {showClientSuggestions && clientName && filteredClients.length > 0 && (
                    <div className="absolute z-10 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-lg max-h-40 overflow-y-auto">
                        {filteredClients.map(c => (
                            <div key={c.id} 
                                 onClick={() => { setClientName(c.name); setShowClientSuggestions(false); }}
                                 className="px-4 py-2 hover:bg-blue-50 cursor-pointer text-sm font-bold text-slate-700"
                            >
                                {c.name} {c.shortcut && <span className="text-slate-400 font-normal">({c.shortcut})</span>}
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div className="relative">
                <div className="flex justify-between items-center mb-1">
                    <label className="text-xs font-bold text-slate-500">품목 검색 (자동 추가)</label>
                    <button onClick={() => onOpenProductManager(clientName, itemsStr)} className="text-xs text-blue-500 font-bold hover:underline">품목 관리</button>
                </div>
                <input 
                    type="text" 
                    value={productSearch} 
                    onChange={e => { setProductSearch(e.target.value); setShowProductSuggestions(true); }}
                    onFocus={() => setShowProductSuggestions(true)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-800 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    placeholder="품목명 또는 단축어 검색" 
                />
                {showProductSuggestions && productSearch && filteredProducts.length > 0 && (
                    <div className="absolute z-10 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-lg max-h-40 overflow-y-auto">
                        {filteredProducts.map(p => (
                            <div key={p.id} 
                                 onClick={() => { 
                                     const prefix = itemsStr && !itemsStr.endsWith(' ') ? ' ' : '';
                                     setItemsStr(prev => prev + prefix + p.shortcut);
                                     setProductSearch('');
                                     setShowProductSuggestions(false);
                                     itemsTextareaRef.current?.focus();
                                 }}
                                 className="px-4 py-2 hover:bg-blue-50 cursor-pointer text-sm font-bold text-slate-700 flex justify-between"
                            >
                                <span>{p.name}</span>
                                <span className="text-blue-500">({p.shortcut})</span>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div>
                <div className="flex justify-between items-center mb-1">
                    <label className="text-xs font-bold text-slate-500">주문 내역 (단축어)</label>
                </div>
                <textarea 
                    ref={itemsTextareaRef}
                    value={itemsStr} 
                    onChange={e => setItemsStr(e.target.value)} 
                    className="w-full h-32 bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-medium text-slate-800 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none"
                    placeholder="예: 각3 백2 파우다1 (단축어와 수량 입력)" 
                />
                <div className="mt-2 flex flex-wrap gap-1">
                    {products.slice(0, 5).map(p => (
                        <button key={p.id} onClick={() => setItemsStr(prev => prev + (prev ? ' ' : '') + p.shortcut)} className="text-[10px] bg-slate-100 text-slate-500 px-2 py-1 rounded border border-slate-200 hover:bg-slate-200">
                            {p.name}:{p.shortcut}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <button onClick={() => onSubmit(clientName, itemsStr)} className="w-full bg-blue-600 text-white rounded-xl py-3.5 font-bold text-lg hover:bg-blue-700 shadow-lg shadow-blue-200 transition-transform active:scale-95">
            저장하기
        </button>
      </div>
    </div>
  );
};

