const ClientManagerModal: React.FC<{ clients: ClientDefinition[], setClients: React.Dispatch<React.SetStateAction<ClientDefinition[]>>, onClose: () => void, onSelectForOrder?: (name: string) => void }> = ({ clients, setClients, onClose, onSelectForOrder }) => {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState(CLIENT_CATEGORIES[0]);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  const handleSave = () => {
    if (!name) return;
    if (editingId) {
        setClients(prev => prev.map(c => c.id === editingId ? { ...c, name, phone, shortcut, category } : c));
        setEditingId(null);
    } else {
        setClients(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), name, phone, shortcut, category }]);
    }
    resetForm();
  };

  const handleEdit = (client: ClientDefinition) => {
      setEditingId(client.id);
      setName(client.name);
      setPhone(client.phone || '');
      setShortcut(client.shortcut || '');
      setCategory(client.category || CLIENT_CATEGORIES[0]);
  };

  const handleCancelEdit = () => {
      setEditingId(null);
      resetForm();
  };

  const resetForm = () => {
      setName('');
      setPhone('');
      setShortcut('');
      setCategory(CLIENT_CATEGORIES[0]);
  }

  const handleDelete = (id: string) => {
    if(confirm('삭제하시겠습니까?')) {
      setClients(prev => prev.filter(c => c.id !== id));
      if (editingId === id) handleCancelEdit();
    }
  };

  const filtered = clients.filter(c => c.name.includes(searchTerm) || (c.shortcut && c.shortcut.includes(searchTerm)));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col p-8 space-y-6 max-h-[85vh]">
        <div className="flex justify-between items-center">
          <h3 className="text-2xl font-black text-slate-800">거래처 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl transition-colors">&times;</button>
        </div>

        <div className="bg-slate-50 rounded-xl border border-slate-100 p-4 space-y-3">
            <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">{editingId ? '거래처 정보 수정' : '새 거래처 등록'}</span>
                {editingId && <button onClick={handleCancelEdit} className="text-xs text-red-500 font-bold hover:underline">수정 취소</button>}
            </div>
            <div className="grid grid-cols-4 gap-2">
                <select value={category} onChange={e => setCategory(e.target.value)} className="col-span-1 bg-white border border-slate-200 rounded-lg px-2 py-2 text-sm">
                    {CLIENT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input value={name} onChange={e => setName(e.target.value)} placeholder="거래처명" className="col-span-1 bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                <input value={phone} onChange={e => setPhone(e.target.value)} placeholder="전화번호" className="col-span-1 bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                <input value={shortcut} onChange={e => setShortcut(e.target.value)} placeholder="단축어" className="col-span-1 bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm" />
            </div>
            <button onClick={handleSave} className={`w-full text-white rounded-lg py-3 font-bold transition-colors ${editingId ? 'bg-green-600 hover:bg-green-700' : 'bg-blue-600 hover:bg-blue-700'}`}>
                {editingId ? '수정 내용 저장' : '새 거래처 추가'}
            </button>
        </div>

        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="거래처 검색..." className="w-full bg-slate-100 border-none rounded-xl px-4 py-3 text-sm font-bold" />

        <div className="overflow-y-auto flex-1 pr-2 space-y-2">
          {filtered.map(c => (
            <div key={c.id} className="flex items-center justify-between p-3 bg-white border border-slate-100 rounded-xl hover:border-blue-200 transition-colors group">
              <div 
                onClick={() => {
                    if (onSelectForOrder) {
                        onSelectForOrder(c.name);
                    } else if (c.phone) {
                        window.location.href = `tel:${c.phone}`;
                    }
                }} 
                className="flex-1 cursor-pointer flex flex-col justify-center"
              >
                <div className="flex items-center gap-2 mb-0.5">
                    <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">{c.category}</span>
                    <span className="font-bold text-slate-700 group-hover:text-blue-600">{c.name}</span>
                    {c.shortcut && <span className="text-xs text-slate-400">({c.shortcut})</span>}
                </div>
                {c.phone && <div className="text-xs text-slate-400 font-medium pl-1">{c.phone}</div>}
              </div>
              <div className="flex items-center gap-1">
                  {c.phone && (
                      <a href={`tel:${c.phone}`} className="p-2 bg-green-50 text-green-600 rounded-lg hover:bg-green-100 transition-colors" title="전화 걸기">
                          <Phone className="w-4 h-4" />
                      </a>
                  )}
                  <button onClick={() => handleEdit(c)} className="p-2 text-slate-300 hover:text-blue-500 hover:bg-blue-50 rounded-lg transition-colors" title="수정">
                      <Pencil className="w-4 h-4" />
                  </button>
                  <button onClick={() => handleDelete(c.id)} className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="삭제">
                      <Trash className="w-4 h-4" />
                  </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

