                </div>
                <input 
                    type="text" 
                    value={productSearch} 
                    onChange={e => { setProductSearch(e.target.value); setShowProductSuggestions(true); }}
                    onFocus={() => setShowProductSuggestions(true)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-800 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    placeholder="품목명 또는 단축어 검색" 
                />
                {showProductSuggestions && productSearch && filteredProducts.length > 0 && (
                    <div className="absolute z-10 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-lg max-h-40 overflow-y-auto">
                        {filteredProducts.map(p => (
                            <div key={p.id} 
                                 onClick={() => { 
                                     const prefix = itemsStr && !itemsStr.endsWith(' ') ? ' ' : '';
                                     setItemsStr(prev => prev + prefix + p.shortcut);
                                     setProductSearch('');
                                     setShowProductSuggestions(false);
                                     itemsTextareaRef.current?.focus();
                                 }}
                                 className="px-4 py-2 hover:bg-blue-50 cursor-pointer text-sm font-bold text-slate-700 flex justify-between"
                            >
                                <span>{p.name}</span>
                                <span className="text-blue-500">({p.shortcut})</span>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div>
                <label className="text-xs font-bold text-slate-500 mb-1 block">주문 내역 (단축어)</label>
                <textarea 
                    ref={itemsTextareaRef}
                    value={itemsStr} 
                    onChange={e => setItemsStr(e.target.value)} 
                    className="w-full h-24 bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-medium text-slate-800 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none"
                    placeholder="예: 각3 백2 파우다1" 
                />
            </div>

            <div>
                <label className="text-xs font-bold text-slate-500 mb-1 block">메모 (선택 사항)</label>
                <textarea 
                    value={memo} 
                    onChange={e => setMemo(e.target.value)} 
                    className="w-full h-16 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 font-medium text-slate-800 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none text-sm"
                    placeholder="기타 주의사항이나 메모를 입력하세요" 
                />
            </div>
        </div>

        <button onClick={() => onSubmit(clientName, itemsStr, memo)} className="w-full bg-blue-600 text-white rounded-xl py-3.5 font-bold text-lg hover:bg-blue-700 shadow-lg shadow-blue-200 transition-transform active:scale-95">
            저장하기
        </button>
      </div>
    </div>
  );
};

