const DataManagerModal: React.FC<{ orders: Order[], products: ProductDefinition[], clients: ClientDefinition[], financials: FinancialRecord[], onImport: (data: any, msg?: string) => void, onClose: () => void }> = ({ orders, products, clients, financials, onImport, onClose }) => {
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const orderCsvInputRef = useRef<HTMLInputElement>(null);
  const clientCsvInputRef = useRef<HTMLInputElement>(null);
  const productCsvInputRef = useRef<HTMLInputElement>(null);

  const [googleSheetUrl, setGoogleSheetUrl] = useState(() => localStorage.getItem('google_sheet_url_v1') || '');
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    localStorage.setItem('google_sheet_url_v1', googleSheetUrl);
  }, [googleSheetUrl]);

  const parseCSVLine = (line: string): string[] => {
    const result: string[] = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (inQuotes) {
        if (char === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            current += '"';
            i++;
          } else {
            inQuotes = false;
          }
        } else {
          current += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          result.push(current.trim());
          current = '';
        } else {
          current += char;
        }
      }
    }
    result.push(current.trim());
    return result;
  };

  const handleExportJSON = () => {
    const data = { version: '1.0', orders, products, clients, financials };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportOrdersCSV = () => {
    let csv = "날짜,거래처,주문내역\n";
    orders.forEach(o => {
      const itemsStr = o.items.map(i => {
        const p = products.find(prod => prod.id === i.productId);
        return `${p ? p.shortcut : i.name}${i.unitQuantity}`;
      }).join(' ');
      csv += `"${o.date}","${o.clientName}","${itemsStr}"\n`;
    });
    const blob = new Blob(["\uFEFF" + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `orders_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportClientsCSV = () => {
    let csv = "이름,단축어,전화번호,카테고리\n";
    clients.forEach(c => {
        csv += `"${c.name}","${c.shortcut || ''}","${c.phone || ''}","${c.category || ''}"\n`;
    });
    const blob = new Blob(["\uFEFF" + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `clients_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportProductsCSV = () => {
    let csv = "품목명,단축어,카테고리\n";
    products.forEach(p => {
        csv += `"${p.name}","${p.shortcut}","${p.category || ''}"\n`;
    });
    const blob = new Blob(["\uFEFF" + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `products_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleSyncToSheet = async () => {
    if (!googleSheetUrl) {
      alert('구글 앱스 스크립트 URL을 입력해주세요.');
      return;
    }
    if (!confirm('현재 앱의 모든 데이터를 구글 스프레드시트에 저장하시겠습니까?')) return;
    setIsSyncing(true);
    try {
      const payload = { clients, products, orders, financials };
      await fetch(googleSheetUrl, { method: 'POST', mode: 'no-cors', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      alert('저장 요청을 보냈습니다.');
    } catch (e) { alert('전송 중 오류가 발생했습니다.'); } finally { setIsSyncing(false); }
  };

  const handleLoadFromSheet = async () => {
    if (!googleSheetUrl) { alert('구글 앱스 스크립트 URL을 입력해주세요.'); return; }
    if (!confirm('구글 스프레드시트에서 데이터를 불러오시겠습니까?')) return;
    setIsSyncing(true);
    try {
      const response = await fetch(googleSheetUrl);
      const data = await response.json();
      onImport(data, '구글 시트에서 데이터를 성공적으로 불러왔습니다.');
    } catch (e) { alert('데이터를 불러오는 중 오류가 발생했습니다.'); } finally { setIsSyncing(false); }
  };

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>, type: 'JSON' | 'ORDERS' | 'CLIENTS' | 'PRODUCTS') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      if (type === 'JSON') {
        try { onImport(JSON.parse(content)); } catch { alert('올바른 백업 파일이 아닙니다.'); }
      } else {
        const lines = content.split(/\r?\n/).filter(line => line.trim() !== "");
        if (lines.length < 2) { alert('가져올 데이터가 없습니다.'); return; }
        const dataLines = lines.slice(1);
        if (type === 'ORDERS') {
            const newOrders: Order[] = dataLines.map(l => {
              const vals = parseCSVLine(l);
              if (vals.length < 3) return null;
              const [d, c, itemsText] = vals;
              const parts = itemsText.split(/\s+/).filter(p => p);
              const parsedItems: OrderItem[] = parts.map(part => {
                const match = part.match(/^([a-zA-Z가-힣]+)([\d]+(\.\d)?)$/);
                if (match) {
                  const sc = match[1].toUpperCase();
                  const qty = parseFloat(match[2]);
                  const prod = products.find(p => p.shortcut.toUpperCase() === sc);
                  if (prod) return { id: Math.random().toString(36).substr(2, 9), productId: prod.id, name: prod.name, category: prod.category, unitQuantity: qty, isLoaded: false };
                }
                return null;
              }).filter((v): v is OrderItem => v !== null);
              return { id: Math.random().toString(36).substr(2, 9), date: d, clientName: c, items: parsedItems, createdAt: Date.now() };
            }).filter((v): v is Order => v !== null);
            if (newOrders.length > 0) onImport({ orders: newOrders }, '주문 목록 불러오기가 완료되었습니다.');
        } else if (type === 'CLIENTS') {
            const uniqueClientsMap = new Map<string, ClientDefinition>();
            dataLines.forEach((line) => {
                const vals = parseCSVLine(line);
                const rawName = vals[0] || '';
                const cleanName = rawName.trim();
                if (!cleanName) return;
                uniqueClientsMap.set(cleanName, { id: Math.random().toString(36).substr(2, 9), name: cleanName, shortcut: (vals[1] || '').trim(), phone: (vals[2] || '').trim(), category: (vals[3] || '').trim() });
            });
            onImport({ clients: Array.from(uniqueClientsMap.values()) }, '거래처 목록 불러오기가 완료되었습니다.');
        } else if (type === 'PRODUCTS') {
             const newProducts: ProductDefinition[] = dataLines.map((l): ProductDefinition | null => {
                const vals = parseCSVLine(l);
                if (vals.length < 1) return null;
                return { id: Math.random().toString(36).substr(2, 9), name: vals[0] || '', shortcut: vals[1] || '', category: vals[2] || '' };
             }).filter((v): v is ProductDefinition => v !== null && !!v.name && !!v.shortcut);
             onImport({ products: newProducts }, '품목 목록 불러오기가 완료되었습니다.');
        }
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col p-8 space-y-6 max-h-[90vh]">
        <div className="flex justify-between items-center">
          <h3 className="text-2xl font-black text-slate-800">데이터 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl transition-colors">&times;</button>
        </div>
        <div className="overflow-y-auto pr-2 space-y-6">
            <div className="space-y-2 bg-blue-50 p-4 rounded-xl border border-blue-100">
                <h4 className="text-sm font-bold text-blue-800 uppercase tracking-widest border-b border-blue-200 pb-2 mb-2">구글 스프레드시트 연동 (클라우드)</h4>
                <div className="space-y-3">
                    <input type="text" placeholder="Apps Script 웹 앱 URL을 붙여넣으세요" value={googleSheetUrl} onChange={(e) => setGoogleSheetUrl(e.target.value)} className="w-full bg-white border border-blue-200 rounded-lg p-2 text-xs text-slate-700 outline-none focus:ring-2 focus:ring-blue-400" />
                    <div className="grid grid-cols-2 gap-3">
                        <button onClick={handleSyncToSheet} disabled={isSyncing} className="p-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-all font-bold flex items-center justify-center gap-2 shadow-sm disabled:opacity-50">
                            {isSyncing ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Upload className="w-5 h-5" />}
                            <span>시트로 내보내기</span>
                        </button>
                        <button onClick={handleLoadFromSheet} disabled={isSyncing} className="p-3 bg-white border border-blue-200 text-blue-700 rounded-xl hover:bg-blue-50 transition-all font-bold flex items-center justify-center gap-2 shadow-sm disabled:opacity-50">
                             {isSyncing ? <div className="w-4 h-4 border-2 border-blue-200 border-t-blue-600 rounded-full animate-spin" /> : <Download className="w-5 h-5" />}
                            <span>시트에서 가져오기</span>
                        </button>
                    </div>
                </div>
            </div>
            <div className="space-y-2">
                 <h4 className="text-sm font-bold text-slate-500 uppercase tracking-widest border-b border-slate-100 pb-2">시스템 백업/복원 (파일)</h4>
                 <div className="grid grid-cols-2 gap-3">
                    <button onClick={handleExportJSON} className="p-4 border-2 border-slate-100 rounded-xl hover:border-blue-500 hover:bg-blue-50 transition-all font-bold text-slate-700 flex items-center justify-center gap-2"><Download className="w-5 h-5 text-blue-500" /> <span>전체 백업 (JSON)</span></button>
                    <button onClick={() => jsonInputRef.current?.click()} className="p-4 border-2 border-slate-100 rounded-xl hover:border-green-500 hover:bg-green-50 transition-all font-bold text-slate-700 flex items-center justify-center gap-2"><Upload className="w-5 h-5 text-green-500" /> <span>백업 복원 (JSON)</span></button>
                 </div>
            </div>
            <div className="space-y-2">
                 <h4 className="text-sm font-bold text-slate-500 uppercase tracking-widest border-b border-slate-100 pb-2">기타 내보내기/가져오기</h4>
                 <div className="grid grid-cols-2 gap-3">
                    <button onClick={handleExportOrdersCSV} className="p-4 border-2 border-slate-100 rounded-xl hover:border-blue-500 hover:bg-blue-50 transition-all font-bold text-slate-700 flex items-center justify-center gap-2"><Download className="w-5 h-5 text-blue-500" /> <span>주문 CSV</span></button>
                    <button onClick={() => orderCsvInputRef.current?.click()} className="p-4 border-2 border-slate-100 rounded-xl hover:border-green-500 hover:bg-green-50 transition-all font-bold text-slate-700 flex items-center justify-center gap-2"><Upload className="w-5 h-5 text-green-500" /> <span>주문 CSV</span></button>
                 </div>
            </div>
        </div>
        <input type="file" ref={jsonInputRef} onChange={e => handleFile(e, 'JSON')} hidden accept=".json" />
        <input type="file" ref={orderCsvInputRef} onChange={e => handleFile(e, 'ORDERS')} hidden accept=".csv" />
        <input type="file" ref={clientCsvInputRef} onChange={e => handleFile(e, 'CLIENTS')} hidden accept=".csv" />
        <input type="file" ref={productCsvInputRef} onChange={e => handleFile(e, 'PRODUCTS')} hidden accept=".csv" />
      </div>
    </div>
  );
};

const ProductManagerModal: React.FC<{ products: ProductDefinition[], setProducts: React.Dispatch<React.SetStateAction<ProductDefinition[]>>, onClose: () => void, onSelectForOrder?: (product: ProductDefinition) => void }> = ({ products, setProducts, onClose, onSelectForOrder }) => {
  const [name, setName] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState(PRODUCT_CATEGORIES[0]);
  const [searchTerm, setSearchTerm] = useState('');

  const handleAdd = () => {
    if (!name || !shortcut) return;
    setProducts(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), name, shortcut, category }]);
    setName('');
    setShortcut('');
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if(confirm('정말 삭제하시겠습니까?')) setProducts(prev => prev.filter(p => p.id !== id));
  };

  const filtered = products.filter(p => p.name.includes(searchTerm) || p.shortcut.includes(searchTerm) || getChosung(p.name).includes(searchTerm));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col p-8 space-y-6 max-h-[85vh]">
        <div className="flex justify-between items-center">
          <h3 className="text-2xl font-black text-slate-800">품목 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl transition-colors">&times;</button>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-2 p-4 bg-slate-50 rounded-xl border border-slate-100">
          <select value={category} onChange={e => setCategory(e.target.value)} className="bg-white border border-slate-200 rounded-lg px-2 py-2 text-sm w-full">
            {PRODUCT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <input value={name} onChange={e => setName(e.target.value)} placeholder="품목명" className="bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500 w-full" />
          <input value={shortcut} onChange={e => setShortcut(e.target.value)} placeholder="단축어" className="bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500 w-full" />
          <button onClick={handleAdd} className="bg-blue-600 text-white rounded-lg px-4 py-2 font-bold hover:bg-blue-700 transition-colors w-full">추가</button>
        </div>
        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="품목 검색..." className="w-full bg-slate-100 border-none rounded-xl px-4 py-3 text-sm font-bold" />
        <div className="overflow-y-auto flex-1 pr-2 space-y-2">
          {filtered.map(p => (
            <div key={p.id} onClick={() => onSelectForOrder && onSelectForOrder(p)} className={`flex items-center justify-between p-3 bg-white border border-slate-100 rounded-xl transition-colors ${onSelectForOrder ? 'cursor-pointer hover:bg-blue-50 hover:border-blue-200' : ''}`}>
              <div className="flex items-center gap-3">
                <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">{p.category}</span>
                <span className="font-bold text-slate-700">{p.name}</span>
                <span className="text-xs font-bold text-blue-500 bg-blue-50 px-1.5 py-0.5 rounded">Cmd: {p.shortcut}</span>
              </div>
              <button onClick={(e) => handleDelete(p.id, e)} className="text-slate-300 hover:text-red-500"><Trash className="w-4 h-4" /></button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const ClientManagerModal: React.FC<{ clients: ClientDefinition[], setClients: React.Dispatch<React.SetStateAction<ClientDefinition[]>>, onClose: () => void, onSelectForOrder?: (name: string) => void }> = ({ clients, setClients, onClose, onSelectForOrder }) => {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [shortcut, setShortcut] = useState('');
  const [category, setCategory] = useState(CLIENT_CATEGORIES[0]);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  const handleSave = () => {
    if (!name) return;
    if (editingId) setClients(prev => prev.map(c => c.id === editingId ? { ...c, name, phone, shortcut, category } : c));
    else setClients(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), name, phone, shortcut, category }]);
    resetForm();
    setEditingId(null);
  };

  const handleEdit = (client: ClientDefinition) => {
      setEditingId(client.id);
      setName(client.name);
      setPhone(client.phone || '');
      setShortcut(client.shortcut || '');
      setCategory(client.category || CLIENT_CATEGORIES[0]);
  };

  const resetForm = () => { setName(''); setPhone(''); setShortcut(''); setCategory(CLIENT_CATEGORIES[0]); }
  const handleDelete = (id: string) => { if(confirm('삭제하시겠습니까?')) setClients(prev => prev.filter(c => c.id !== id)); };

  const filtered = clients.filter(c => c.name.includes(searchTerm) || (c.shortcut && c.shortcut.includes(searchTerm)));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col p-8 space-y-6 max-h-[85vh]">
        <div className="flex justify-between items-center">
          <h3 className="text-2xl font-black text-slate-800">거래처 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl transition-colors">&times;</button>
        </div>
        <div className="bg-slate-50 rounded-xl border border-slate-100 p-4 space-y-3">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                <select value={category} onChange={e => setCategory(e.target.value)} className="bg-white border border-slate-200 rounded-lg px-2 py-2 text-sm"><option value="">지역선택</option>{CLIENT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}</select>
                <input value={name} onChange={e => setName(e.target.value)} placeholder="거래처명" className="bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                <input value={phone} onChange={e => setPhone(e.target.value)} placeholder="전화번호" className="bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                <input value={shortcut} onChange={e => setShortcut(e.target.value)} placeholder="단축어" className="bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm" />
            </div>
            <button onClick={handleSave} className="w-full bg-blue-600 text-white rounded-lg py-3 font-bold">{editingId ? '수정 저장' : '거래처 추가'}</button>
        </div>
        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="거래처 검색..." className="w-full bg-slate-100 border-none rounded-xl px-4 py-3 text-sm font-bold" />
        <div className="overflow-y-auto flex-1 pr-2 space-y-2">
          {filtered.map(c => (
            <div key={c.id} className="flex items-center justify-between p-3 bg-white border border-slate-100 rounded-xl hover:border-blue-200 transition-colors group">
              <div onClick={() => onSelectForOrder ? onSelectForOrder(c.name) : (c.phone && (window.location.href = `tel:${c.phone}`))} className="flex-1 cursor-pointer">
                <div className="flex items-center gap-2 mb-0.5">
                    <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">{c.category}</span>
                    <span className="font-bold text-slate-700">{c.name}</span>
                </div>
                {c.phone && <div className="text-xs text-slate-400">{c.phone}</div>}
              </div>
              <div className="flex gap-1">
                  <button onClick={() => handleEdit(c)} className="p-2 text-slate-300 hover:text-blue-500"><Pencil className="w-4 h-4" /></button>
                  <button onClick={() => handleDelete(c.id)} className="p-2 text-slate-300 hover:text-red-500"><Trash className="w-4 h-4" /></button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const OrderModal: React.FC<{
  onClose: () => void;
  onSubmit: (clientName: string, itemsStr: string, memo: string) => void;
  selectedDate: string;
  products: ProductDefinition[];
  clients: ClientDefinition[];
  initialClientName: string;
  initialItemsStr: string;
  initialMemo: string;
  isEditing: boolean;
  onOpenProductManager: (currentClientName: string, currentItemsStr: string, currentMemo: string) => void;
  onOpenClientManager: (currentClientName: string, currentItemsStr: string, currentMemo: string) => void;
}> = ({ onClose, onSubmit, selectedDate, products, clients, initialClientName, initialItemsStr, initialMemo, isEditing, onOpenProductManager, onOpenClientManager }) => {
  const [clientName, setClientName] = useState(initialClientName);
  const [itemsStr, setItemsStr] = useState(initialItemsStr);
  const [memo, setMemo] = useState(initialMemo);
  const [showClientSuggestions, setShowClientSuggestions] = useState(false);
  const [productSearch, setProductSearch] = useState('');
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const itemsTextareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => { setClientName(initialClientName); }, [initialClientName]);
  useEffect(() => { setItemsStr(initialItemsStr); }, [initialItemsStr]);
  useEffect(() => { setMemo(initialMemo); }, [initialMemo]);

  const filteredClients = useMemo(() => {
    if (!clientName) return [];
    return clients.filter(c => c.name.includes(clientName) || (c.shortcut && c.shortcut.includes(clientName)) || getChosung(c.name).includes(clientName)).slice(0, 5);
  }, [clients, clientName]);

  const filteredProducts = useMemo(() => {
    if (!productSearch) return [];
    return products.filter(p => p.name.includes(productSearch) || p.shortcut.includes(productSearch) || getChosung(p.name).includes(productSearch)).slice(0, 5);
  }, [products, productSearch]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg flex flex-col p-6 space-y-4">
        <div className="flex justify-between items-center border-b border-slate-100 pb-4">
          <h3 className="text-xl font-black text-slate-800">{isEditing ? '주문 수정' : '새 주문'}</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
        </div>
        <div className="space-y-4 overflow-y-auto max-h-[60vh] pr-1">
            <div className="relative">
                <input type="text" value={clientName} onChange={e => { setClientName(e.target.value); setShowClientSuggestions(true); }} placeholder="거래처명" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold" />
                {showClientSuggestions && clientName && filteredClients.length > 0 && (
                    <div className="absolute z-10 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-lg max-h-40 overflow-y-auto">
                        {filteredClients.map(c => <div key={c.id} onClick={() => { setClientName(c.name); setShowClientSuggestions(false); }} className="px-4 py-2 hover:bg-blue-50 cursor-pointer text-sm font-bold">{c.name}</div>)}
                    </div>
                )}
            </div>
            <div className="relative">
                <input type="text" value={productSearch} onChange={e => { setProductSearch(e.target.value); setShowProductSuggestions(true); }} placeholder="품목 검색 추가" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold" />
                {showProductSuggestions && productSearch && filteredProducts.length > 0 && (
                    <div className="absolute z-10 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-lg max-h-40 overflow-y-auto">
                        {filteredProducts.map(p => <div key={p.id} onClick={() => { setItemsStr(prev => prev + (prev && !prev.endsWith(' ') ? ' ' : '') + p.shortcut); setProductSearch(''); setShowProductSuggestions(false); itemsTextareaRef.current?.focus(); }} className="px-4 py-2 hover:bg-blue-50 cursor-pointer text-sm font-bold flex justify-between"><span>{p.name}</span><span className="text-blue-500">{p.shortcut}</span></div>)}
                    </div>
                )}
            </div>
            <textarea ref={itemsTextareaRef} value={itemsStr} onChange={e => setItemsStr(e.target.value)} className="w-full h-24 bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-medium" placeholder="예: 각3 백2" />
            <textarea value={memo} onChange={e => setMemo(e.target.value)} className="w-full h-16 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm" placeholder="메모" />
        </div>
        <button onClick={() => onSubmit(clientName, itemsStr, memo)} className="w-full bg-blue-600 text-white rounded-xl py-3.5 font-bold shadow-lg shadow-blue-200 transition-transform active:scale-95">저장</button>
      </div>
    </div>
  );
};

