  useEffect(() => { setClientName(initialClientName); }, [initialClientName]);
  useEffect(() => { setItemsStr(initialItemsStr); }, [initialItemsStr]);
  useEffect(() => { setMemo(initialMemo); }, [initialMemo]);

  const filteredClients = useMemo(() => {
    if (!clientName) return [];
    return clients.filter(c => c.name.includes(clientName) || (c.shortcut && c.shortcut.includes(clientName)) || getChosung(c.name).includes(clientName)).slice(0, 5);
  }, [clients, clientName]);

  const filteredProducts = useMemo(() => {
    if (!productSearch) return [];
    return products.filter(p => p.name.includes(productSearch) || p.shortcut.includes(productSearch) || getChosung(p.name).includes(productSearch)).slice(0, 5);
  }, [products, productSearch]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg flex flex-col p-6 space-y-4">
