                    </div>
                    <div className="bg-blue-50 p-4 rounded-xl flex justify-between items-center border border-blue-100">
                        <span className="font-bold text-blue-800">기간 총 매출</span>
                        <span className="font-black text-2xl text-blue-600">{(totals.cash + totals.transfer + totals.card + totals.note).toLocaleString()}원</span>
