const DataManagerModal: React.FC<{ orders: Order[], products: ProductDefinition[], clients: ClientDefinition[], financials: FinancialRecord[], onImport: (data: any, msg?: string) => void, onClose: () => void }> = ({ orders, products, clients, financials, onImport, onClose }) => {
  const jsonInputRef = useRef<HTMLInputElement>(null);

  const [googleSheetUrl, setGoogleSheetUrl] = useState(() => localStorage.getItem('google_sheet_url_v1') || '');
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    localStorage.setItem('google_sheet_url_v1', googleSheetUrl);
  }, [googleSheetUrl]);

  const parseCSVLine = (line: string): string[] => {
    const result: string[] = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (inQuotes) {
        if (char === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            current += '"';
            i++;
          } else {
            inQuotes = false;
          }
        } else {
          current += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          result.push(current.trim());
          current = '';
        } else {
          current += char;
        }
      }
    }
    result.push(current.trim());
    return result;
  };

  const handleExportJSON = () => {
    const data = { version: '1.0', orders, products, clients, financials };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportOrdersCSV = () => {
    let csv = "날짜,거래처,주문내역\n";
    orders.forEach(o => {
      const itemsStr = o.items.map(i => {
        const p = products.find(prod => prod.id === i.productId);
        return `${p ? p.shortcut : i.name}${i.unitQuantity}`;
      }).join(' ');
      csv += `"${o.date}","${o.clientName}","${itemsStr}"\n`;
    });
    const blob = new Blob(["\uFEFF" + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `orders_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportClientsCSV = () => {
    let csv = "이름,단축어,전화번호,카테고리\n";
    clients.forEach(c => {
        csv += `"${c.name}","${c.shortcut || ''}","${c.phone || ''}","${c.category || ''}"\n`;
    });
    const blob = new Blob(["\uFEFF" + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `clients_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportProductsCSV = () => {
    let csv = "품목명,단축어,카테고리,금액\n";
    products.forEach(p => {
        csv += `"${p.name}","${p.shortcut}","${p.category || ''}","${p.price || 0}"\n`;
    });
    const blob = new Blob(["\uFEFF" + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `products_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleSyncToSheet = async () => {
    if (!googleSheetUrl) {
      alert('구글 앱스 스크립트 URL을 입력해주세요.');
      return;
    }
    if (!confirm('현재 앱의 모든 데이터를 구글 스프레드시트에 저장하시겠습니까?')) return;
    setIsSyncing(true);
    try {
      const payload = { clients, products, orders, financials };
      await fetch(googleSheetUrl, { method: 'POST', mode: 'no-cors', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      alert('저장 요청을 보냈습니다.');
    } catch (e) { alert('전송 중 오류가 발생했습니다.'); } finally { setIsSyncing(false); }
  };

  const handleLoadFromSheet = async () => {
    if (!googleSheetUrl) { alert('구글 앱스 스크립트 URL을 입력해주세요.'); return; }
    if (!confirm('구글 스프레드시트에서 데이터를 불러오시겠습니까?')) return;
    setIsSyncing(true);
    try {
      const response = await fetch(googleSheetUrl);
      const data = await response.json();
      onImport(data, '구글 시트에서 데이터를 성공적으로 불러왔습니다.');
    } catch (e) { alert('데이터를 불러오는 중 오류가 발생했습니다.'); } finally { setIsSyncing(false); }
  };

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>, type: 'JSON' | 'ORDERS' | 'CLIENTS' | 'PRODUCTS') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      if (type === 'JSON') {
        try { onImport(JSON.parse(content)); } catch { alert('올바른 백업 파일이 아닙니다.'); }
      } else {
        const lines = content.split(/\r?\n/).filter(line => line.trim() !== "");
        if (lines.length < 2) { alert('가져올 데이터가 없습니다.'); return; }
        const dataLines = lines.slice(1);
        if (type === 'ORDERS') {
            const newOrders: Order[] = dataLines.map(l => {
              const vals = parseCSVLine(l);
              if (vals.length < 3) return null;
              const [d, c, itemsText] = vals;
              const parts = itemsText.split(/\s+/).filter(p => p);
              const parsedItems: OrderItem[] = parts.map(part => {
                const match = part.match(/^([a-zA-Z가-힣]+)([\d]+(\.\d)?)$/);
                if (match) {
                  const sc = match[1].toUpperCase();
                  const qty = parseFloat(match[2]);
                  const prod = products.find(p => p.shortcut.toUpperCase() === sc);
                  if (prod) return { id: Math.random().toString(36).substr(2, 9), productId: prod.id, name: prod.name, category: prod.category, unitQuantity: qty, isLoaded: false };
                }
                return null;
              }).filter((v): v is OrderItem => v !== null);
              return { id: Math.random().toString(36).substr(2, 9), date: d, clientName: c, items: parsedItems, createdAt: Date.now() };
            }).filter((v): v is Order => v !== null);
            if (newOrders.length > 0) onImport({ orders: newOrders }, '주문 목록 불러오기가 완료되었습니다.');
        } else if (type === 'CLIENTS') {
            const uniqueClientsMap = new Map<string, ClientDefinition>();
            dataLines.forEach((line) => {
                const vals = parseCSVLine(line);
                const rawName = vals[0] || '';
                const cleanName = rawName.trim();
                if (!cleanName) return;
                uniqueClientsMap.set(cleanName, { id: Math.random().toString(36).substr(2, 9), name: cleanName, shortcut: (vals[1] || '').trim(), phone: (vals[2] || '').trim(), category: (vals[3] || '').trim() });
            });
            onImport({ clients: Array.from(uniqueClientsMap.values()) }, '거래처 목록 불러오기가 완료되었습니다.');
        } else if (type === 'PRODUCTS') {
             const newProducts: ProductDefinition[] = dataLines.map((l): ProductDefinition | null => {
                const vals = parseCSVLine(l);
                if (vals.length < 1) return null;
                return { id: Math.random().toString(36).substr(2, 9), name: vals[0] || '', shortcut: vals[1] || '', category: vals[2] || '', price: parseInt(vals[3]) || 0 };
             }).filter((v): v is ProductDefinition => v !== null && !!v.name && !!v.shortcut);
             onImport({ products: newProducts }, '품목 목록 불러오기가 완료되었습니다.');
        }
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col p-6 space-y-6 max-h-[85vh] overflow-y-auto">
        <div className="flex justify-between items-center">
          <h3 className="text-2xl font-black text-slate-800">데이터 관리</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl transition-colors">&times;</button>
        </div>

        <div className="space-y-4">
          <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
            <h4 className="font-bold text-slate-700 mb-2">백업 및 복원 (JSON)</h4>
            <div className="flex gap-2">
              <button onClick={handleExportJSON} className="flex-1 bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700 transition-colors flex items-center justify-center gap-2">
                <Download className="w-4 h-4" /> 전체 백업 저장
              </button>
              <button onClick={() => jsonInputRef.current?.click()} className="flex-1 bg-white border border-slate-300 text-slate-700 py-2 rounded-lg font-bold hover:bg-slate-50 transition-colors flex items-center justify-center gap-2">
                <Upload className="w-4 h-4" /> 백업 파일 복원
              </button>
              <input type="file" ref={jsonInputRef} onChange={e => handleFile(e, 'JSON')} accept=".json" className="hidden" />
            </div>
          </div>

          <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
            <h4 className="font-bold text-slate-700 mb-2">CSV 내보내기/가져오기</h4>
            <div className="space-y-2">
               <div className="flex gap-2 items-center">
                 <span className="w-16 text-xs font-bold text-slate-500">주문</span>
                 <button onClick={handleExportOrdersCSV} className="text-xs bg-slate-200 px-3 py-1.5 rounded hover:bg-slate-300 font-bold">내보내기</button>
                 <label className="text-xs bg-slate-200 px-3 py-1.5 rounded hover:bg-slate-300 font-bold cursor-pointer">
                    가져오기 <input type="file" onChange={e => handleFile(e, 'ORDERS')} accept=".csv" className="hidden" />
                 </label>
               </div>
               <div className="flex gap-2 items-center">
                 <span className="w-16 text-xs font-bold text-slate-500">거래처</span>
                 <button onClick={handleExportClientsCSV} className="text-xs bg-slate-200 px-3 py-1.5 rounded hover:bg-slate-300 font-bold">내보내기</button>
                 <label className="text-xs bg-slate-200 px-3 py-1.5 rounded hover:bg-slate-300 font-bold cursor-pointer">
                    가져오기 <input type="file" onChange={e => handleFile(e, 'CLIENTS')} accept=".csv" className="hidden" />
                 </label>
               </div>
               <div className="flex gap-2 items-center">
                 <span className="w-16 text-xs font-bold text-slate-500">품목</span>
                 <button onClick={handleExportProductsCSV} className="text-xs bg-slate-200 px-3 py-1.5 rounded hover:bg-slate-300 font-bold">내보내기</button>
                 <label className="text-xs bg-slate-200 px-3 py-1.5 rounded hover:bg-slate-300 font-bold cursor-pointer">
                    가져오기 <input type="file" onChange={e => handleFile(e, 'PRODUCTS')} accept=".csv" className="hidden" />
                 </label>
               </div>
            </div>
          </div>

          <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
             <h4 className="font-bold text-slate-700 mb-2">구글 스프레드시트 연동 (Beta)</h4>
             <input value={googleSheetUrl} onChange={e => setGoogleSheetUrl(e.target.value)} placeholder="Apps Script Web App URL" className="w-full text-xs bg-white border border-slate-200 rounded p-2 mb-2" />
             <div className="flex gap-2">
                <button onClick={handleSyncToSheet} disabled={isSyncing} className="flex-1 bg-green-600 text-white py-2 rounded-lg font-bold text-xs hover:bg-green-700 disabled:opacity-50">
                   {isSyncing ? '전송 중...' : '시트로 내보내기'}
                </button>
                <button onClick={handleLoadFromSheet} disabled={isSyncing} className="flex-1 bg-white border border-green-600 text-green-700 py-2 rounded-lg font-bold text-xs hover:bg-green-50 disabled:opacity-50">
                   {isSyncing ? '불러오는 중...' : '시트에서 가져오기'}
                </button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

