            <label className="text-[10px] font-bold text-slate-400">금액</label>
            <input value={price} onChange={e => setPrice(e.target.value)} placeholder="금액" className="bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500 w-full" />
