  clients: ClientDefinition[];
  initialClientName: string;
  initialItemsStr: string;
  initialMemo: string;
  isEditing: boolean;
  onOpenProductManager: (currentClientName: string, currentItemsStr: string, currentMemo: string) => void;
  onOpenClientManager: (currentClientName: string, currentItemsStr: string, currentMemo: string) => void;
}> = ({ onClose, onSubmit, selectedDate, products, clients, initialClientName, initialItemsStr, initialMemo, isEditing, onOpenProductManager, onOpenClientManager }) => {
  const [clientName, setClientName] = useState(initialClientName);
  const [itemsStr, setItemsStr] = useState(initialItemsStr);
  const [memo, setMemo] = useState(initialMemo);
  const [showClientSuggestions, setShowClientSuggestions] = useState(false);
  const [productSearch, setProductSearch] = useState('');
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const itemsTextareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => { setClientName(initialClientName); }, [initialClientName]);
  useEffect(() => { setItemsStr(initialItemsStr); }, [initialItemsStr]);
  useEffect(() => { setMemo(initialMemo); }, [initialMemo]);

  const filteredClients = useMemo(() => {
    if (!clientName) return [];
    return clients.filter(c => c.name.includes(clientName) || (c.shortcut && c.shortcut.includes(clientName)) || getChosung(c.name).includes(clientName)).slice(0, 5);
  }, [clients, clientName]);

  const filteredProducts = useMemo(() => {
    if (!productSearch) return [];
    return products.filter(p => p.name.includes(productSearch) || p.shortcut.includes(productSearch) || getChosung(p.name).includes(productSearch)).slice(0, 5);
  }, [products, productSearch]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg flex flex-col p-6 space-y-4">
        <div className="flex justify-between items-center border-b border-slate-100 pb-4">
          <h3 className="text-xl font-black text-slate-800">{isEditing ? '주문 수정' : '새 주문'}</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
        </div>
        <div className="space-y-4 overflow-y-auto max-h-[60vh] pr-1">
            <div className="relative">
                <input type="text" value={clientName} onChange={e => { setClientName(e.target.value); setShowClientSuggestions(true); }} placeholder="거래처명" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold" />
                {showClientSuggestions && clientName && filteredClients.length > 0 && (
                    <div className="absolute z-10 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-lg max-h-40 overflow-y-auto">
                        {filteredClients.map(c => <div key={c.id} onClick={() => { setClientName(c.name); setShowClientSuggestions(false); }} className="px-4 py-2 hover:bg-blue-50 cursor-pointer text-sm font-bold">{c.name}</div>)}
                    </div>
                )}
            </div>
            <div className="relative">
                <input type="text" value={productSearch} onChange={e => { setProductSearch(e.target.value); setShowProductSuggestions(true); }} placeholder="품목 검색 추가" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold" />
                {showProductSuggestions && productSearch && filteredProducts.length > 0 && (
                    <div className="absolute z-10 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-lg max-h-40 overflow-y-auto">
                        {filteredProducts.map(p => <div key={p.id} onClick={() => { setItemsStr(prev => prev + (prev && !prev.endsWith(' ') ? ' ' : '') + p.shortcut); setProductSearch(''); setShowProductSuggestions(false); itemsTextareaRef.current?.focus(); }} className="px-4 py-2 hover:bg-blue-50 cursor-pointer text-sm font-bold flex justify-between"><span>{p.name}</span><span className="text-blue-500">{p.shortcut}</span></div>)}
                    </div>
                )}
            </div>
            <textarea ref={itemsTextareaRef} value={itemsStr} onChange={e => setItemsStr(e.target.value)} className="w-full h-24 bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-medium" placeholder="예: 각3 백2" />
            <textarea value={memo} onChange={e => setMemo(e.target.value)} className="w-full h-16 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm" placeholder="메모" />
        </div>
        <button onClick={() => onSubmit(clientName, itemsStr, memo)} className="w-full bg-blue-600 text-white rounded-xl py-3.5 font-bold shadow-lg shadow-blue-200 transition-transform active:scale-95">저장</button>
      </div>
    </div>
  );
};

