         <div className="bg-slate-50 rounded-xl p-4 grid gap-3 grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 items-end">
             <div className="col-span-1 lg:col-span-1 space-y-1">
                 <label className="text-[10px] font-bold text-slate-400">카테고리</label>
                 <select value={category} onChange={e => setCategory(e.target.value)} className="w-full text-sm p-2 rounded-lg border border-slate-200 font-bold">{PRODUCT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}</select>
             </div>
             <div className="col-span-1 lg:col-span-1 space-y-1">
                 <label className="text-[10px] font-bold text-slate-400">단축어</label>
                 <input value={shortcut} onChange={e => setShortcut(e.target.value)} className="w-full text-sm p-2 rounded-lg border border-slate-200 font-bold" placeholder="예: 크" />
             </div>
             <div className="col-span-1 lg:col-span-1 space-y-1">
                 <label className="text-[10px] font-bold text-slate-400">품목명</label>
