             </div>
             <div className="col-span-1 lg:col-span-1 space-y-1">
                 <label className="text-[10px] font-bold text-slate-400">단가</label>
                 <input type="number" value={price} onChange={e => setPrice(e.target.value)} className="w-full text-sm p-2 rounded-lg border border-slate-200 font-bold" placeholder="0" />
             </div>
             <button onClick={handleSave} className="bg-blue-600 text-white font-bold p-2 rounded-lg hover:bg-blue-700 h-[38px]">추가</button>
         </div>

         <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="검색..." className="bg-slate-100 rounded-xl px-4 py-2 w-full font-bold text-sm" />

         <div className="flex-1 overflow-y-auto space-y-2 pr-2">
             {filtered.map(p => (
                 <div key={p.id} onClick={() => onSelectForOrder ? onSelectForOrder(p) : null} className={`flex items-center justify-between p-3 bg-white border border-slate-100 rounded-xl hover:border-blue-200 transition-colors ${onSelectForOrder ? 'cursor-pointer hover:bg-blue-50' : ''}`}>
                     <div className="flex items-center gap-2">
                         <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">{p.category}</span>
                         <span className="font-bold text-slate-700">{p.name}</span>
                         <span className="text-xs text-blue-500 font-bold bg-blue-50 px-1.5 py-0.5 rounded">{p.shortcut}</span>
                         {p.price && <span className="text-xs text-slate-400 ml-2">{p.price.toLocaleString()}원</span>}
                     </div>
                     <button onClick={(e) => { e.stopPropagation(); handleDelete(p.id); }} className="text-slate-300 hover:text-red-500"><Trash className="w-4 h-4" /></button>
                 </div>
             ))}
         </div>
      </div>
    </div>
  );
};

const DataManagerModal: React.FC<{
  orders: Order[];
  products: ProductDefinition[];
  clients: ClientDefinition[];
  financials: FinancialRecord[];
  onImport: (data: any) => void;
  onClose: () => void;
}> = ({ orders, products, clients, financials, onImport, onClose }) => {
  const handleExport = () => {
      const data = { orders, products, clients, financials, version: 'v11' };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `smart_loading_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
          try {
              const data = JSON.parse(event.target?.result as string);
              onImport(data);
          } catch (err) {
              alert('파일 형식이 올바르지 않습니다.');
          }
      };
      reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-6 space-y-6">
         <div className="flex justify-between items-center">
             <h3 className="text-xl font-black text-slate-800">데이터 백업 / 복원</h3>
             <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
         </div>
         <div className="space-y-4">
             <button onClick={handleExport} className="w-full flex items-center justify-center gap-3 bg-blue-50 hover:bg-blue-100 text-blue-700 font-bold py-4 rounded-xl border-2 border-blue-100 transition-colors">
                 <Download className="w-6 h-6" />
                 <span>데이터 내보내기 (백업)</span>
             </button>
             <div className="relative">
                 <input type="file" onChange={handleFileChange} accept=".json" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                 <div className="w-full flex items-center justify-center gap-3 bg-slate-50 hover:bg-slate-100 text-slate-700 font-bold py-4 rounded-xl border-2 border-slate-100 transition-colors">
                     <Upload className="w-6 h-6" />
                     <span>데이터 가져오기 (복원)</span>
                 </div>
             </div>
         </div>
      </div>
    </div>
  );
};

