const SummaryDetailModal: React.FC<{
  itemName: string;
  category: string;
  orders: Order[];
  onClose: () => void;
}> = ({ itemName, category, orders, onClose }) => {
  const relatedOrders = orders.filter(o => o.items.some(i => i.name === itemName));
  const total = relatedOrders.reduce((sum, o) => sum + o.items.filter(i => i.name === itemName).reduce((s, i) => s + i.unitQuantity, 0), 0);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden">
         <div className="bg-blue-600 p-5 text-white">
             <div className="flex justify-between items-start">
                 <div>
                     <span className="text-blue-200 text-xs font-bold uppercase tracking-wider">{category}</span>
                     <h3 className="text-2xl font-black mt-1">{itemName}</h3>
                 </div>
                 <button onClick={onClose} className="text-blue-200 hover:text-white text-2xl">&times;</button>
             </div>
             <div className="mt-4 flex items-baseline gap-1">
                 <span className="text-4xl font-black">{Number(total.toFixed(1))}</span>
                 <span className="text-blue-200 font-bold">개</span>
             </div>
         </div>
         <div className="max-h-[50vh] overflow-y-auto p-2">
             {relatedOrders.map(order => {
                 const qty = order.items.filter(i => i.name === itemName).reduce((s, i) => s + i.unitQuantity, 0);
                 return (
                     <div key={order.id} className="flex justify-between items-center p-3 hover:bg-slate-50 rounded-xl border-b border-slate-50 last:border-0">
                         <span className="font-bold text-slate-700">{order.clientName}</span>
                         <span className="font-black text-blue-600 bg-blue-50 px-2 py-1 rounded-lg">{qty}</span>
                     </div>
                 );
             })}
         </div>
      </div>
    </div>
