                 <h3 className="text-xl font-black text-slate-800">마감 관리</h3>
                 <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
             </div>
             <div className="flex p-2 gap-2 bg-slate-50 border-b border-slate-100">
                 <button onClick={() => setTab('input')} className={`flex-1 py-2 rounded-xl text-sm font-bold transition-colors ${tab === 'input' ? 'bg-white shadow text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>입력 ({selectedDate})</button>
                 <button onClick={() => setTab('chart')} className={`flex-1 py-2 rounded-xl text-sm font-bold transition-colors ${tab === 'chart' ? 'bg-white shadow text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>기록 목록</button>
