                         <div className="bg-blue-50 p-4 rounded-xl text-center">
                             <p className="text-sm font-bold text-blue-400 mb-1">{selectedDate} 총 매출</p>
                             <p className="text-3xl font-black text-blue-700">{(selectedFinancial.cash + selectedFinancial.transfer + selectedFinancial.card + selectedFinancial.note).toLocaleString()}원</p>
                         </div>
                         <div className="space-y-4">
                             <div><label className="text-xs font-bold text-slate-500">현금</label><input type="text" value={selectedFinancial.cash} onChange={e => onUpdateFinancial(selectedDate, 'cash', e.target.value)} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-right" /></div>
                             <div><label className="text-xs font-bold text-slate-500">이체</label><input type="text" value={selectedFinancial.transfer} onChange={e => onUpdateFinancial(selectedDate, 'transfer', e.target.value)} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-right" /></div>
                             <div><label className="text-xs font-bold text-slate-500">카드</label><input type="text" value={selectedFinancial.card} onChange={e => onUpdateFinancial(selectedDate, 'card', e.target.value)} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-right" /></div>
                             <div><label className="text-xs font-bold text-slate-500">어음</label><input type="text" value={selectedFinancial.note} onChange={e => onUpdateFinancial(selectedDate, 'note', e.target.value)} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-right" /></div>
