        </div>

        {mode === 'register' && (
            <div className="bg-slate-50 rounded-xl border border-slate-100 p-4">
                <div className="grid gap-4 grid-cols-1">
                    <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400">지역</label>
                    <select value={category} onChange={e => setCategory(e.target.value)} className="bg-white border border-slate-200 rounded-lg px-3 py-2.5 text-sm w-full font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500"><option value="">지역선택</option>{CLIENT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}</select>
                    </div>
                    <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400">거래처명</label>
                    <input value={name} onChange={e => setName(e.target.value)} placeholder="거래처명 입력" className="bg-white border border-slate-200 rounded-lg px-3 py-2.5 text-sm w-full font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500" />
                    </div>
                    <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400">전화번호</label>
                    <input value={phone} onChange={e => setPhone(e.target.value)} placeholder="010-0000-0000" className="bg-white border border-slate-200 rounded-lg px-3 py-2.5 text-sm w-full font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500" />
                    </div>
                    <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400">단축어</label>
                    <input value={shortcut} onChange={e => setShortcut(e.target.value)} placeholder="예: 한산" className="bg-white border border-slate-200 rounded-lg px-3 py-2.5 text-sm w-full font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500" />
                    </div>
                </div>
            </div>
        )}

        {mode === 'list' && (
            <>
                <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="거래처 검색..." className="w-full bg-slate-100 border-none rounded-xl px-4 py-3 text-sm font-bold" />
                <div className="overflow-y-auto flex-1 pr-2 space-y-2">
                {filtered.map(c => (
                    <div key={c.id} className="flex items-center justify-between p-3 bg-white border border-slate-100 rounded-xl hover:border-blue-200 transition-colors group">
                    <div onClick={() => onSelectForOrder ? onSelectForOrder(c.name) : null} className={`flex-1 ${onSelectForOrder ? 'cursor-pointer' : ''}`}>
                        <div className="flex items-center gap-2 mb-0.5">
                            <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">{c.category}</span>
                            <span className="font-bold text-slate-700">{c.name}</span>
                            {c.shortcut && <span className="text-xs text-blue-500 font-bold bg-blue-50 px-1.5 py-0.5 rounded">{c.shortcut}</span>}
                        </div>
                        {c.phone && <div className="text-xs text-slate-400">{c.phone}</div>}
                    </div>
                    <div className="flex gap-1 items-center">
                        {c.phone && (
                            <a href={`tel:${c.phone}`} className="p-2 text-slate-300 hover:text-green-500 bg-slate-50 hover:bg-green-50 rounded-lg transition-colors" onClick={(e) => e.stopPropagation()}>
                                <Phone className="w-4 h-4" />
                            </a>
                        )}
                        <button onClick={() => handleEdit(c)} className="p-2 text-slate-300 hover:text-blue-500 hover:bg-blue-50 rounded-lg transition-colors"><Pencil className="w-4 h-4" /></button>
                        <button onClick={() => handleDelete(c.id)} className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"><Trash className="w-4 h-4" /></button>
                    </div>
                    </div>
                ))}
                </div>
            </>
        )}
      </div>
    </div>
  );
};

