                        <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 font-bold text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none transition-colors" />
                    </div>
                    <span className="text-slate-400 mt-5 font-bold">~</span>
                    <div className="flex flex-col flex-1">
                        <label className="text-xs font-bold text-slate-400 mb-1">종료일</label>
                        <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 font-bold text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none transition-colors" />
                    </div>
                </div>

                <div className="space-y-6">
                    <div>
                        <h4 className="text-sm font-black text-slate-500 uppercase tracking-widest mb-4">기간 합계 그래프</h4>
                        <div className="h-48 flex items-end justify-between gap-4 px-4 pb-2 border-b border-slate-200">
                            {[
                                { label: '현금', value: totals.cash, color: 'bg-green-500', text: 'text-green-600' },
                                { label: '계좌', value: totals.transfer, color: 'bg-blue-500', text: 'text-blue-600' },
                                { label: '카드', value: totals.card, color: 'bg-purple-500', text: 'text-purple-600' },
                                { label: '어음', value: totals.note, color: 'bg-orange-500', text: 'text-orange-600' }
                            ].map((item) => (
                                <div key={item.label} className="flex flex-col items-center flex-1 h-full justify-end group">
                                    <div className="text-xs font-bold mb-1 opacity-0 group-hover:opacity-100 transition-opacity">{item.value.toLocaleString()}</div>
                                    <div style={{ height: `${(item.value / maxVal) * 100}%` }} className={`w-full max-w-[60px] rounded-t-lg transition-all duration-500 ${item.color} opacity-80 group-hover:opacity-100 relative`}></div>
                                    <div className={`mt-2 font-bold text-sm ${item.text}`}>{item.label}</div>
