            {filtered.map(c => (
               <div key={c.id} onClick={() => onSelectForOrder && onSelectForOrder(c.name)} className={`flex justify-between items-center p-3 border-b hover:bg-slate-50 ${onSelectForOrder ? 'cursor-pointer active:bg-blue-50' : ''}`}>
