                        {c.shortcut && <span className="text-xs bg-slate-100 px-1.5 py-0.5 rounded text-slate-500">{c.shortcut}</span>}
                     </div>
                     <div className="text-xs text-slate-400 mt-0.5">{c.category} | {c.phone}</div>
