               </div>
            ))}
         </div>
      </div>
    </div>
  );
};

const OrderModal: React.FC<{
  onClose: () => void,
  onSubmit: (client: string, items: string, memo: string) => void,
  selectedDate: string,
  products: ProductDefinition[],
  clients: ClientDefinition[],
  initialClientName: string,
  initialItemsStr: string,
  initialMemo: string,
  isEditing: boolean,
  onOpenProductManager: (c: string, i: string, m: string) => void,
  onOpenClientManager: (c: string, i: string, m: string) => void
}> = ({ onClose, onSubmit, selectedDate, products, clients, initialClientName, initialItemsStr, initialMemo, isEditing, onOpenProductManager, onOpenClientManager }) => {
  const [clientName, setClientName] = useState(initialClientName);
  const [itemsStr, setItemsStr] = useState(initialItemsStr);
  const [memo, setMemo] = useState(initialMemo);

  const [filteredClients, setFilteredClients] = useState<ClientDefinition[]>([]);
  const [showClientSuggestions, setShowClientSuggestions] = useState(false);

  useEffect(() => {
    if (clientName && showClientSuggestions) {
        const matches = clients.filter(c => c.name.includes(clientName) || (c.shortcut && c.shortcut.includes(clientName)));
        setFilteredClients(matches.slice(0, 5));
    } else {
        setFilteredClients([]);
    }
  }, [clientName, clients, showClientSuggestions]);

  const handleSubmit = () => {
      if(!clientName.trim()) return alert('거래처명을 입력하세요.');
      if(!itemsStr.trim()) return alert('주문 내용을 입력하세요.');
      onSubmit(clientName, itemsStr, memo);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md" onClick={onClose}>
       <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden" onClick={e => e.stopPropagation()}>
          <div className="bg-slate-50 p-4 border-b border-slate-100 flex justify-between items-center">
             <div>
                <h3 className="font-bold text-lg text-slate-800">{isEditing ? '주문 수정' : '새 주문 등록'}</h3>
                <p className="text-xs text-slate-500 font-bold">{selectedDate}</p>
             </div>
             <button onClick={onClose} className="text-2xl text-slate-400 hover:text-slate-600">&times;</button>
          </div>
          <div className="p-6 space-y-5">
             <div className="space-y-1 relative">
                <label className="text-xs font-bold text-slate-500 ml-1">거래처</label>
                <div className="flex gap-2">
                    <div className="relative flex-1">
                        <input 
                            value={clientName} 
                            onChange={e => { setClientName(e.target.value); setShowClientSuggestions(true); }}
                            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-800 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all"
                            placeholder="거래처명 입력"
                        />
                        {filteredClients.length > 0 && showClientSuggestions && (
                            <div className="absolute top-full left-0 w-full bg-white border border-slate-200 rounded-xl shadow-lg mt-1 z-10 overflow-hidden">
                                {filteredClients.map(c => (
                                    <div key={c.id} 
                                        onClick={() => { setClientName(c.name); setShowClientSuggestions(false); }}
                                        className="px-4 py-2 hover:bg-blue-50 cursor-pointer text-sm font-medium border-b border-slate-50 last:border-0"
                                    >
                                        {c.name} <span className="text-xs text-slate-400 ml-2">{c.shortcut}</span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                    <button onClick={() => onOpenClientManager(clientName, itemsStr, memo)} className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 rounded-xl transition-colors">
                        <Settings className="w-5 h-5" />
                    </button>
                </div>
             </div>

             <div className="space-y-1">
                <div className="flex justify-between items-end px-1">
                    <label className="text-xs font-bold text-slate-500">주문 내용 (단축어 수량)</label>
                    <button onClick={() => onOpenProductManager(clientName, itemsStr, memo)} className="text-xs text-blue-600 font-bold hover:underline mb-1">품목 코드 확인</button>
                </div>
                <textarea 
                    value={itemsStr}
                    onChange={e => setItemsStr(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-medium text-slate-800 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all h-32 resize-none"
                    placeholder="예: 크릴5 파우다10 (띄어쓰기로 구분)"
                />
             </div>

             <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 ml-1">메모</label>
                <input 
                    value={memo}
                    onChange={e => setMemo(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-medium text-slate-800 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all"
                    placeholder="특이사항 입력"
                />
             </div>

             <button onClick={handleSubmit} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-xl shadow-lg shadow-blue-200 transition-transform active:scale-95 text-lg">
                {isEditing ? '수정 완료' : '주문 등록'}
             </button>
          </div>
       </div>
    </div>
  );
};

