const PRODUCT_CATEGORIES = ['크릴', '파우다', '미끼', '생물미끼', '조구', '기타'];
const CLIENT_CATEGORIES = ['마산', '통영', '거제'];

// Helper for Korean Chosung search
const getChosung = (str: string) => {
  const cho = ["ㄱ","ㄲ","ㄴ","ㄷ","ㄸ","ㄹ","ㅁ","ㅂ","ㅃ","ㅅ","ㅆ","ㅇ","ㅈ","ㅉ","ㅊ","ㅋ","ㅌ","ㅍ","ㅎ"];
  let result = "";
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i) - 44032;
    if (code > -1 && code < 11172) result += cho[Math.floor(code / 588)];
    else result += str.charAt(i);
  }
  return result;
};

type WidgetType = 'CALENDAR' | 'SUMMARY' | 'ORDER_LIST' | 'DAILY_CLOSING';

const App: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('smart_orders_v11'); 
    return saved ? JSON.parse(saved) : [];
  });

  const [products, setProducts] = useState<ProductDefinition[]>(() => {
    const saved = localStorage.getItem('smart_products_v11');
    return saved ? JSON.parse(saved) : []; 
  });

  const [clients, setClients] = useState<ClientDefinition[]>(() => {
    const saved = localStorage.getItem('smart_clients_v11');
    return saved ? JSON.parse(saved) : []; 
  });

  const [financials, setFinancials] = useState<FinancialRecord[]>(() => {
    const saved = localStorage.getItem('smart_financials_v11');
    return saved ? JSON.parse(saved) : [];
  });

  // Widget State
  const [layoutOrder, setLayoutOrder] = useState<WidgetType[]>(() => {
    const saved = localStorage.getItem('smart_layout_v11');
    return saved ? JSON.parse(saved) : ['CALENDAR', 'SUMMARY', 'ORDER_LIST', 'DAILY_CLOSING'];
  });

  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(() => {
    const d = new Date();
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  });

  const [showOrderForm, setShowOrderForm] = useState(false);
  const [showProductManager, setShowProductManager] = useState(false);
  const [showClientManager, setShowClientManager] = useState(false);
  const [showDataManager, setShowDataManager] = useState(false);
  const [showClosingManager, setShowClosingManager] = useState(false);
  const [summaryItemDetail, setSummaryItemDetail] = useState<{ name: string, category: string } | null>(null);

  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Drag states
  const [draggedOrderId, setDraggedOrderId] = useState<string | null>(null);
  const [draggedWidget, setDraggedWidget] = useState<WidgetType | null>(null);

  const [editingOrder, setEditingOrder] = useState<Order | null>(null);

  // Draft state for OrderForm (to preserve data when switching modals)
  const [orderDraft, setOrderDraft] = useState<{ clientName: string, itemsStr: string, memo: string } | null>(null);

  useEffect(() => { localStorage.setItem('smart_orders_v11', JSON.stringify(orders)); }, [orders]);
  useEffect(() => { localStorage.setItem('smart_products_v11', JSON.stringify(products)); }, [products]);
  useEffect(() => { localStorage.setItem('smart_clients_v11', JSON.stringify(clients)); }, [clients]);
  useEffect(() => { localStorage.setItem('smart_financials_v11', JSON.stringify(financials)); }, [financials]);
  useEffect(() => { localStorage.setItem('smart_layout_v11', JSON.stringify(layoutOrder)); }, [layoutOrder]);

  function formatDate(date: Date) {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  const getHolidayName = (date: Date) => {
    const fullDate = formatDate(date);
    const monthDay = fullDate.substring(5);
    return HOLIDAYS[fullDate] || HOLIDAYS[monthDay] || null;
  };

  const monthYear = useMemo(() => {
    return currentDate.toLocaleString('ko-KR', { month: 'long', year: 'numeric' });
  }, [currentDate]);

  const daysInMonth = useMemo(() => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) days.push(new Date(year, month, i));
    return days;
  }, [currentDate]);

  const handlePrevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const handleNextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const parseShortcuts = (input: string): OrderItem[] => {
    const parts = input.split(/[\s,]+/).map(p => p.trim()).filter(p => p !== "");
    const parsedItems: OrderItem[] = [];

    parts.forEach(part => {
      const match = part.match(/^([a-zA-Z가-힣]+)([\d]+(\.\d)?)$/);
      if (match) {
        const shortcut = match[1].toUpperCase();
        const unitQty = parseFloat(match[2]) || 0;
        const product = products.find(p => p.shortcut.toUpperCase() === shortcut);
        if (product) {
          parsedItems.push({
            id: Math.random().toString(36).substr(2, 9),
            productId: product.id,
            name: product.name,
            category: product.category,
            unitQuantity: unitQty,
            isLoaded: false
          });
        }
      }
    });
    return parsedItems;
  };

  const reconstructItemsStr = (items: OrderItem[]) => {
    return items.map(i => {
        const p = products.find(prod => prod.id === i.productId);
        const code = p ? p.shortcut : i.name;
        return `${code}${i.unitQuantity}`;
    }).join(' ');
  };

  const handleSaveOrder = (clientName: string, itemsStr: string, memo: string) => {
    if (!selectedDate || !clientName || !itemsStr) return;
    const items = parseShortcuts(itemsStr);
    if (items.length === 0) return;

    if (editingOrder) {
      setOrders(prev => prev.map(o => o.id === editingOrder.id ? { ...o, clientName, items, memo } : o));
      setEditingOrder(null);
    } else {
      const newOrder: Order = {
        id: Math.random().toString(36).substr(2, 9),
        clientName,
        date: selectedDate,
        createdAt: Date.now(),
        items,
        memo
      };
      setOrders(prev => [...prev, newOrder]);
    }
    setShowOrderForm(false);
    setOrderDraft(null); // Clear draft after save
  };

  const deleteOrder = (e: React.MouseEvent, orderId: string) => {
    e.stopPropagation();
    if (confirm('이 주문을 삭제하시겠습니까?')) {
      setOrders(prev => prev.filter(o => o.id !== orderId));
    }
  };

  const startEditOrder = (order: Order) => {
    setEditingOrder(order);
    setShowOrderForm(true);
  };

  const toggleItemLoaded = (orderId: string, itemId: string) => {
    setOrders(prev => prev.map(order => {
      if (order.id !== orderId) return order;
      return {
        ...order,
        items: order.items.map(item => item.id === itemId ? { ...item, isLoaded: !item.isLoaded } : item)
      };
    }));
  };

  const updateFinancialRecord = (date: string, field: keyof FinancialRecord, value: string) => {
    const numValue = parseInt(value.replace(/,/g, ''), 10) || 0;
    setFinancials(prev => {
      const existing = prev.find(f => f.date === date);
      if (existing) {
        return prev.map(f => f.date === date ? { ...f, [field]: numValue } : f);
      } else {
        return [...prev, { date, cash: 0, transfer: 0, card: 0, note: 0, [field]: numValue } as FinancialRecord];
      }
    });
  };

  const selectedDateOrders = useMemo(() => {
    if (!selectedDate) return [];
    return orders.filter(o => o.date === selectedDate);
  }, [orders, selectedDate]);

  const selectedFinancial = useMemo(() => {
    if (!selectedDate) return { cash: 0, transfer: 0, card: 0, note: 0 };
    return financials.find(f => f.date === selectedDate) || { cash: 0, transfer: 0, card: 0, note: 0 };
  }, [financials, selectedDate]);

  const categoryTotals = useMemo(() => {
    const totals: Record<string, Record<string, number>> = {};
    selectedDateOrders.forEach(o => {
      o.items.forEach(i => {
        const cat = i.category || '기타';
        if (!totals[cat]) totals[cat] = {};
        if (!totals[cat][i.name]) totals[cat][i.name] = 0;
        totals[cat][i.name] += i.unitQuantity;
      });
    });
    return totals;
  }, [selectedDateOrders]);

  const fetchAiAdvice = async () => {
    if (selectedDateOrders.length === 0) return;
    setIsAiLoading(true);
    const advice = await getSmartLoadingAdvice(selectedDateOrders);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // --- Order Drag & Drop Handlers ---
  const handleDragStart = (e: React.DragEvent, id: string) => {
    e.stopPropagation(); // Prevent widget drag
    setDraggedOrderId(id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (!draggedOrderId || draggedOrderId === id) return;

    // Ensure we are not dragging a widget
    if (draggedWidget) return;

    const newOrders = [...orders];
    const draggedIdx = newOrders.findIndex(o => o.id === draggedOrderId);
    const targetIdx = newOrders.findIndex(o => o.id === id);
    if (draggedIdx > -1 && targetIdx > -1) {
      const [draggedItem] = newOrders.splice(draggedIdx, 1);
      newOrders.splice(targetIdx, 0, draggedItem);
      setOrders(newOrders);
    }
  };

  const handleDragEnd = () => setDraggedOrderId(null);

  // --- Widget Drag & Drop Handlers ---
  const handleWidgetDragStart = (e: React.DragEvent, type: WidgetType) => {
    e.stopPropagation();
    setDraggedWidget(type);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleWidgetDragOver = (e: React.DragEvent, targetType: WidgetType) => {
    e.preventDefault();
    e.stopPropagation();

    // Ensure we are dragging a widget, not an order
    if (!draggedWidget || draggedWidget === targetType || draggedOrderId) return;

    const newLayout = [...layoutOrder];
    const draggedIdx = newLayout.indexOf(draggedWidget);
    const targetIdx = newLayout.indexOf(targetType);

    if (draggedIdx > -1 && targetIdx > -1) {
      newLayout.splice(draggedIdx, 1);
      newLayout.splice(targetIdx, 0, draggedWidget);
      setLayoutOrder(newLayout);
    }
  };

  const handleWidgetDragEnd = () => {
    setDraggedWidget(null);
  };

  const handleImportData = (data: any, message?: string) => {
    if (data.orders) setOrders(data.orders);
    if (data.products) setProducts(data.products);
    if (data.clients) setClients(data.clients);
    if (data.financials) setFinancials(data.financials);
    setShowDataManager(false);
    alert(message || '데이터가 성공적으로 복원되었습니다.');
  };

  const handleSelectClientForOrder = (clientName: string) => {
    setOrderDraft(prev => ({ 
        clientName: clientName, 
        itemsStr: prev?.itemsStr || '',
        memo: prev?.memo || ''
    }));
    setShowClientManager(false);
    setShowOrderForm(true);
  };

  const handleSelectProductForOrder = (product: ProductDefinition) => {
      setOrderDraft(prev => ({
          clientName: prev?.clientName || '',
          itemsStr: (prev?.itemsStr ? prev.itemsStr + ' ' : '') + product.shortcut,
          memo: prev?.memo || ''
      }));
      setShowProductManager(false);
      setShowOrderForm(true);
  };

  const handleOpenProductManagerFromOrder = (currentClientName: string, currentItemsStr: string, currentMemo: string) => {
      setOrderDraft({ clientName: currentClientName, itemsStr: currentItemsStr, memo: currentMemo });
      setShowOrderForm(false);
      setShowProductManager(true);
  };

  const handleOpenClientManagerFromOrder = (currentClientName: string, currentItemsStr: string, currentMemo: string) => {
      setOrderDraft({ clientName: currentClientName, itemsStr: currentItemsStr, memo: currentMemo });
      setShowOrderForm(false);
      setShowClientManager(true);
  };

  const handleCloseOrderForm = () => {
      setShowOrderForm(false); 
      setEditingOrder(null); 
      setOrderDraft(null);
  };

  const renderCalendar = () => (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="calendar-grid bg-slate-50 border-b border-slate-200">
        {['일', '월', '화', '수', '목', '금', '토'].map((day, idx) => (
          <div key={day} className={`py-3 text-center text-sm font-bold uppercase tracking-wider ${idx === 0 ? 'text-red-500' : idx === 6 ? 'text-blue-500' : 'text-slate-400'}`}>{day}</div>
        ))}
      </div>
      <div className="calendar-grid divide-x divide-y divide-slate-100">
        {daysInMonth.map((date, idx) => {
          if (!date) return <div key={`empty-${idx}`} className="h-24 md:h-32 bg-slate-50/30" />;
          const dateStr = formatDate(date);
          const dayOrders = orders.filter(o => o.date === dateStr);
          const isSelected = selectedDate === dateStr;
          const isToday = formatDate(new Date()) === dateStr;
          const holidayName = getHolidayName(date);
          const dayOfWeek = date.getDay();
          const isSunday = dayOfWeek === 0;
          const isSaturday = dayOfWeek === 6;
          const fin = financials.find(f => f.date === dateStr);
          const hasFinancial = fin && (fin.cash > 0 || fin.transfer > 0 || fin.card > 0 || fin.note > 0);

          return (
            <div key={dateStr} onClick={() => setSelectedDate(dateStr)} className={`h-24 md:h-32 p-2 cursor-pointer transition-all hover:bg-blue-50/40 relative ${isSelected ? 'bg-blue-50 ring-2 ring-blue-500 ring-inset z-10' : ''}`}>
              <div className="flex justify-between items-start">
                <div className="flex flex-col items-center">
                  <span className={`text-base font-bold ${isToday ? 'bg-blue-600 text-white w-7 h-7 rounded-full flex items-center justify-center' : holidayName || isSunday ? 'text-red-500' : isSaturday ? 'text-blue-500' : 'text-slate-500'}`}>{date.getDate()}</span>
                  {holidayName && <span className="text-[11px] text-red-400 font-bold mt-0.5 truncate max-w-[45px]">{holidayName}</span>}
                </div>
                {dayOrders.length > 0 && <span className="bg-blue-100 text-blue-700 text-xs px-2 py-0.5 rounded-full font-bold">{dayOrders.length}</span>}
              </div>
              <div className="mt-2 space-y-1 overflow-hidden">
                {hasFinancial && (
                    <div className="flex gap-0.5 justify-center mb-1">
                        <div className="w-1.5 h-1.5 rounded-full bg-green-400" title="매출 입력됨"></div>
                    </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );

  const renderSummary = () => (
    <div className="bg-blue-900 rounded-2xl p-5 text-white shadow-xl">
      <div className="flex justify-between items-center mb-4 border-b border-blue-800/50 pb-2">
         <h4 className="text-sm font-black uppercase tracking-widest opacity-80">카테고리별 품목 합계</h4>
         <div className="text-xs text-blue-300 font-medium">{selectedDate} 기준</div>
      </div>
      {Object.keys(categoryTotals).length === 0 ? (
          <p className="text-sm text-blue-300 py-2">등록된 주문 내역이 없습니다.</p>
      ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {Object.entries(categoryTotals).map(([category, items]) => (
              <div key={category} className="space-y-1">
                <div className="text-xs font-black text-blue-400 uppercase mb-1">{category}</div>
                {Object.entries(items).map(([name, count]) => (
                  <div key={name} 
                       onClick={() => setSummaryItemDetail({ name, category })}
                       className="flex justify-between items-center text-sm cursor-pointer hover:bg-white/10 p-1 rounded transition-colors -mx-1"
                  >
                    <span className="font-medium opacity-90">{name}</span>
                    <span className="font-bold text-white">{Number((count as number).toFixed(1))}</span>
                  </div>
                ))}
              </div>
            ))}
          </div>
      )}
    </div>
  );

  const renderOrderList = () => (
    <div className="space-y-4">
      {selectedDateOrders.length === 0 ? (
        <div className="flex flex-col items-center justify-center text-center py-12 bg-white rounded-2xl border border-dashed border-slate-200">
          <Truck className="w-12 h-12 text-slate-200 mb-3" />
          <p className="font-bold text-slate-400">등록된 주문이 없습니다.</p>
          <button onClick={() => setShowOrderForm(true)} className="mt-4 text-sm text-blue-600 font-bold hover:underline">주문 추가하기</button>
        </div>
      ) : (
        selectedDateOrders.map(order => {
          const totalQty = order.items.reduce((sum, i) => sum + i.unitQuantity, 0);
          return (
            <div key={order.id} draggable onDragStart={(e) => handleDragStart(e, order.id)} onDragOver={(e) => handleDragOver(e, order.id)} onDragEnd={handleDragEnd}
              className={`bg-white border-2 border-slate-100 rounded-2xl overflow-hidden shadow-sm hover:border-blue-200 transition-colors ${draggedOrderId === order.id ? 'opacity-40 grayscale' : ''}`}>
              <div className="px-4 py-2 bg-slate-50 flex justify-between items-center border-b border-slate-100">
                <div className="flex items-center gap-2">
                  <div className="cursor-grab active:cursor-grabbing text-slate-300 hover:text-blue-400"><GripVertical className="w-4 h-4" /></div>
                  <span className="font-black text-base text-slate-800">{order.clientName}</span>
                </div>
                <div className="flex gap-1">
                  <button onClick={() => startEditOrder(order)} className="text-slate-300 hover:text-blue-500 p-1"><Pencil className="w-4 h-4" /></button>
                  <button onClick={(e) => deleteOrder(e, order.id)} className="text-slate-300 hover:text-red-500 p-1"><Trash className="w-4 h-4" /></button>
                </div>
              </div>
              <div className="p-1.5 space-y-0.5">
                {order.items.map(item => (
                  <div key={item.id} onClick={() => toggleItemLoaded(order.id, item.id)}
                    className={`flex items-center gap-2 px-2 py-1.5 rounded-lg cursor-pointer transition-all border ${item.isLoaded ? 'bg-green-50 border-green-100' : 'bg-white hover:bg-slate-50 border-transparent'}`}>
                    <div className={`w-5 h-5 flex-shrink-0 rounded-md border-2 flex items-center justify-center transition-all ${item.isLoaded ? 'bg-green-500 border-green-500 text-white' : 'border-slate-200'}`}>
                      {item.isLoaded && <CheckCircle className="w-3.5 h-3.5" />}
                    </div>
                    <div className="flex-1 flex justify-between items-center gap-2 overflow-hidden">
                      <div className={`flex flex-col ${item.isLoaded ? 'opacity-40' : ''}`}>
                        <span className="text-[10px] font-black text-blue-500 uppercase">{item.category}</span>
                        <span className={`text-sm font-bold truncate ${item.isLoaded ? 'line-through text-green-800' : 'text-slate-700'}`}>{item.name}</span>
                      </div>
                      <div className={`flex-shrink-0 text-xs font-black px-1.5 py-0.5 rounded-md ${item.isLoaded ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-600'}`}>{item.unitQuantity}</div>
                    </div>
                  </div>
                ))}
              </div>
              {order.memo && (
                <div className="px-4 py-2 border-t border-slate-50 bg-slate-50/30">
                  <p className="text-xs text-slate-500 font-medium italic">* {order.memo}</p>
                </div>
              )}
              <div className="bg-slate-50 px-4 py-2 border-t border-slate-100 flex justify-end items-center gap-2">
                  <span className="text-xs font-bold text-slate-400">합계</span>
                  <span className="text-sm font-black text-slate-800">{Number(totalQty.toFixed(1))} 개</span>
              </div>
            </div>
          );
        })
      )}
    </div>
  );

  const renderDailyClosing = () => {
    if (!selectedDate) return null;
    return (
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-5">
        <h4 className="text-lg font-black text-slate-800 mb-4 flex items-center gap-2">
            <CheckCircle className="w-5 h-5 text-green-500" />
            일일 마감 (매출 입력)
        </h4>
        <div className="grid grid-cols-2 gap-4 mb-4">
            <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500">현금</label>
                <input type="text" 
                    value={selectedFinancial.cash.toLocaleString()} 
                    onChange={e => updateFinancialRecord(selectedDate, 'cash', e.target.value)}
                    className="w-full bg-slate-100 border border-slate-300 rounded-lg p-2 text-right font-black text-slate-900 focus:bg-white focus:ring-2 focus:ring-green-500 outline-none transition-colors" 
                    placeholder="0" />
            </div>
            <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500">계좌이체</label>
                <input type="text" 
                    value={selectedFinancial.transfer.toLocaleString()} 
                    onChange={e => updateFinancialRecord(selectedDate, 'transfer', e.target.value)}
                    className="w-full bg-slate-100 border border-slate-300 rounded-lg p-2 text-right font-black text-slate-900 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-colors" 
                    placeholder="0" />
            </div>
            <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500">카드</label>
                <input type="text" 
                    value={selectedFinancial.card.toLocaleString()} 
                    onChange={e => updateFinancialRecord(selectedDate, 'card', e.target.value)}
                    className="w-full bg-slate-100 border border-slate-300 rounded-lg p-2 text-right font-black text-slate-900 focus:bg-white focus:ring-2 focus:ring-purple-500 outline-none transition-colors" 
                    placeholder="0" />
            </div>
            <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500">어음</label>
                <input type="text" 
                    value={selectedFinancial.note.toLocaleString()} 
                    onChange={e => updateFinancialRecord(selectedDate, 'note', e.target.value)}
                    className="w-full bg-slate-100 border border-slate-300 rounded-lg p-2 text-right font-black text-slate-900 focus:bg-white focus:ring-2 focus:ring-orange-500 outline-none transition-colors" 
                    placeholder="0" />
            </div>
        </div>
        <div className="flex justify-between items-center py-2 border-t border-slate-100">
            <span className="font-bold text-slate-500">총 합계</span>
            <span className="font-black text-xl text-slate-800">
                {(selectedFinancial.cash + selectedFinancial.transfer + selectedFinancial.card + selectedFinancial.note).toLocaleString()}원
            </span>
        </div>

        <div className="mt-4 p-4 bg-slate-900 rounded-xl text-white">
            <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-bold text-blue-300 tracking-widest">AI 상차 분석</span>
                {!aiAdvice && !isAiLoading && <button onClick={fetchAiAdvice} className="text-xs bg-blue-600 px-2 py-1 rounded font-bold hover:bg-blue-500">분석 실행</button>}
            </div>
            {isAiLoading ? (
                <div className="space-y-1 opacity-50"><div className="h-1.5 bg-slate-700 rounded w-full animate-pulse" /><div className="h-1.5 bg-slate-700 rounded w-2/3 animate-pulse" /></div> 
            ) : aiAdvice ? (
                <p className="text-sm leading-relaxed font-medium text-slate-300">"{aiAdvice}"</p>
            ) : (
                <p className="text-xs text-slate-500">분석 실행을 눌러 상차 팁을 확인하세요.</p>
            )}
        </div>
      </div>
    );
  };

  const getWidgetTitle = (type: WidgetType) => {
    switch (type) {
      case 'CALENDAR': return `${monthYear} 캘린더`;
      case 'SUMMARY': return '카테고리별 주문 합계';
      case 'ORDER_LIST': return `${selectedDate} 주문 목록 (${selectedDateOrders.length})`;
      case 'DAILY_CLOSING': return '일일 마감';
      default: return '';
    }
  };

  const getWidgetContent = (type: WidgetType) => {
    switch (type) {
      case 'CALENDAR': return renderCalendar();
      case 'SUMMARY': return renderSummary();
      case 'ORDER_LIST': return renderOrderList();
      case 'DAILY_CLOSING': return renderDailyClosing();
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900 pb-20">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-4 py-4 md:px-8 shadow-sm">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg text-white shadow-lg shadow-blue-200">
              <Truck className="w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 hidden sm:block">스마트 상차 플래너</h1>
          </div>
          <div className="flex items-center gap-2">
            <div className="flex items-center bg-slate-100 rounded-lg p-1">
              <button onClick={handlePrevMonth} className="p-1.5 hover:bg-white rounded-md transition-all shadow-sm"><ChevronLeft className="w-4 h-4" /></button>
              <span className="text-sm font-bold text-slate-700 w-24 text-center">{monthYear}</span>
              <button onClick={handleNextMonth} className="p-1.5 hover:bg-white rounded-md transition-all shadow-sm"><ChevronRight className="w-4 h-4" /></button>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full p-4 space-y-6">
        <div className="flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm border border-slate-200">
           <div>
              <h2 className="text-2xl font-black text-slate-800">{selectedDate}</h2>
              <p className="text-xs font-bold text-slate-400">TODAY SCHEDULE</p>
           </div>
           <button onClick={() => setShowOrderForm(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2.5 rounded-xl font-bold shadow-lg shadow-blue-100 transition-transform active:scale-95 flex items-center gap-2">
             <Plus className="w-5 h-5" />
             <span>주문 추가</span>
           </button>
        </div>

        <div className="grid grid-cols-4 gap-2">
          <button onClick={() => setShowClientManager(true)} className="text-xs font-bold text-slate-500 hover:text-blue-600 bg-white border border-slate-200 px-2 py-3 rounded-xl transition-all shadow-sm flex flex-col items-center justify-center gap-1">
             <span>거래처조회</span>
          </button>
          <button onClick={() => setShowProductManager(true)} className="text-xs font-bold text-slate-500 hover:text-blue-600 bg-white border border-slate-200 px-2 py-3 rounded-xl transition-all shadow-sm flex flex-col items-center justify-center gap-1">
             <span>상품조회</span>
          </button>
          <button onClick={() => setShowClosingManager(true)} className="text-xs font-bold text-slate-500 hover:text-blue-600 bg-white border border-slate-200 px-2 py-3 rounded-xl transition-all shadow-sm flex flex-col items-center justify-center gap-1">
             <span>마감등록</span>
          </button>
          <button onClick={() => setShowDataManager(true)} className="text-xs font-bold text-slate-500 hover:text-blue-600 bg-white border border-slate-200 px-2 py-3 rounded-xl transition-all shadow-sm flex flex-col items-center justify-center gap-1">
             <span>데이터</span>
          </button>
        </div>

        {layoutOrder.map((type, index) => (
          <DashboardWidget 
            key={type} 
            title={getWidgetTitle(type)}
            type={type}
            onDragStart={handleWidgetDragStart}
            onDragOver={handleWidgetDragOver}
            onDragEnd={handleWidgetDragEnd}
            isDragging={draggedWidget === type}
          >
            {getWidgetContent(type)}
          </DashboardWidget>
        ))}
      </main>

      {showProductManager && <ProductManagerModal products={products} setProducts={setProducts} onClose={() => setShowProductManager(false)} onSelectForOrder={handleSelectProductForOrder} />}
      {showClientManager && <ClientManagerModal clients={clients} setClients={setClients} onClose={() => setShowClientManager(false)} onSelectForOrder={handleSelectClientForOrder} />}
      {showDataManager && <DataManagerModal orders={orders} products={products} clients={clients} financials={financials} onImport={handleImportData} onClose={() => setShowDataManager(false)} />}
      {showClosingManager && <ClosingManagerModal financials={financials} onClose={() => setShowClosingManager(false)} />}
      {showOrderForm && (
        <OrderModal 
          onClose={handleCloseOrderForm} 
          onSubmit={handleSaveOrder} 
          selectedDate={selectedDate || ""} 
          products={products} 
          clients={clients} 
          initialClientName={editingOrder ? editingOrder.clientName : (orderDraft?.clientName || '')} 
          initialItemsStr={editingOrder ? reconstructItemsStr(editingOrder.items) : (orderDraft?.itemsStr || '')} 
          initialMemo={editingOrder ? (editingOrder.memo || '') : (orderDraft?.memo || '')}
          isEditing={!!editingOrder} 
          onOpenProductManager={handleOpenProductManagerFromOrder} 
          onOpenClientManager={handleOpenClientManagerFromOrder} 
        />
      )}
      {summaryItemDetail && (
        <SummaryDetailModal
          itemName={summaryItemDetail.name}
          category={summaryItemDetail.category}
          orders={selectedDateOrders}
          onClose={() => setSummaryItemDetail(null)}
        />
      )}
    </div>
  );
};

const DashboardWidget: React.FC<{ 
  title: string, 
  children: React.ReactNode, 
  type: WidgetType,
  onDragStart: (e: React.DragEvent, type: WidgetType) => void,
  onDragOver: (e: React.DragEvent, type: WidgetType) => void,
  onDragEnd: () => void,
  isDragging: boolean
}> = ({ title, children, type, onDragStart, onDragOver, onDragEnd, isDragging }) => {
  const [isCollapsed, setIsCollapsed] = useState(false);

  return (
    <div 
        draggable
        onDragStart={(e) => onDragStart(e, type)}
        onDragOver={(e) => onDragOver(e, type)}
        onDragEnd={onDragEnd}
        className={`flex flex-col gap-2 transition-opacity duration-200 ${isDragging ? 'opacity-40' : 'opacity-100'}`}
    >
      <div className="flex justify-between items-center px-2 cursor-grab active:cursor-grabbing">
         <div className="flex items-center gap-2">
            <div className="text-slate-300"><GripVertical className="w-5 h-5" /></div>
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest select-none">{title}</h3>
         </div>
         <div className="flex items-center gap-1">
            <button onClick={() => setIsCollapsed(!isCollapsed)} className="p-1 text-slate-300 hover:text-slate-600 transition-colors ml-2">
              {isCollapsed ? <Plus className="w-4 h-4" /> : <div className="w-4 h-0.5 bg-current my-2 mx-0" />}
            </button>
         </div>
      </div>
      {!isCollapsed && (
        <div className="animate-fade-in">
          {children}
        </div>
      )}
    </div>
  );
};

