      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col max-h-[85vh]" onClick={e => e.stopPropagation()}>
        <div className="p-6 border-b border-slate-100 flex justify-between items-center">
            <h3 className="text-xl font-black text-slate-800">품목 관리</h3>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-3xl">&times;</button>
