                     {isSyncing ? '전송중...' : '시트로 내보내기'}
                 </button>
                 <button onClick={handleLoadFromSheet} disabled={isSyncing} className="bg-amber-100 text-amber-700 font-bold py-3 rounded-xl hover:bg-amber-200 disabled:opacity-50">
