        {/* Header */}
        <header className="flex justify-between items-end mb-2">
          <div>
            <h1 className="text-2xl font-black text-slate-800">Smart Order <span className="text-blue-500 text-base align-top">v11</span></h1>
            <p className="text-sm text-slate-500 font-medium">{monthYear}</p>
          </div>
          <div className="flex gap-2">
             <button onClick={() => setShowDataManager(true)} className="p-2 bg-white rounded-xl text-slate-400 hover:text-blue-600 shadow-sm transition-colors"><Settings /></button>
          </div>
        </header>

        {/* Date Navigator */}
        <div className="flex items-center justify-between bg-white p-2 rounded-2xl shadow-sm">
            <button onClick={handlePrevMonth} className="p-2 hover:bg-slate-50 rounded-xl text-slate-500"><ChevronLeft /></button>
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setSelectedDate(formatDate(new Date()))}>
                <span className="font-black text-lg text-slate-800">{currentDate.getFullYear()}년 {currentDate.getMonth() + 1}월</span>
                {selectedDate === formatDate(new Date()) && <span className="text-[10px] bg-red-100 text-red-600 px-1.5 py-0.5 rounded-full font-bold">TODAY</span>}
            </div>
            <button onClick={handleNextMonth} className="p-2 hover:bg-slate-50 rounded-xl text-slate-500"><ChevronRight /></button>
        </div>

        {/* AI Advice Banner */}
        <div className="bg-gradient-to-r from-indigo-600 to-blue-600 rounded-2xl p-5 text-white shadow-lg relative overflow-hidden">
            <div className="relative z-10">
