                    <h3 className="font-bold text-lg flex items-center gap-2">✨ AI 스마트 배차 조언</h3>
                    <button onClick={fetchAiAdvice} disabled={isAiLoading} className="text-xs bg-white/20 hover:bg-white/30 px-3 py-1.5 rounded-lg font-bold transition-colors">
                        {isAiLoading ? '분석중...' : '새로고침'}
