                                    <div className="flex justify-between items-center px-1">
                                        <h3 className="font-bold text-lg text-slate-800">주문 내역</h3>
                                        <button onClick={() => setShowOrderForm(true)} className="text-sm font-bold text-blue-600 hover:underline flex items-center gap-1">
                                            <Plus className="w-4 h-4" /> 주문 추가
                                        </button>
                                    </div>
                                    {renderOrderList()}
                                </div>
                            )}
                            {widget === 'DAILY_CLOSING' && renderDailyClosing()}
                        </div>
                    ))}
                </div>
            </div>

            {/* Sidebar / Quick Menu */}
            <div className="space-y-4">
                <div className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                    <h3 className="font-bold text-slate-400 text-xs uppercase mb-3">Quick Menu</h3>
                    <div className="grid grid-cols-2 gap-3">
                        <button onClick={() => setShowProductManager(true)} className="p-3 bg-slate-50 hover:bg-blue-50 hover:text-blue-600 rounded-xl font-bold text-sm text-slate-600 transition-colors">품목 관리</button>
                        <button onClick={() => setShowClientManager(true)} className="p-3 bg-slate-50 hover:bg-blue-50 hover:text-blue-600 rounded-xl font-bold text-sm text-slate-600 transition-colors">거래처 관리</button>
                        <button onClick={() => setShowClosingManager(true)} className="p-3 bg-slate-50 hover:bg-blue-50 hover:text-blue-600 rounded-xl font-bold text-sm text-slate-600 transition-colors">마감 관리</button>
                        <button onClick={() => window.print()} className="p-3 bg-slate-50 hover:bg-blue-50 hover:text-blue-600 rounded-xl font-bold text-sm text-slate-600 transition-colors">인쇄</button>
