                            <input 
                                autoFocus
                                value={orderDraft?.clientName || editingOrder?.clientName || ''}
                                onChange={(e) => setOrderDraft(prev => ({ ...prev!, clientName: e.target.value, itemsStr: prev?.itemsStr || '', memo: prev?.memo || '' }))}
                                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold focus:outline-none focus:ring-2 focus:ring-blue-500" 
