                            <button onClick={() => handleOpenClientManagerFromOrder(orderDraft?.clientName || editingOrder?.clientName || '', orderDraft?.itemsStr || (editingOrder ? reconstructItemsStr(editingOrder.items) : '') || '', orderDraft?.memo || editingOrder?.memo || '')} className="px-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-sm">선택</button>
