                             <input 
                                value={orderDraft?.itemsStr || (editingOrder && !orderDraft ? reconstructItemsStr(editingOrder.items) : '') || ''}
                                onChange={(e) => setOrderDraft(prev => ({ ...prev!, itemsStr: e.target.value, clientName: prev?.clientName || '', memo: prev?.memo || '' }))}
                                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-3 font-medium focus:outline-none focus:ring-2 focus:ring-blue-500" 
                                placeholder="예: 크릴10 파우다5"
                             />
                             <button onClick={() => handleOpenProductManagerFromOrder(orderDraft?.clientName || '', orderDraft?.itemsStr || '', orderDraft?.memo || '')} className="px-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-sm">목록</button>
                          </div>
                          <p className="text-xs text-slate-400 mt-1 pl-1">입력된 단축어가 자동으로 변환됩니다.</p>
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-400 mb-1">메모</label>
                          <textarea 
                             value={orderDraft?.memo || editingOrder?.memo || ''}
                             onChange={(e) => setOrderDraft(prev => ({ ...prev!, memo: e.target.value, clientName: prev?.clientName || '', itemsStr: prev?.itemsStr || '' }))}
                             className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 h-24 resize-none focus:outline-none focus:ring-2 focus:ring-blue-500"
                             placeholder="특이사항 입력"
                          />
                      </div>
                      <button 
                        onClick={() => handleSaveOrder(orderDraft?.clientName || editingOrder?.clientName || '', orderDraft?.itemsStr || (editingOrder ? reconstructItemsStr(editingOrder.items) : '') || '', orderDraft?.memo || editingOrder?.memo || '')}
                        className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl text-lg shadow-lg shadow-blue-200 transition-all mt-2"
                      >
                          저장하기
                      </button>
                  </div>
              </div>
          </div>
      )}

      {showScheduleForm && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
              <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl p-6">
                   <h3 className="font-bold text-lg mb-4">{editingSchedule ? '일정 수정' : '새 일정 등록'}</h3>
                   <form onSubmit={(e) => {
                       e.preventDefault();
                       const formData = new FormData(e.currentTarget);
                       handleSaveSchedule(formData.get('title') as string, formData.get('content') as string, formData.get('time') as string, parseInt(formData.get('alarm') as string) || 0);
                   }} className="space-y-4">
                       <input name="title" defaultValue={editingSchedule?.title} placeholder="일정 제목" className="w-full p-3 bg-slate-50 rounded-xl border border-slate-200" required autoFocus />
                       <textarea name="content" defaultValue={editingSchedule?.content} placeholder="내용" className="w-full p-3 bg-slate-50 rounded-xl border border-slate-200 h-24 resize-none" />
                       <div className="flex gap-2">
                           <input type="time" name="time" defaultValue={editingSchedule?.time} className="flex-1 p-3 bg-slate-50 rounded-xl border border-slate-200" />
                           <select name="alarm" defaultValue={editingSchedule?.alarm || 0} className="flex-1 p-3 bg-slate-50 rounded-xl border border-slate-200">
                               <option value="0">알람 없음</option>
                               <option value="10">10분 전</option>
                               <option value="30">30분 전</option>
                               <option value="60">1시간 전</option>
                           </select>
                       </div>
                       <div className="flex gap-3 pt-2">
                           <button type="button" onClick={handleCloseScheduleForm} className="flex-1 py-3 bg-slate-100 font-bold text-slate-600 rounded-xl">취소</button>
                           <button type="submit" className="flex-1 py-3 bg-blue-600 text-white font-bold rounded-xl">저장</button>
                       </div>
                   </form>
              </div>
          </div>
      )}

      {/* Simple placeholders for managers */}
      {(showProductManager || showClientManager || showDataManager || showClosingManager) && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-md rounded-2xl p-8 text-center">
               <div className="w-16 h-16 bg-blue-50 text-blue-500 rounded-full flex items-center justify-center mx-auto mb-4">
                   <Settings className="w-8 h-8" />
               </div>
               <h3 className="text-xl font-bold text-slate-800 mb-2">기능 준비중</h3>
               <p className="text-slate-500 mb-6">해당 관리자 기능은 다음 업데이트에 제공됩니다.</p>
               <button onClick={() => {
                   setShowProductManager(false);
                   setShowClientManager(false);
                   setShowDataManager(false);
                   setShowClosingManager(false);
               }} className="w-full py-3 bg-slate-100 hover:bg-slate-200 font-bold text-slate-700 rounded-xl transition-colors">확인</button>
           </div>
        </div>
      )}

      {/* Summary Detail Modal */}
      {summaryItemDetail && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-md rounded-2xl p-6">
                  <h3 className="font-bold text-lg mb-2">{summaryItemDetail.name} 상세 내역</h3>
                  <div className="max-h-60 overflow-y-auto space-y-2">
                      {selectedDateOrders.flatMap(o => o.items.filter(i => i.name === summaryItemDetail.name).map(i => ({ client: o.clientName, qty: i.unitQuantity })))
                          .map((item, idx) => (
                              <div key={idx} className="flex justify-between p-2 bg-slate-50 rounded">
                                  <span>{item.client}</span>
                                  <span className="font-bold">{item.qty}</span>
                              </div>
                          ))}
                  </div>
                  <button onClick={() => setSummaryItemDetail(null)} className="w-full mt-4 py-3 bg-blue-600 text-white font-bold rounded-xl">닫기</button>
              </div>
          </div>
      )}

    </div>
  );
};

export default App;
